t["Let's see what we can survive together."] = "\\u062E\\u0644\\u064A\\u0646\\u0627 \\u0646\\u0634\\u0648\\u0641 \\u0634\\u0648 \\u0641\\u064A\\u0646\\u0627 \\u0646\\u0646\\u062C\\u0648 \\u0645\\u0646\\u0647 \\u0633\\u0648\\u0627."
t["Let's settle the next watch and supply jobs."] = "\\u062E\\u0644\\u064A\\u0646\\u0627 \\u0646\\u062D\\u0633\\u0645 \\u0627\\u0644\\u062D\\u0631\\u0627\\u0633\\u0629 \\u0627\\u0644\\u062C\\u0627\\u064A\\u0629 \\u0648\\u0634\\u063A\\u0644 \\u0627\\u0644\\u0645\\u0648\\u0646\\u0629."
t["Let's talk tomorrow before everyone scatters, %1."] = "\\u062E\\u0644\\u064A\\u0646\\u0627 \\u0646\\u062D\\u0643\\u064A \\u0628\\u0643\\u0631\\u0627 \\u0642\\u0628\\u0644 \\u0645\\u0627 \\u064A\\u062A\\u0641\\u0631\\u0642 \\u0627\\u0644\\u0643\\u0644 \\u064A\\u0627 %1."
t["Light is going. Let's not get caught outside without a plan."] = "\\u0627\\u0644\\u0636\\u0648 \\u0639\\u0645 \\u064A\\u0631\\u0648\\u062D. \\u062E\\u0644\\u064A\\u0646\\u0627 \\u0645\\u0627 \\u0646\\u0639\\u0644\\u0642 \\u0628\\u0631\\u0627 \\u0628\\u0644\\u0627 \\u062E\\u0637\\u0629."
t["Lights out, neighbor!"] = "\\u062A\\u0635\\u0628\\u062D \\u0639\\u0644\\u0649 \\u062E\\u064A\\u0631 \\u064A\\u0627 \\u062C\\u0627\\u0631!"
t["Line is clear. Bait is set."] = "\\u0627\\u0644\\u062E\\u064A\\u0637 \\u0646\\u0636\\u064A\\u0641 \\u0648\\u0627\\u0644\\u0637\\u0639\\u0645 \\u062C\\u0627\\u0647\\u0632."
t["Listen closely:"] = "\\u0627\\u0633\\u0645\\u0639 \\u0645\\u0646\\u064A\\u062D:"
t["Listen to me. I have a bite, and we need a plan."] = "\\u0627\\u0633\\u0645\\u0639\\u0646\\u064A. \\u0645\\u0639\\u064A \\u0639\\u0636\\u0629\\u060C \\u0648\\u0644\\u0627\\u0632\\u0645 \\u0646\\u0639\\u0645\\u0644 \\u062E\\u0637\\u0629."
t["Lock it down. Two on watch, round the clock."] = "\\u0633\\u0643\\u0631\\u0648\\u0627 \\u0643\\u0644 \\u0634\\u064A. \\u0627\\u062A\\u0646\\u064A\\u0646 \\u0639\\u0627\\u0644\\u062D\\u0631\\u0627\\u0633\\u0629\\u060C \\u0644\\u064A\\u0644 \\u0646\\u0647\\u0627\\u0631."
t["Lockers full of homework. The kids finally got their wish."] = "\\u062E\\u0632\\u0627\\u064A\\u0646 \\u0645\\u0644\\u064A\\u0627\\u0646\\u0629 \\u0648\\u0638\\u0627\\u064A\\u0641. \\u0627\\u0644\\u0648\\u0644\\u0627\\u062F \\u0623\\u062E\\u064A\\u0631\\u064B\\u0627 \\u0646\\u0627\\u0644\\u0648\\u0627 \\u0623\\u0645\\u0646\\u064A\\u062A\\u0647\\u0645."
t["Lockers like these used to belong to people I knew. I don't want to open any."] = "\\u062E\\u0632\\u0627\\u064A\\u0646 \\u0645\\u062A\\u0644 \\u0647\\u064A \\u0643\\u0627\\u0646\\u062A \\u0644\\u0646\\u0627\\u0633 \\u0628\\u0639\\u0631\\u0641\\u0647\\u0645. \\u0645\\u0627 \\u0628\\u062F\\u064A \\u0627\\u0641\\u062A\\u062D \\u0648\\u0644\\u0627 \\u0648\\u062D\\u062F\\u0629."
t["Logs everywhere, saw nowhere. That's our progress report."] = "\\u062C\\u0630\\u0648\\u0639 \\u0628\\u0643\\u0644 \\u0645\\u062D\\u0644 \\u0648\\u0645\\u0646\\u0634\\u0627\\u0631 \\u0628\\u0648\\u0644\\u0627 \\u0645\\u062D\\u0644. \\u0647\\u0627\\u062F \\u062A\\u0642\\u0631\\u064A\\u0631 \\u0627\\u0644\\u0625\\u0646\\u062C\\u0627\\u0632\\u0627\\u062A."
t["Lollipops by the door. The good dentists had lollipops."] = "\\u0645\\u0635\\u0627\\u0635\\u0627\\u062A \\u062C\\u0646\\u0628 \\u0627\\u0644\\u0628\\u0627\\u0628. \\u0623\\u0637\\u0628\\u0627 \\u0627\\u0644\\u0623\\u0633\\u0646\\u0627\\u0646 \\u0627\\u0644\\u0623\\u0643\\u0627\\u0628\\u0631 \\u0643\\u0627\\u0646 \\u0639\\u0646\\u062F\\u0647\\u0645 \\u0645\\u0635\\u0627\\u0635\\u0627\\u062A."
t["Lone zombie ahead."] = "\\u0632\\u0648\\u0645\\u0628\\u064A \\u0644\\u062D\\u0627\\u0644\\u0647 \\u0642\\u062F\\u0627\\u0645\\u0646\\u0627."
t["Long day, %1. At least we made it back together."] = "\\u064A\\u0648\\u0645 \\u0637\\u0648\\u064A\\u0644 \\u064A\\u0627 %1. \\u0639\\u0627\\u0644\\u0623\\u0642\\u0644 \\u0631\\u062C\\u0639\\u0646\\u0627 \\u0633\\u0648\\u0627."
t["Look alive! One of them is close!"] = "\\u0635\\u062D\\u0635\\u062D! \\u0648\\u0627\\u062D\\u062F \\u0645\\u0646\\u0647\\u0645 \\u0642\\u0631\\u064A\\u0628!"
t["Look at me now, while I can still look back."] = "\\u0627\\u062A\\u0637\\u0644\\u0639 \\u0641\\u064A\\u064A \\u0647\\u0644\\u0623, \\u0637\\u0627\\u0644\\u0645\\u0627 \\u0644\\u0633\\u0627 \\u0628\\u0642\\u062F\\u0631 \\u0627\\u062A\\u0637\\u0644\\u0639 \\u0641\\u064A\\u0643."
t["Look at me, %1! I need your help!"] = "\\u0627\\u062A\\u0637\\u0644\\u0639 \\u0641\\u064A\\u064A \\u064A\\u0627 %1! \\u0628\\u062F\\u064A \\u0645\\u0633\\u0627\\u0639\\u062F\\u062A\\u0643!"
t["Look at me, not at the blood."] = "\\u0627\\u0637\\u0644\\u0651\\u0639 \\u0641\\u064A\\u0646\\u064A\\u060C \\u0645\\u0648 \\u0639\\u0627\\u0644\\u062F\\u0645."
t["Look at that. A proper fish."] = "\\u0634\\u0648\\u0641 \\u0647\\u0627\\u0644\\u062D\\u0644\\u0627\\u0648\\u0629. \\u0633\\u0645\\u0643\\u0629 \\u0639\\u0646 \\u062C\\u062F."
t["Look at them. No idea what is coming."] = "\\u0634\\u0648\\u0641\\u0647\\u0645. \\u0645\\u0648 \\u062F\\u0631\\u064A\\u0627\\u0646\\u064A\\u0646 \\u0634\\u0648 \\u062C\\u0627\\u064A."
t["Look at this. Just look. Then keep quiet about it."] = "\\u0634\\u0648\\u0641 \\u0647\\u064A. \\u0628\\u0633 \\u0634\\u0648\\u0641. \\u0648\\u0628\\u0639\\u062F\\u064A\\u0646 \\u0627\\u0633\\u0643\\u062A."
t["Look at us. We are still here, and we are getting better at this."] = "\\u0634\\u0648\\u0641 \\u062D\\u0627\\u0644\\u0646\\u0627. \\u0644\\u0633\\u0627 \\u0647\\u0648\\u0646\\u060C \\u0648\\u0639\\u0645 \\u0646\\u0635\\u064A\\u0631 \\u0623\\u0634\\u0637\\u0631."
t["Look up if you want. It won't look back."] = "\\u0627\\u062A\\u0637\\u0644\\u0639 \\u0644\\u0641\\u0648\\u0642 \\u0625\\u0630\\u0627 \\u0628\\u062F\\u0643. \\u0645\\u0648 \\u0631\\u062D \\u062A\\u062A\\u0637\\u0644\\u0639 \\u0641\\u064A\\u0643."
t["Loose. Back to it."] = "\\u0641\\u0644\\u062A. \\u064A\\u0644\\u0627 \\u0646\\u0643\\u0645\\u0644."
t["Lord, forgive me. Again!"] = "\\u064A\\u0627 \\u0631\\u0628 \\u0633\\u0627\\u0645\\u062D\\u0646\\u064A. \\u0643\\u0645\\u0627\\u0646 \\u0645\\u0631\\u0629!"
t["Losing %1 changed this place. It has not felt the same since."] = "\\u062E\\u0633\\u0627\\u0631\\u0629 %1 \\u063A\\u064A\\u0651\\u0631\\u062A \\u0647\\u0627\\u0644\\u0645\\u0637\\u0631\\u062D. \\u0645\\u0646 \\u0648\\u0642\\u062A\\u0647\\u0627 \\u0645\\u0648 \\u0645\\u062A\\u0644 \\u0642\\u0628\\u0644."
t["Losing your face from my memory frightens me more than dying."] = "\\u0625\\u0646 \\u064A\\u0636\\u064A\\u0639 \\u0648\\u062C\\u0647\\u0643 \\u0645\\u0646 \\u0630\\u0627\\u0643\\u0631\\u062A\\u064A \\u0628\\u062E\\u0648\\u0641\\u0646\\u064A \\u0623\\u0643\\u062A\\u0631 \\u0645\\u0646 \\u0627\\u0644\\u0645\\u0648\\u062A."
t["Loss exceeds any gain. Holding until conditions improve."] = "\\u0627\\u0644\\u062E\\u0633\\u0627\\u0631\\u0629 \\u0623\\u0643\\u0628\\u0631 \\u0645\\u0646 \\u0623\\u064A \\u0631\\u0628\\u062D. \\u0645\\u0633\\u062A\\u0646\\u064A\\u0629 \\u0644\\u062A\\u062A\\u062D\\u0633\\u0646 \\u0627\\u0644\\u0638\\u0631\\u0648\\u0641."
t["Lost it, blast it."] = "\\u0631\\u0627\\u062D\\u062A\\u060C \\u064A\\u062E\\u0631\\u0628 \\u0628\\u064A\\u062A\\u0647\\u0627."
t["Lost it, damn it."] = "\\u0631\\u0627\\u062D\\u062A\\u060C \\u064A\\u0644\\u0639\\u0646 \\u0623\\u0628\\u0648\\u0647\\u0627."
t["Lost this patch. I'll turn it over for another try."] = "\\u062E\\u0633\\u0631\\u062A \\u0647\\u0627\\u0644\\u0634\\u0642\\u0641\\u0629. \\u0631\\u062D \\u0627\\u0642\\u0644\\u0628\\u0647\\u0627 \\u0648\\u0646\\u062C\\u0631\\u0628 \\u0645\\u0631\\u0629 \\u062A\\u0627\\u0646\\u064A\\u0629."
t["Lost-and-found box. Everybody's lost now."] = "\\u0635\\u0646\\u062F\\u0648\\u0642 \\u0627\\u0644\\u0645\\u0641\\u0642\\u0648\\u062F\\u0627\\u062A. \\u0627\\u0644\\u0643\\u0644 \\u0636\\u0627\\u064A\\u0639 \\u0647\\u0644\\u0623."
t["Loud enough to wake the whole county. Most of it already died."] = "\\u0639\\u0627\\u0644\\u064A \\u0644\\u062F\\u0631\\u062C\\u0629 \\u064A\\u0641\\u064A\\u0642 \\u0627\\u0644\\u0645\\u0646\\u0637\\u0642\\u0629 \\u0643\\u0644\\u0647\\u0627. \\u0648\\u0623\\u063A\\u0644\\u0628\\u0647\\u0627 \\u0645\\u064A\\u062A \\u0623\\u0635\\u0644\\u0627\\u064B."
t["Loud is the enemy. Remember that before you fall in love in here."] = "\\u0627\\u0644\\u0635\\u0648\\u062A \\u0627\\u0644\\u0639\\u0627\\u0644\\u064A \\u0647\\u0648 \\u0627\\u0644\\u0639\\u062F\\u0648. \\u062A\\u0630\\u0643\\u0631 \\u0647\\u0627\\u0644\\u0634\\u064A \\u0642\\u0628\\u0644 \\u0645\\u0627 \\u062A\\u063A\\u0631\\u0645 \\u0628\\u0634\\u064A \\u0647\\u0648\\u0646."
t["Louisville is still out there being Louisville, with nobody in it."] = "\\u0644\\u0648\\u064A\\u0632\\u0641\\u064A\\u0644 \\u0644\\u0633\\u0627 \\u0647\\u0648\\u0646\\u064A\\u0643 \\u0639\\u0645 \\u062A\\u0639\\u064A\\u0634 \\u0644\\u0648\\u064A\\u0632\\u0641\\u064A\\u0644\\u060C \\u0628\\u0644\\u0627 \\u062D\\u062F\\u0627 \\u0641\\u064A\\u0647\\u0627."
t["Lovely day for a walk through the end of everything."] = "\\u064A\\u0648\\u0645 \\u062D\\u0644\\u0648 \\u0644\\u0644\\u0645\\u0634\\u0648\\u0627\\u0631 \\u0628\\u0646\\u0647\\u0627\\u064A\\u0629 \\u0643\\u0644 \\u0634\\u064A."
t["Low visibility. We should avoid open-ended searches."] = "\\u0627\\u0644\\u0631\\u0624\\u064A\\u0629 \\u0636\\u0639\\u064A\\u0641\\u0629. \\u0644\\u0627\\u0632\\u0645 \\u0646\\u062A\\u062C\\u0646\\u0628 \\u0627\\u0644\\u062A\\u0641\\u062A\\u064A\\u0634 \\u0627\\u0644\\u0645\\u0641\\u062A\\u0648\\u062D."
t["Lower it now if you want to keep talking!"] = "\\u0646\\u0632\\u0644\\u0647 \\u0647\\u0644\\u0623 \\u0625\\u0630\\u0627 \\u0628\\u062F\\u0643 \\u0646\\u0636\\u0644 \\u0646\\u062D\\u0643\\u064A!"
t["Lower the weapon and make your request. Entry is the household's decision."] = "\\u0646\\u0632\\u0644 \\u0627\\u0644\\u0633\\u0644\\u0627\\u062D \\u0648\\u0642\\u0648\\u0644 \\u0634\\u0648 \\u0628\\u062F\\u0643. \\u0627\\u0644\\u0641\\u0648\\u062A\\u0629 \\u0642\\u0631\\u0627\\u0631 \\u0623\\u0647\\u0644 \\u0627\\u0644\\u0628\\u064A\\u062A."
t["Lower your voice. We have enough trouble outside."] = "\\u0648\\u0637\\u0651\\u064A \\u0635\\u0648\\u062A\\u0643. \\u0639\\u0646\\u0627 \\u0645\\u0634\\u0627\\u0643\\u0644 \\u0628\\u0631\\u0627 \\u0643\\u0641\\u0627\\u064A\\u0629."
t["Lower your weapon!"] = "\\u0646\\u0632\\u0651\\u0644 \\u0633\\u0644\\u0627\\u062D\\u0643!"
t["Loyalty cards didn't prepare anybody for this."] = "\\u0628\\u0637\\u0627\\u0642\\u0627\\u062A \\u0627\\u0644\\u0648\\u0644\\u0627\\u0621 \\u0645\\u0627 \\u062D\\u0636\\u0651\\u0631\\u062A \\u062D\\u062F\\u0627 \\u0644\\u0647\\u0627\\u0644\\u0634\\u064A."
t["Lucky fish. It will not get me twice."] = "\\u0645\\u062D\\u0638\\u0648\\u0638\\u0629 \\u0647\\u0627\\u0644\\u0633\\u0645\\u0643\\u0629. \\u0645\\u0627 \\u0631\\u062D \\u062A\\u0636\\u062D\\u0643 \\u0639\\u0644\\u064A\\u0651 \\u0645\\u0631\\u062A\\u064A\\u0646."
t["Made it back. Somebody tell me there's coffee."] = "\\u0648\\u0635\\u0644\\u0646\\u0627. \\u062D\\u062F\\u0627 \\u064A\\u0642\\u0644\\u064A \\u0641\\u064A \\u0642\\u0647\\u0648\\u0629."
t["Made it! Maybe the road likes us today."] = "\\u0648\\u0635\\u0644\\u062A! \\u064A\\u0645\\u0643\\u0646 \\u0627\\u0644\\u0637\\u0631\\u064A\\u0642 \\u0628\\u062D\\u0628\\u0646\\u0627 \\u0627\\u0644\\u064A\\u0648\\u0645."
t["Made it. I am not doing that twice."] = "\\u0648\\u0635\\u0644\\u062A. \\u0647\\u0627\\u0644\\u0634\\u064A \\u0645\\u0627 \\u0628\\u0639\\u064A\\u062F\\u0647 \\u0645\\u0631\\u062A\\u064A\\u0646."
t["Made it. I'll relax once there's a locked door between us and the road."] = "\\u0648\\u0635\\u0644\\u0646\\u0627. \\u0628\\u0631\\u062A\\u0627\\u062D \\u0644\\u0645\\u0627 \\u064A\\u0643\\u0648\\u0646 \\u0641\\u064A \\u0628\\u0627\\u0628 \\u0645\\u0642\\u0641\\u0648\\u0644 \\u0628\\u064A\\u0646\\u0627\\u062A\\u0646\\u0627 \\u0648\\u0628\\u064A\\u0646 \\u0627\\u0644\\u0637\\u0631\\u064A\\u0642."
t["Made it. I'll watch while you climb."] = "\\u0648\\u0635\\u0644\\u062A. \\u0628\\u0646\\u062A\\u0628\\u0647\\u0644\\u0643 \\u0648\\u0625\\u0646\\u062A \\u0639\\u0645 \\u062A\\u0637\\u0644\\u0639."
t["Made it. Nothing important tore."] = "\\u0648\\u0635\\u0644\\u062A. \\u0645\\u0627 \\u0627\\u0646\\u0634\\u0642 \\u0634\\u064A \\u0645\\u0647\\u0645."
t["Made it. Small miracles."] = "\\u0648\\u0635\\u0644\\u062A. \\u0645\\u0639\\u062C\\u0632\\u0627\\u062A \\u0635\\u063A\\u064A\\u0631\\u0629."
t["Magazine empty. Disengaging to reload."] = "\\u0627\\u0644\\u0645\\u062E\\u0632\\u0646 \\u0641\\u0627\\u0636\\u064A. \\u0639\\u0645 \\u0627\\u0628\\u0639\\u062F \\u0644\\u0639\\u0628\\u0651\\u064A."
t["Make a hole, %1. Coming through."] = "\\u0641\\u062A\\u062D\\u0644\\u064A \\u0637\\u0631\\u064A\\u0642 \\u064A\\u0627 %1. \\u0645\\u0627\\u0634\\u064A\\u0629."
t["Make it quick. This place gives me the creeps."] = "\\u062E\\u0644\\u0635\\u0647\\u0627 \\u0628\\u0633\\u0631\\u0639\\u0629. \\u0647\\u0627\\u0644\\u0645\\u062D\\u0644 \\u0628\\u064A\\u0642\\u0634\\u0639\\u0631."
t["Make it stop. Please, make it stop."] = "\\u0648\\u0642\\u0641\\u0647\\u0627. \\u0627\\u0644\\u0644\\u0647 \\u064A\\u062E\\u0644\\u064A\\u0643\\u060C \\u0648\\u0642\\u0641\\u0647\\u0627."
t["Make the next swing count for both of us."] = "\\u062E\\u0644\\u064A \\u0627\\u0644\\u0636\\u0631\\u0628\\u0629 \\u0627\\u0644\\u062C\\u0627\\u064A\\u0629 \\u0639\\u0646 \\u062A\\u0646\\u064A\\u0646\\u0627\\u062A\\u0646\\u0627."
t["Make them pay for touching one of us!"] = "\\u062E\\u0644\\u064A\\u0647\\u0646 \\u064A\\u062F\\u0641\\u0639\\u0648\\u0627 \\u062A\\u0645\\u0646 \\u0627\\u0644\\u0644\\u064A \\u0644\\u0645\\u0633\\u0648\\u0627 \\u0648\\u0627\\u062D\\u062F \\u0645\\u0646\\u0627!"
t["Make them string out first!"] = "\\u062E\\u0644\\u064A\\u0647\\u0646 \\u064A\\u062A\\u0645\\u062F\\u0648\\u0627 \\u0628\\u0627\\u0644\\u0637\\u0627\\u0628\\u0648\\u0631 \\u0623\\u0648\\u0644!"
t["Makes me want to stay in this chair a little longer."] = "\\u0628\\u064A\\u062E\\u0644\\u064A\\u0646\\u064A \\u0628\\u062F\\u064A \\u0636\\u0644 \\u0628\\u0647\\u0627\\u0644\\u0643\\u0631\\u0633\\u064A \\u0634\\u0648\\u064A \\u0643\\u0645\\u0627\\u0646."
t["Mama would want me to cover my eyes. Mama's not here."] = "\\u0623\\u0645\\u064A \\u0643\\u0627\\u0646\\u062A \\u0628\\u062F\\u0647\\u0627 \\u063A\\u0645\\u0651\\u0636 \\u0639\\u064A\\u0648\\u0646\\u064A. \\u0623\\u0645\\u064A \\u0645\\u0648 \\u0647\\u0648\\u0646."
t["Mamaw could shell a bushel of beans in the time you've been standing there."] = "\\u062A\\u064A\\u062A\\u0627 \\u0643\\u0627\\u0646\\u062A \\u062A\\u0642\\u0634\\u0651\\u0631 \\u0634\\u0648\\u0627\\u0644 \\u0641\\u0627\\u0635\\u0648\\u0644\\u064A\\u0627 \\u0628\\u0627\\u0644\\u0648\\u0642\\u062A \\u0627\\u0644\\u0644\\u064A \\u0625\\u0646\\u062A \\u0648\\u0627\\u0642\\u0641 \\u0641\\u064A\\u0647 \\u0647\\u0648\\u0646."
t["Maps and field guides. Grab those before the romance."] = "\\u062E\\u0631\\u0627\\u064A\\u0637 \\u0648\\u0623\\u062F\\u0644\\u0629 \\u0645\\u064A\\u062F\\u0627\\u0646\\u064A\\u0629. \\u062E\\u0648\\u062F\\u0647\\u0645 \\u0642\\u0628\\u0644 \\u0627\\u0644\\u063A\\u0631\\u0627\\u0645\\u064A\\u0627\\u062A."
t["Mass contact! Clear a path and run!"] = "\\u0643\\u062A\\u0644\\u0629 \\u0645\\u064A\\u062A\\u064A\\u0646! \\u0627\\u0641\\u062A\\u062D \\u0637\\u0631\\u064A\\u0642 \\u0648\\u0627\\u0631\\u0643\\u0636!"
t["Mass contact. Clear one lane and withdraw."] = "\\u0643\\u062A\\u0644\\u0629 \\u0645\\u064A\\u062A\\u064A\\u0646. \\u0627\\u0641\\u062A\\u062D \\u0645\\u0645\\u0631 \\u0648\\u0627\\u0646\\u0633\\u062D\\u0628."
t["Mass contact. No engagement. Find another way."] = "\\u0643\\u062A\\u0644\\u0629 \\u0645\\u064A\\u062A\\u064A\\u0646. \\u0644\\u0627 \\u0645\\u0648\\u0627\\u062C\\u0647\\u0629. \\u062F\\u0648\\u0631 \\u0637\\u0631\\u064A\\u0642 \\u062A\\u0627\\u0646\\u064A."
t["Mass of dead incoming! Withdraw now!"] = "\\u0643\\u062A\\u0644\\u0629 \\u0645\\u064A\\u062A\\u064A\\u0646 \\u062C\\u0627\\u064A\\u0629! \\u0627\\u0646\\u0633\\u062D\\u0628 \\u0647\\u0644\\u0623!"
t["Matching set! I'll take both!"] = "\\u0637\\u0642\\u0645 \\u0643\\u0627\\u0645\\u0644! \\u0628\\u0622\\u062E\\u062F \\u0627\\u0644\\u062A\\u0646\\u064A\\u0646!"
t["Math says heck no. I'm backing off until it improves."] = "\\u0627\\u0644\\u062D\\u0633\\u0627\\u0628 \\u0628\\u064A\\u0642\\u0648\\u0644 \\u0648\\u0644\\u0627 \\u0628\\u0627\\u0644\\u0623\\u062D\\u0644\\u0627\\u0645. \\u0639\\u0645 \\u0627\\u0628\\u0639\\u062F \\u0644\\u062A\\u062A\\u062D\\u0633\\u0646."
t["Math says hell no. I'm backing off until it improves."] = "\\u0627\\u0644\\u062D\\u0633\\u0627\\u0628 \\u0628\\u064A\\u0642\\u0648\\u0644 \\u0648\\u0644\\u0627 \\u0628\\u0627\\u0644\\u062C\\u062D\\u064A\\u0645. \\u0639\\u0645 \\u0627\\u0628\\u0639\\u062F \\u0644\\u062A\\u062A\\u062D\\u0633\\u0646."
t["Maybe kindness is a skill. We practice it or we lose it."] = "\\u064A\\u0645\\u0643\\u0646 \\u0627\\u0644\\u0644\\u0637\\u0641 \\u0645\\u0647\\u0627\\u0631\\u0629. \\u064A\\u0627 \\u0645\\u0646\\u062A\\u0645\\u0631\\u0646 \\u0639\\u0644\\u064A\\u0647 \\u064A\\u0627 \\u0645\\u0646\\u062E\\u0633\\u0631\\u0647."
t["Maybe learning is just admitting we aren't finished yet."] = "\\u064A\\u0645\\u0643\\u0646 \\u0627\\u0644\\u062A\\u0639\\u0644\\u0645 \\u064A\\u0639\\u0646\\u064A \\u0646\\u0639\\u062A\\u0631\\u0641 \\u0625\\u0646\\u0648 \\u0644\\u0633\\u0627 \\u0645\\u0627 \\u062E\\u0644\\u0635\\u0646\\u0627."
t["Maybe that's why I like this table. It gives the memories a place."] = "\\u064A\\u0645\\u0643\\u0646 \\u0644\\u0647\\u064A\\u0643 \\u0628\\u062D\\u0628 \\u0647\\u0627\\u0644\\u0637\\u0627\\u0648\\u0644\\u0629. \\u0628\\u062A\\u0639\\u0637\\u064A \\u0627\\u0644\\u0630\\u0643\\u0631\\u064A\\u0627\\u062A \\u0645\\u0637\\u0631\\u062D."
t["Maybe the hills are swallowing the signal."] = "\\u064A\\u0645\\u0643\\u0646 \\u0627\\u0644\\u062C\\u0628\\u0627\\u0644 \\u0639\\u0645 \\u062A\\u0628\\u0644\\u0639 \\u0627\\u0644\\u0625\\u0634\\u0627\\u0631\\u0629."
t["Maybe the lesson is that we keep asking questions."] = "\\u064A\\u0645\\u0643\\u0646 \\u0627\\u0644\\u062F\\u0631\\u0633 \\u0625\\u0646\\u0648 \\u0646\\u0636\\u0644 \\u0646\\u0633\\u0623\\u0644."
t["Maybe the morning will smell clean, for once."] = "\\u064A\\u0645\\u0643\\u0646 \\u0627\\u0644\\u0635\\u0628\\u062D \\u0631\\u064A\\u062D\\u062A\\u0647 \\u062A\\u0643\\u0648\\u0646 \\u0646\\u0636\\u064A\\u0641\\u0629\\u060C \\u0644\\u0645\\u0631\\u0629."
t["Maybe tomorrow the voice will sound less tired."] = "\\u064A\\u0645\\u0643\\u0646 \\u0628\\u0643\\u0631\\u0627 \\u064A\\u0643\\u0648\\u0646 \\u0627\\u0644\\u0635\\u0648\\u062A \\u0623\\u0642\\u0644 \\u062A\\u0639\\u0628."
t["Maybe we can make a warm room of this one."] = "\\u064A\\u0645\\u0643\\u0646 \\u0646\\u062E\\u0644\\u064A \\u0647\\u0627\\u0644\\u0623\\u0648\\u0636\\u0629 \\u0647\\u064A \\u0627\\u0644\\u0623\\u0648\\u0636\\u0629 \\u0627\\u0644\\u062F\\u0627\\u0641\\u064A\\u0629."
t["Maybe we pass books around so nobody has to carry everything alone."] = "\\u064A\\u0645\\u0643\\u0646 \\u0645\\u0646\\u0628\\u062F\\u0644 \\u0627\\u0644\\u0643\\u062A\\u0628 \\u062D\\u062A\\u0649 \\u0645\\u0627 \\u062D\\u062F\\u0627 \\u064A\\u062D\\u0645\\u0644 \\u0643\\u0644 \\u0634\\u064A \\u0644\\u062D\\u0627\\u0644\\u0647."
t["Maybe we'll smell fresh bread here again."] = "\\u064A\\u0645\\u0643\\u0646 \\u0646\\u0634\\u0645 \\u0631\\u064A\\u062D\\u0629 \\u062E\\u0628\\u0632 \\u0637\\u0627\\u0632\\u0629 \\u0647\\u0648\\u0646 \\u0645\\u0631\\u0629 \\u062A\\u0627\\u0646\\u064A\\u0629."
t["Maybe with more time I would have told you more. I wanted to."] = "\\u064A\\u0645\\u0643\\u0646 \\u0644\\u0648 \\u0641\\u064A \\u0648\\u0642\\u062A \\u0643\\u0646\\u062A \\u062D\\u0643\\u064A\\u062A\\u0644\\u0643 \\u0623\\u0643\\u062A\\u0631. \\u0643\\u0627\\u0646 \\u0628\\u062F\\u064A."
t["Membership expired. So did the members."] = "\\u0627\\u0644\\u0627\\u0634\\u062A\\u0631\\u0627\\u0643 \\u0627\\u0646\\u062A\\u0647\\u0649. \\u0648\\u0627\\u0644\\u0645\\u0634\\u062A\\u0631\\u0643\\u064A\\u0646 \\u0643\\u0645\\u0627\\u0646."
t["Mental note: the end of the world has shitty signage."] = "\\u0645\\u0644\\u0627\\u062D\\u0638\\u0629: \\u0646\\u0647\\u0627\\u064A\\u0629 \\u0627\\u0644\\u0639\\u0627\\u0644\\u0645 \\u064A\\u0627\\u0641\\u0637\\u0627\\u062A\\u0647\\u0627 \\u0632\\u0641\\u062A."
t["Mental note: the end of the world has terrible signage."] = "\\u0645\\u0644\\u0627\\u062D\\u0638\\u0629: \\u0646\\u0647\\u0627\\u064A\\u0629 \\u0627\\u0644\\u0639\\u0627\\u0644\\u0645 \\u064A\\u0627\\u0641\\u0637\\u0627\\u062A\\u0647\\u0627 \\u0633\\u064A\\u0626\\u0629."
t["Metal doesn't listen to persuasion. We need a torch."] = "\\u0627\\u0644\\u062D\\u062F\\u064A\\u062F \\u0645\\u0627 \\u0628\\u064A\\u062A\\u0642\\u0646\\u0651\\u0639 \\u0628\\u0627\\u0644\\u062D\\u0643\\u064A. \\u0628\\u062F\\u0646\\u0627 \\u0634\\u0627\\u0644\\u064A\\u0645\\u0648."
t["Midnight math: days survived, cans left, people met."] = "\\u062D\\u0633\\u0627\\u0628\\u0627\\u062A \\u0646\\u0635 \\u0627\\u0644\\u0644\\u064A\\u0644: \\u0623\\u064A\\u0627\\u0645 \\u0639\\u0634\\u0646\\u0627\\u0647\\u0627\\u060C \\u0639\\u0644\\u0628 \\u0628\\u0627\\u0642\\u064A\\u0629\\u060C \\u0646\\u0627\\u0633 \\u0634\\u0641\\u0646\\u0627\\u0647\\u0645."
t["Milli calls this tea. The kettle declined to comment."] = "\\u0645\\u064A\\u0644\\u064A \\u0628\\u062A\\u0633\\u0645\\u064A\\u0647 \\u0634\\u0627\\u064A. \\u0627\\u0644\\u0625\\u0628\\u0631\\u064A\\u0642 \\u0631\\u0641\\u0636 \\u0627\\u0644\\u062A\\u0639\\u0644\\u064A\\u0642."
t["Milli says tea tastes better when nobody is shooting. Let's test that, %1."] = "\\u0645\\u064A\\u0644\\u064A \\u0628\\u062A\\u0642\\u0648\\u0644 \\u0627\\u0644\\u0634\\u0627\\u064A \\u0623\\u0637\\u064A\\u0628 \\u0644\\u0645\\u0627 \\u0645\\u0627 \\u062D\\u062F\\u0627 \\u064A\\u0637\\u062E. \\u062E\\u0644\\u064A\\u0646\\u0627 \\u0646\\u062C\\u0631\\u0628 \\u064A\\u0627 %1."
t["Milli's kettle is making its rounds. Who wants cold tea?"] = "\\u0625\\u0628\\u0631\\u064A\\u0642 \\u0645\\u064A\\u0644\\u064A \\u0639\\u0645 \\u064A\\u062F\\u0648\\u0631. \\u0645\\u064A\\u0646 \\u0628\\u062F\\u0648 \\u0634\\u0627\\u064A \\u0628\\u0627\\u0631\\u062F\\u061F"
t["Mind that blade. I'm right here."] = "\\u062F\\u064A\\u0631 \\u0628\\u0627\\u0644\\u0643 \\u0639\\u0627\\u0644\\u0646\\u0635\\u0644. \\u0623\\u0646\\u0627 \\u0647\\u0648\\u0646."
t["Mind the pair! Near one's mine!"] = "\\u062F\\u064A\\u0631 \\u0628\\u0627\\u0644\\u0643 \\u0645\\u0646\\u0646! \\u0627\\u0644\\u0642\\u0631\\u064A\\u0628 \\u0625\\u0644\\u064A!"
t["Mind your boots. This patch is getting cleaned."] = "\\u062F\\u064A\\u0631 \\u0628\\u0627\\u0644\\u0643 \\u0639\\u0628\\u0648\\u0637\\u0643. \\u0639\\u0645 \\u0646\\u0636\\u0641 \\u0647\\u0627\\u0644\\u0642\\u0637\\u0639\\u0629."
t["Mind your language in here. Even now."] = "\\u0627\\u0646\\u062A\\u0628\\u0647 \\u0644\\u0643\\u0644\\u0627\\u0645\\u0643 \\u0647\\u0648\\u0646. \\u062D\\u062A\\u0649 \\u0647\\u0644\\u0623."
t["Mine was loud. Cutlery, radio, somebody laughing too hard."] = "\\u062A\\u0628\\u0639\\u0646\\u0627 \\u0643\\u0627\\u0646 \\u0639\\u0627\\u0644\\u064A. \\u0634\\u0648\\u0643 \\u0648\\u0631\\u0627\\u062F\\u064A\\u0648 \\u0648\\u062D\\u062F\\u0627 \\u0639\\u0645 \\u064A\\u0636\\u062D\\u0643 \\u0632\\u064A\\u0627\\u062F\\u0629."
t["Mm. Fair enough."] = "\\u0645\\u0645\\u0645. \\u0645\\u0639\\u0643 \\u062D\\u0642."
t["Mop's earned a rest. So have I."] = "\\u0627\\u0644\\u0645\\u0645\\u0633\\u062D\\u0629 \\u0628\\u062A\\u0633\\u062A\\u0627\\u0647\\u0644 \\u062A\\u0631\\u062A\\u0627\\u062D. \\u0648\\u0623\\u0646\\u0627 \\u0643\\u0645\\u0627\\u0646."
t["Morale broadcast equipment. Stay tuned for further updates. I'm all ears."] = "\\u0645\\u0639\\u062F\\u0627\\u062A \\u0628\\u062B \\u0627\\u0644\\u0645\\u0639\\u0646\\u0648\\u064A\\u0627\\u062A. \\u062E\\u0644\\u064A\\u0643 \\u0645\\u0639\\u0646\\u0627 \\u0644\\u0645\\u0632\\u064A\\u062F \\u0645\\u0646 \\u0627\\u0644\\u0623\\u062E\\u0628\\u0627\\u0631. \\u0643\\u0644\\u064A \\u0622\\u0630\\u0627\\u0646."
t["Morbid inventory: shovels, two. Graves dug, more than two."] = "\\u062C\\u0631\\u062F \\u0623\\u0633\\u0648\\u062F: \\u0631\\u0641\\u0648\\u0634\\u060C \\u0627\\u062A\\u0646\\u064A\\u0646. \\u0642\\u0628\\u0648\\u0631 \\u0645\\u062D\\u0641\\u0648\\u0631\\u0629\\u060C \\u0623\\u0643\\u062A\\u0631 \\u0645\\u0646 \\u0627\\u062A\\u0646\\u064A\\u0646."
t["Morbid thought: the crows are eating better than we are."] = "\\u0641\\u0643\\u0631\\u0629 \\u0633\\u0648\\u062F\\u0627: \\u0627\\u0644\\u063A\\u0631\\u0628\\u0627\\u0646 \\u0639\\u0645 \\u062A\\u0627\\u0643\\u0644 \\u0623\\u062D\\u0633\\u0646 \\u0645\\u0646\\u0627."
t["Morbid thought: the goddamn crows are eating better than we are."] = "\\u0641\\u0643\\u0631\\u0629 \\u0633\\u0648\\u062F\\u0627: \\u0627\\u0644\\u063A\\u0631\\u0628\\u0627\\u0646 \\u0627\\u0644\\u0645\\u0644\\u0639\\u0648\\u0646\\u0629 \\u0639\\u0645 \\u062A\\u0627\\u0643\\u0644 \\u0623\\u062D\\u0633\\u0646 \\u0645\\u0646\\u0627."
t["More close than I can handle. I'm backing off."] = "\\u0642\\u0631\\u0627\\u0628 \\u0623\\u0643\\u062A\\u0631 \\u0645\\u0645\\u0627 \\u0628\\u062A\\u062D\\u0645\\u0644. \\u0639\\u0645 \\u0627\\u0628\\u0639\\u062F."
t["More zombies than I can count."] = "\\u0632\\u0648\\u0645\\u0628\\u064A \\u0623\\u0643\\u062A\\u0631 \\u0645\\u0646 \\u0645\\u0627 \\u0628\\u0642\\u062F\\u0631 \\u0639\\u062F."
t["Morning found us. The empty houses did not notice."] = "\\u0627\\u0644\\u0635\\u0628\\u062D \\u0644\\u0642\\u0627\\u0646\\u0627. \\u0627\\u0644\\u0628\\u064A\\u0648\\u062A \\u0627\\u0644\\u0641\\u0627\\u0636\\u064A\\u0629 \\u0645\\u0627 \\u0627\\u0646\\u062A\\u0628\\u0647\\u062A."
t["Morning. Daylight means we can cover more ground."] = "\\u0635\\u0628\\u0627\\u062D \\u0627\\u0644\\u062E\\u064A\\u0631. \\u0627\\u0644\\u0636\\u0648 \\u064A\\u0639\\u0646\\u064A \\u0641\\u064A\\u0646\\u0627 \\u0646\\u0642\\u0637\\u0639 \\u0645\\u0633\\u0627\\u0641\\u0629 \\u0623\\u0643\\u0628\\u0631."
t["Morning. How are you holding up?"] = "\\u0635\\u0628\\u0627\\u062D \\u0627\\u0644\\u062E\\u064A\\u0631. \\u0643\\u064A\\u0641\\u0643\\u060C \\u0645\\u0627\\u0634\\u064A \\u062D\\u0627\\u0644\\u0643\\u061F"
t["Morning. Let's check the exits before we settle in."] = "\\u0635\\u0628\\u0627\\u062D \\u0627\\u0644\\u062E\\u064A\\u0631. \\u062E\\u0644\\u064A\\u0646\\u0627 \\u0646\\u0634\\u064A\\u0643 \\u0627\\u0644\\u0645\\u062E\\u0627\\u0631\\u062C \\u0642\\u0628\\u0644 \\u0645\\u0627 \\u0646\\u0642\\u0639\\u062F."
t["Morning. Let's make today count."] = "\\u0635\\u0628\\u0627\\u062D \\u0627\\u0644\\u062E\\u064A\\u0631. \\u062E\\u0644\\u064A\\u0646\\u0627 \\u0646\\u0633\\u062A\\u0641\\u064A\\u062F \\u0645\\u0646 \\u0647\\u0627\\u0644\\u064A\\u0648\\u0645."
t["Morning. Quiet so far. I hope it stays that way."] = "\\u0635\\u0628\\u0627\\u062D \\u0627\\u0644\\u062E\\u064A\\u0631. \\u0647\\u0627\\u062F\\u064A \\u0644\\u0647\\u0644\\u0623. \\u0625\\u0646 \\u0634\\u0627\\u0621 \\u0627\\u0644\\u0644\\u0647 \\u064A\\u0636\\u0644 \\u0647\\u064A\\u0643."
t["Morning. We made it through another night."] = "\\u0635\\u0628\\u0627\\u062D \\u0627\\u0644\\u062E\\u064A\\u0631. \\u0645\\u0631\\u0642\\u062A \\u0644\\u064A\\u0644\\u0629 \\u062A\\u0627\\u0646\\u064A\\u0629."
t["Move it, %1. Even the zombies are losing interest."] = "\\u062E\\u0644\\u0635\\u0646\\u064A \\u064A\\u0627 %1. \\u062D\\u062A\\u0649 \\u0627\\u0644\\u0632\\u0648\\u0645\\u0628\\u064A \\u0635\\u0627\\u0631 \\u0632\\u0647\\u0642\\u0627\\u0646."
t["Move over, %1. I need through."] = "\\u0648\\u062E\\u0631 \\u064A\\u0627 %1. \\u0628\\u062F\\u064A \\u0645\\u0631\\u0642."
t["Move the supplies out before you seal the room."] = "\\u0637\\u0627\\u0644\\u0639 \\u0627\\u0644\\u0645\\u0648\\u0646\\u0629 \\u0642\\u0628\\u0644 \\u0645\\u0627 \\u062A\\u0633\\u0643\\u0631 \\u0627\\u0644\\u063A\\u0631\\u0641\\u0629."
t["Move! I don't want anyone trapped!"] = "\\u062A\\u062D\\u0631\\u0643! \\u0645\\u0627 \\u0628\\u062F\\u064A \\u062D\\u062F\\u0627 \\u064A\\u0646\\u062D\\u0635\\u0631!"
t["Move! I'll cover the retreat!"] = "\\u062A\\u062D\\u0631\\u0643! \\u0628\\u063A\\u0637\\u064A \\u0627\\u0644\\u0627\\u0646\\u0633\\u062D\\u0627\\u0628!"
t["Movement! Zombie nearby!"] = "\\u0641\\u064A \\u062D\\u0631\\u0643\\u0629! \\u0632\\u0648\\u0645\\u0628\\u064A \\u0642\\u0631\\u064A\\u0628!"
t["Moving in!"] = "\\u0639\\u0645 \\u0642\\u0631\\u0628!"
t["Moving in. Watch my flank!"] = "\\u0639\\u0645 \\u0642\\u0631\\u0628. \\u0627\\u0646\\u062A\\u0628\\u0647\\u0644\\u064A \\u0639\\u062C\\u0646\\u0628\\u064A!"
t["Multiple contacts. About four."] = "\\u0641\\u064A \\u0643\\u0630\\u0627 \\u0648\\u0627\\u062D\\u062F. \\u0634\\u064A \\u0623\\u0631\\u0628\\u0639\\u0629."
t["Multiple immediate threats. Rejecting contact and opening distance."] = "\\u0643\\u0630\\u0627 \\u062E\\u0637\\u0631 \\u0641\\u0648\\u0631\\u064A. \\u0644\\u0627 \\u0627\\u0634\\u062A\\u0628\\u0627\\u0643\\u060C \\u0648\\u0639\\u0645 \\u0627\\u0628\\u0639\\u062F."
t["Multiple targets. Stay on your feet!"] = "\\u0623\\u0647\\u062F\\u0627\\u0641 \\u0643\\u062A\\u064A\\u0631. \\u0636\\u0644 \\u0648\\u0627\\u0642\\u0641!"
t["Multiple targets. We fight our way out!"] = "\\u0623\\u0647\\u062F\\u0627\\u0641 \\u0643\\u062A\\u064A\\u0631. \\u0645\\u0646\\u0637\\u0644\\u0639 \\u0628\\u0627\\u0644\\u0642\\u062A\\u0627\\u0644!"
t["Multiple walkers, spread out ahead."] = "\\u0643\\u0630\\u0627 \\u0632\\u0648\\u0645\\u0628\\u064A \\u0645\\u062A\\u0641\\u0631\\u0642\\u064A\\u0646 \\u0642\\u062F\\u0627\\u0645\\u0646\\u0627."
t["Muzzle down, stranger!"] = "\\u0648\\u062C\\u0651\\u0647 \\u0627\\u0644\\u0628\\u0627\\u0631\\u0648\\u062F\\u0629 \\u0644\\u0644\\u0623\\u0631\\u0636 \\u064A\\u0627 \\u063A\\u0631\\u064A\\u0628!"
t["My ammunition is nearly gone."] = "\\u0631\\u0635\\u0627\\u0635\\u064A \\u0642\\u0631\\u0628 \\u064A\\u062E\\u0644\\u0635."
t["My attention is slipping. I need food before we take another risk."] = "\\u0627\\u0646\\u062A\\u0628\\u0627\\u0647\\u064A \\u0639\\u0645 \\u064A\\u0631\\u0648\\u062D. \\u0628\\u062F\\u064A \\u0623\\u0643\\u0644 \\u0642\\u0628\\u0644 \\u0623\\u064A \\u0645\\u062E\\u0627\\u0637\\u0631\\u0629 \\u062A\\u0627\\u0646\\u064A\\u0629."
t["My axe is about done. You want this?"] = "\\u0641\\u0627\\u0633\\u064A \\u0642\\u0631\\u0628 \\u064A\\u062E\\u0644\\u0635. \\u0628\\u062F\\u0643 \\u064A\\u0627\\u0647\\u061F"
t["My bladder has worse timing than the weather."] = "\\u0645\\u062B\\u0627\\u0646\\u062A\\u064A \\u062A\\u0648\\u0642\\u064A\\u062A\\u0647\\u0627 \\u0623\\u0633\\u0648\\u0623 \\u0645\\u0646 \\u0627\\u0644\\u0637\\u0642\\u0633."
t["My brain keeps drawing the map, then a second map, just in case."] = "\\u0639\\u0642\\u0644\\u064A \\u0628\\u064A\\u0636\\u0644 \\u064A\\u0631\\u0633\\u0645 \\u0627\\u0644\\u062E\\u0631\\u064A\\u0637\\u0629\\u060C \\u0648\\u0628\\u0639\\u062F\\u064A\\u0646 \\u062E\\u0631\\u064A\\u0637\\u0629 \\u062A\\u0627\\u0646\\u064A\\u0629\\u060C \\u0627\\u062D\\u062A\\u064A\\u0627\\u0637."
t["My brain keeps rehearsing the worst evening. Over and over."] = "\\u0639\\u0642\\u0644\\u064A \\u0628\\u064A\\u0636\\u0644 \\u064A\\u062A\\u0645\\u0631\\u0646 \\u0639\\u0644\\u0649 \\u0623\\u0633\\u0648\\u0623 \\u0645\\u0633\\u0627. \\u0645\\u0631\\u0629 \\u0648\\u0631\\u0627 \\u0645\\u0631\\u0629."
t["My brain's doing housework of its own. Let it."] = "\\u0639\\u0642\\u0644\\u064A \\u0639\\u0645 \\u064A\\u0639\\u0645\\u0644 \\u0634\\u063A\\u0644 \\u0628\\u064A\\u062A \\u0644\\u062D\\u0627\\u0644\\u0647. \\u062E\\u0644\\u064A\\u0647."
t["My canteen is empty and I am running dry."] = "\\u0645\\u0637\\u0631\\u062A\\u064A \\u0641\\u0627\\u0636\\u064A\\u0629 \\u0648\\u0623\\u0646\\u0627 \\u0639\\u0645 \\u0627\\u0646\\u0634\\u0641."
t["My chest thinks we're already dead. Give me a second."] = "\\u0635\\u062F\\u0631\\u064A \\u0645\\u0641\\u0643\\u0631 \\u0625\\u0646\\u0627 \\u0645\\u062A\\u0646\\u0627 \\u062E\\u0644\\u0635. \\u0627\\u0639\\u0637\\u064A\\u0646\\u064A \\u0644\\u062D\\u0638\\u0629."
t["My eyes keep losing focus."] = "\\u0639\\u064A\\u0648\\u0646\\u064A \\u0639\\u0645 \\u062A\\u0636\\u064A\\u0651\\u0639 \\u0627\\u0644\\u062A\\u0631\\u0643\\u064A\\u0632."
t["My family used to argue over who sat by the window."] = "\\u0623\\u0647\\u0644\\u064A \\u0643\\u0627\\u0646\\u0648\\u0627 \\u064A\\u062A\\u062E\\u0627\\u0646\\u0642\\u0648\\u0627 \\u0645\\u064A\\u0646 \\u0628\\u064A\\u0642\\u0639\\u062F \\u062C\\u0646\\u0628 \\u0627\\u0644\\u0634\\u0628\\u0627\\u0643."
t["My feet hurt, my back hurts, and the world ended. Rough week."] = "\\u0631\\u062C\\u0644\\u064A\\u064A \\u0639\\u0645 \\u064A\\u0648\\u062C\\u0639\\u0648\\u0646\\u064A\\u060C \\u0636\\u0647\\u0631\\u064A \\u0639\\u0645 \\u064A\\u0648\\u062C\\u0639\\u0646\\u064A\\u060C \\u0648\\u0627\\u0644\\u062F\\u0646\\u064A\\u0627 \\u062E\\u0644\\u0635\\u062A. \\u062C\\u0645\\u0639\\u0629 \\u062A\\u0642\\u064A\\u0644\\u0629."
t["My feet hurt, my back hurts, and the world ended. Shit week."] = "\\u0631\\u062C\\u0644\\u064A\\u064A \\u0639\\u0645 \\u064A\\u0648\\u062C\\u0639\\u0648\\u0646\\u064A\\u060C \\u0636\\u0647\\u0631\\u064A \\u0639\\u0645 \\u064A\\u0648\\u062C\\u0639\\u0646\\u064A\\u060C \\u0648\\u0627\\u0644\\u062F\\u0646\\u064A\\u0627 \\u062E\\u0644\\u0635\\u062A. \\u062C\\u0645\\u0639\\u0629 \\u0632\\u0641\\u062A."
t["My first need is food."] = "\\u0623\\u0648\\u0644 \\u062D\\u0627\\u062C\\u062A\\u064A \\u0623\\u0643\\u0644."
t["My fists aren't a plan. I'm holding until I'm armed."] = "\\u0642\\u0628\\u0636\\u0627\\u062A\\u064A \\u0645\\u0648 \\u062E\\u0637\\u0629. \\u0645\\u0633\\u062A\\u0646\\u064A\\u0629 \\u0644\\u062A\\u0633\\u0644\\u062D."
t["My goal is to make this place safer before the next horde finds it."] = "\\u0647\\u062F\\u0641\\u064A \\u062E\\u0644\\u064A \\u0647\\u0627\\u0644\\u0645\\u0637\\u0631\\u062D \\u0623\\u0623\\u0645\\u0646 \\u0642\\u0628\\u0644 \\u0645\\u0627 \\u062A\\u0644\\u0627\\u0642\\u064A\\u0647 \\u0627\\u0644\\u0645\\u0648\\u062C\\u0629 \\u0627\\u0644\\u062C\\u0627\\u064A\\u0629."
t["My goal is to recover one piece of my old life."] = "\\u0647\\u062F\\u0641\\u064A \\u0625\\u0646\\u064A \\u0631\\u062C\\u0651\\u0639 \\u062D\\u062A\\u0629 \\u0645\\u0646 \\u062D\\u064A\\u0627\\u062A\\u064A \\u0627\\u0644\\u0642\\u062F\\u064A\\u0645\\u0629."
t["My hands are shaking. Give me a moment."] = "\\u0625\\u064A\\u062F\\u064A\\u064A \\u0639\\u0645 \\u064A\\u0631\\u062C\\u0641\\u0648\\u0627. \\u0627\\u0639\\u0637\\u064A\\u0646\\u064A \\u0644\\u062D\\u0638\\u0629."
t["My hands are sore, but the wall's still standing."] = "\\u0625\\u064A\\u062F\\u064A\\u064A \\u0639\\u0645 \\u064A\\u0648\\u062C\\u0639\\u0648\\u0646\\u064A\\u060C \\u0628\\u0633 \\u0627\\u0644\\u062D\\u064A\\u0637 \\u0644\\u0633\\u0627 \\u0648\\u0627\\u0642\\u0641."
t["My hands remember things I did this summer. I wish they'd stop."] = "\\u0625\\u064A\\u062F\\u064A\\u064A \\u0628\\u062A\\u062A\\u0630\\u0643\\u0631 \\u0634\\u063A\\u0644\\u0627\\u062A \\u0639\\u0645\\u0644\\u062A\\u0647\\u0627 \\u0647\\u0627\\u0644\\u0635\\u064A\\u0641. \\u064A\\u0627 \\u0631\\u064A\\u062A\\u0647\\u0627 \\u062A\\u0648\\u0642\\u0641."
t["My head is clear today. Put me to work."] = "\\u0631\\u0627\\u0633\\u064A \\u0635\\u0627\\u0641\\u064A \\u0627\\u0644\\u064A\\u0648\\u0645. \\u0634\\u063A\\u0651\\u0644\\u0646\\u064A."
t["My head is starting to ache. I need a drink."] = "\\u0631\\u0627\\u0633\\u064A \\u0639\\u0645 \\u064A\\u0628\\u0644\\u0651\\u0634 \\u064A\\u0648\\u062C\\u0639\\u0646\\u064A. \\u0628\\u062F\\u064A \\u0627\\u0634\\u0631\\u0628."
t["My head keeps narrating how we die. Badly written, too."] = "\\u0631\\u0627\\u0633\\u064A \\u0628\\u064A\\u0636\\u0644 \\u064A\\u062D\\u0643\\u064A \\u0643\\u064A\\u0641 \\u0631\\u062D \\u0646\\u0645\\u0648\\u062A. \\u0648\\u0643\\u062A\\u0627\\u0628\\u062A\\u0647 \\u0639\\u0627\\u0637\\u0644\\u0629."
t["My head keeps narrating how we die. Shitty writing, too."] = "\\u0631\\u0627\\u0633\\u064A \\u0628\\u064A\\u0636\\u0644 \\u064A\\u062D\\u0643\\u064A \\u0643\\u064A\\u0641 \\u0631\\u062D \\u0646\\u0645\\u0648\\u062A. \\u0648\\u0643\\u062A\\u0627\\u0628\\u062A\\u0647 \\u0632\\u0641\\u062A."
t["My head's a damn mess. I'm sitting this approach out."] = "\\u0631\\u0627\\u0633\\u064A \\u0645\\u062E\\u0631\\u0628\\u0637 \\u064A\\u0644\\u0639\\u0646\\u0647. \\u0647\\u0627\\u0644\\u0645\\u0631\\u0629 \\u0645\\u0648 \\u0637\\u0627\\u0644\\u0639\\u0629."
t["My head's a darn mess. I'm sitting this approach out."] = "\\u0631\\u0627\\u0633\\u064A \\u0645\\u062E\\u0631\\u0628\\u0637 \\u0648\\u0627\\u0644\\u0644\\u0647. \\u0647\\u0627\\u0644\\u0645\\u0631\\u0629 \\u0645\\u0648 \\u0637\\u0627\\u0644\\u0639\\u0629."
t["My head's doing that thing again. Ignore me."] = "\\u0631\\u0627\\u0633\\u064A \\u0639\\u0645 \\u064A\\u0639\\u0645\\u0644 \\u0647\\u062F\\u0627\\u0643 \\u0627\\u0644\\u0634\\u064A \\u0645\\u0631\\u0629 \\u062A\\u0627\\u0646\\u064A\\u0629. \\u0637\\u0646\\u0651\\u0634."
t["My head's full of rooms nobody will walk into again."] = "\\u0631\\u0627\\u0633\\u064A \\u0645\\u0644\\u064A\\u0627\\u0646 \\u0623\\u0648\\u0636 \\u0645\\u0627 \\u062D\\u062F\\u0627 \\u0631\\u062D \\u064A\\u0641\\u0648\\u062A\\u0647\\u0627 \\u0628\\u0639\\u062F."
t["My legs are getting heavy."] = "\\u0625\\u062C\\u0631\\u064A\\u064A \\u0639\\u0645 \\u064A\\u062A\\u0642\\u0644\\u0648\\u0627."
t["My lungs declined the invitation. I'm stopping for air."] = "\\u0631\\u0626\\u062A\\u064A\\u0646\\u064A \\u0627\\u0639\\u062A\\u0630\\u0631\\u0648\\u0627 \\u0639\\u0646 \\u0627\\u0644\\u062D\\u0636\\u0648\\u0631. \\u0639\\u0645 \\u0648\\u0642\\u0641 \\u0622\\u062E\\u062F \\u0646\\u0641\\u0633."
t["My medicine won't help me now. Save it."] = "\\u062F\\u0648\\u0627\\u064A\\u064A \\u0645\\u0627 \\u0639\\u0627\\u062F \\u0628\\u064A\\u0646\\u0641\\u0639. \\u0648\\u0641\\u0631\\u0647."
t["My mind wandered off and came back with nothing useful."] = "\\u0639\\u0642\\u0644\\u064A \\u0634\\u0631\\u062F \\u0648\\u0631\\u062C\\u0639 \\u0628\\u0644\\u0627 \\u0634\\u064A \\u0645\\u0641\\u064A\\u062F."
t["My mother read to me. I can still hear how she said the names."] = "\\u0625\\u0645\\u064A \\u0643\\u0627\\u0646\\u062A \\u062A\\u0642\\u0631\\u0627\\u0644\\u064A. \\u0644\\u0633\\u0627 \\u0633\\u0627\\u0645\\u0639\\u0629 \\u0643\\u064A\\u0641 \\u0643\\u0627\\u0646\\u062A \\u062A\\u0644\\u0641\\u0638 \\u0627\\u0644\\u0623\\u0633\\u0627\\u0645\\u064A."
t["My mouth is getting dry."] = "\\u062A\\u0645\\u064A \\u0639\\u0645 \\u064A\\u0646\\u0634\\u0641."
t["My mouth is so dry I can barely talk."] = "\\u062A\\u0645\\u064A \\u0646\\u0627\\u0634\\u0641 \\u0644\\u062F\\u0631\\u062C\\u0629 \\u0628\\u0627\\u0644\\u0643\\u0627\\u062F \\u0639\\u0645 \\u0627\\u062D\\u0643\\u064A."
t["My nerves have reduced the whole apocalypse to one cigarette."] = "\\u0623\\u0639\\u0635\\u0627\\u0628\\u064A \\u0627\\u062E\\u062A\\u0635\\u0631\\u062A \\u0643\\u0644 \\u0646\\u0647\\u0627\\u064A\\u0629 \\u0627\\u0644\\u0639\\u0627\\u0644\\u0645 \\u0628\\u0633\\u064A\\u062C\\u0627\\u0631\\u0629."
t["My nerves keep asking for a cigarette. Persistent little clerks."] = "\\u0623\\u0639\\u0635\\u0627\\u0628\\u064A \\u0639\\u0645 \\u062A\\u0636\\u0644 \\u062A\\u0637\\u0627\\u0644\\u0628 \\u0628\\u0633\\u064A\\u062C\\u0627\\u0631\\u0629. \\u0645\\u0648\\u0638\\u0641\\u064A\\u0646 \\u0644\\u062C\\u0648\\u062C\\u064A\\u0646."
t["My nerves won't take orders. I'm holding until they do."] = "\\u0623\\u0639\\u0635\\u0627\\u0628\\u064A \\u0645\\u0627 \\u0639\\u0645 \\u062A\\u0637\\u064A\\u0639. \\u0631\\u062D \\u0636\\u0644 \\u0644\\u062A\\u0637\\u064A\\u0639."
t["My next job is checking every tool and repairing what I can."] = "\\u0634\\u063A\\u0644\\u062A\\u064A \\u0627\\u0644\\u062C\\u0627\\u064A\\u0629 \\u0625\\u0646\\u064A \\u0627\\u0641\\u062D\\u0635 \\u0643\\u0644 \\u0639\\u062F\\u0629 \\u0648\\u0635\\u0644\\u0651\\u062D \\u0627\\u0644\\u0644\\u064A \\u0628\\u0642\\u062F\\u0631 \\u0639\\u0644\\u064A\\u0647."
t["My plan is simple: find a book and let my mind go somewhere else for a while."] = "\\u062E\\u0637\\u062A\\u064A \\u0628\\u0633\\u064A\\u0637\\u0629: \\u0644\\u0627\\u0642\\u064A \\u0643\\u062A\\u0627\\u0628 \\u0648\\u062E\\u0644\\u064A \\u0631\\u0627\\u0633\\u064A \\u064A\\u0631\\u0648\\u062D \\u0644\\u0645\\u0637\\u0631\\u062D \\u062A\\u0627\\u0646\\u064A \\u0634\\u0648\\u064A."
t["My priority is making sure a small wound never becomes a death sentence."] = "\\u0647\\u0645\\u064A \\u0627\\u0644\\u0623\\u0648\\u0644 \\u0625\\u0646\\u0648 \\u0627\\u0644\\u062C\\u0631\\u062D \\u0627\\u0644\\u0635\\u063A\\u064A\\u0631 \\u0645\\u0627 \\u064A\\u0635\\u064A\\u0631 \\u062D\\u0643\\u0645 \\u0625\\u0639\\u062F\\u0627\\u0645."
t["My pulse will stop before the danger does."] = "\\u0646\\u0628\\u0636\\u064A \\u0631\\u062D \\u064A\\u0648\\u0642\\u0641 \\u0642\\u0628\\u0644 \\u0645\\u0627 \\u064A\\u0648\\u0642\\u0641 \\u0627\\u0644\\u062E\\u0637\\u0631."
t["My reactions are gone. I need shelter and sleep."] = "\\u0631\\u062F\\u0627\\u062A \\u0641\\u0639\\u0644\\u064A \\u0631\\u0627\\u062D\\u062A. \\u0628\\u062F\\u064A \\u0645\\u0644\\u062C\\u0623 \\u0648\\u0646\\u0648\\u0645."
t["My reactions are slowing. We need shelter before another risk."] = "\\u0631\\u062F\\u0629 \\u0641\\u0639\\u0644\\u064A \\u0639\\u0645 \\u062A\\u0628\\u0637\\u0649. \\u0628\\u062F\\u0646\\u0627 \\u0645\\u0644\\u062C\\u0623 \\u0642\\u0628\\u0644 \\u0623\\u064A \\u0645\\u062E\\u0627\\u0637\\u0631\\u0629."
t["My skin feels like it belongs to somebody else today."] = "\\u062C\\u0644\\u062F\\u064A \\u0627\\u0644\\u064A\\u0648\\u0645 \\u0643\\u0623\\u0646\\u0647 \\u0644\\u062D\\u062F\\u0627 \\u062A\\u0627\\u0646\\u064A."
t["My skin feels too tight when there is nothing to do."] = "\\u062C\\u0644\\u062F\\u064A \\u0628\\u064A\\u0635\\u064A\\u0631 \\u0636\\u064A\\u0642 \\u0639\\u0644\\u064A\\u064A \\u0644\\u0645\\u0627 \\u0645\\u0627 \\u064A\\u0643\\u0648\\u0646 \\u0641\\u064A \\u0634\\u064A \\u0627\\u0639\\u0645\\u0644\\u0647."
t["My stomach is reminding me it exists."] = "\\u0645\\u0639\\u062F\\u062A\\u064A \\u0639\\u0645 \\u062A\\u0630\\u0643\\u0631\\u0646\\u064A \\u0625\\u0646\\u0647\\u0627 \\u0645\\u0648\\u062C\\u0648\\u062F\\u0629."
t["My things are yours. Take the good boots. Don't argue with me."] = "\\u0623\\u063A\\u0631\\u0627\\u0636\\u064A \\u0625\\u0644\\u0643. \\u062E\\u0648\\u062F \\u0627\\u0644\\u0628\\u0648\\u0637 \\u0627\\u0644\\u0645\\u0646\\u064A\\u062D. \\u0648\\u0644\\u0627 \\u062A\\u062C\\u0627\\u062F\\u0644\\u0646\\u064A."
t["My thoughts keep stopping halfway through."] = "\\u0623\\u0641\\u0643\\u0627\\u0631\\u064A \\u0639\\u0645 \\u062A\\u0648\\u0642\\u0641 \\u0628\\u0646\\u0635 \\u0627\\u0644\\u0637\\u0631\\u064A\\u0642."
t["My turn!"] = "\\u062F\\u0648\\u0631\\u064A!"
t["My weapon's failing. I need another one."] = "\\u0633\\u0644\\u0627\\u062D\\u064A \\u0639\\u0645 \\u064A\\u0633\\u062A\\u0633\\u0644\\u0645. \\u0628\\u062F\\u064A \\u063A\\u064A\\u0631\\u0647."
t["My wounds need attention before they get worse."] = "\\u062C\\u0631\\u0648\\u062D\\u064A \\u0628\\u062F\\u0647\\u0627 \\u0627\\u0647\\u062A\\u0645\\u0627\\u0645 \\u0642\\u0628\\u0644 \\u0645\\u0627 \\u062A\\u0633\\u0648\\u0621."
t["My wounds vote against it. I'm listening and pulling back."] = "\\u062C\\u0631\\u0648\\u062D\\u064A \\u0635\\u0648\\u062A\\u062A \\u0636\\u062F. \\u0633\\u0645\\u0639\\u062A \\u0643\\u0644\\u0645\\u062A\\u0647\\u0627 \\u0648\\u0631\\u0627\\u062C\\u0639\\u0629."
t["Mystery novels. I know who did it. Everybody did it."] = "\\u0631\\u0648\\u0627\\u064A\\u0627\\u062A \\u0628\\u0648\\u0644\\u064A\\u0633\\u064A\\u0629. \\u0628\\u0639\\u0631\\u0641 \\u0645\\u064A\\u0646 \\u0639\\u0645\\u0644\\u0647\\u0627. \\u0627\\u0644\\u0643\\u0644 \\u0639\\u0645\\u0644\\u0647\\u0627."
t["Name's %1. Everybody calls me %2."] = "\\u0627\\u0633\\u0645\\u064A %1. \\u0627\\u0644\\u0643\\u0644 \\u0628\\u064A\\u0646\\u0627\\u062F\\u064A\\u0646\\u064A %2."
t["Near one first, then the straggler!"] = "\\u0627\\u0644\\u0642\\u0631\\u064A\\u0628 \\u0623\\u0648\\u0644, \\u0648\\u0628\\u0639\\u062F\\u064A\\u0646 \\u0627\\u0644\\u0644\\u064A \\u0648\\u0631\\u0627\\u0647!"
t["Never again. Please."] = "\\u0645\\u0627 \\u0639\\u0627\\u062F \\u0628\\u062F\\u064A. \\u0627\\u0644\\u0644\\u0647 \\u064A\\u062E\\u0644\\u064A\\u0643."
t["Next time we eat, stay with me a while. It makes the place feel warmer."] = "\\u0627\\u0644\\u0645\\u0631\\u0629 \\u0627\\u0644\\u062C\\u0627\\u064A\\u0629 \\u0644\\u0645\\u0627 \\u0646\\u0627\\u0643\\u0644\\u060C \\u062E\\u0644\\u064A\\u0643 \\u0645\\u0639\\u064A \\u0634\\u0648\\u064A. \\u0628\\u064A\\u062F\\u0641\\u0649 \\u0627\\u0644\\u0645\\u0637\\u0631\\u062D."
t["Nice car. Nicer when it moves."] = "\\u0633\\u064A\\u0627\\u0631\\u0629 \\u062D\\u0644\\u0648\\u0629. \\u0623\\u062D\\u0644\\u0649 \\u0644\\u0645\\u0627 \\u062A\\u0645\\u0634\\u064A."
t["Night doesn't own the road, but we shouldn't tempt it."] = "\\u0627\\u0644\\u0644\\u064A\\u0644 \\u0645\\u0648 \\u0645\\u0627\\u0644\\u0643 \\u0627\\u0644\\u0637\\u0631\\u064A\\u0642\\u060C \\u0628\\u0633 \\u0644\\u0627 \\u0646\\u0633\\u062A\\u0641\\u0632\\u0647."
t["Night folds over the camp, one room at a time."] = "\\u0627\\u0644\\u0644\\u064A\\u0644 \\u0628\\u064A\\u0637\\u0648\\u064A \\u0627\\u0644\\u0645\\u062E\\u064A\\u0645 \\u063A\\u0631\\u0641\\u0629 \\u063A\\u0631\\u0641\\u0629."
t["Night watch: every shadow gets a name, then a backstory."] = "\\u0645\\u0646\\u0627\\u0648\\u0628\\u0629 \\u0644\\u064A\\u0644: \\u0643\\u0644 \\u062E\\u064A\\u0627\\u0644 \\u0628\\u064A\\u0627\\u062E\\u062F \\u0627\\u0633\\u0645\\u060C \\u0648\\u0628\\u0639\\u062F\\u064A\\u0646 \\u0642\\u0635\\u0629 \\u062D\\u064A\\u0627\\u0629."
t["No active job. I'm %1."] = "\\u0645\\u0627 \\u0641\\u064A \\u0634\\u063A\\u0644 \\u0642\\u0627\\u064A\\u0645. \\u0634\\u063A\\u0644\\u062A\\u064A %1."
t["No ammunition. I'm not going any closer."] = "\\u0645\\u0627 \\u0645\\u0639\\u064A \\u0631\\u0635\\u0627\\u0635. \\u0645\\u0648 \\u0645\\u0642\\u0631\\u0651\\u0628\\u0629 \\u0623\\u0643\\u062A\\u0631."
t["No anger. I just know where I need to be."] = "\\u0628\\u0644\\u0627 \\u0632\\u0639\\u0644. \\u0628\\u0633 \\u0628\\u0639\\u0631\\u0641 \\u0648\\u064A\\u0646 \\u0644\\u0627\\u0632\\u0645 \\u0643\\u0648\\u0646."
t["No audience, no encore. Just water."] = "\\u0644\\u0627 \\u062C\\u0645\\u0647\\u0648\\u0631 \\u0648\\u0644\\u0627 \\u0625\\u0639\\u0627\\u062F\\u0629. \\u0628\\u0633 \\u0645\\u064A."
t["No bait. The fish have negotiated well."] = "\\u0645\\u0627 \\u0641\\u064A \\u0637\\u0639\\u0645. \\u0627\\u0644\\u0633\\u0645\\u0643 \\u0641\\u0627\\u0648\\u0636 \\u0645\\u0646\\u064A\\u062D."
t["No breath, no fight. I'm falling back."] = "\\u0628\\u0644\\u0627 \\u0646\\u0641\\u0633 \\u0645\\u0627 \\u0641\\u064A \\u0642\\u062A\\u0627\\u0644. \\u0639\\u0645 \\u0627\\u0631\\u062C\\u0639 \\u0644\\u0648\\u0631\\u0627."
t["No bullets means no advance. I'm checking my pockets."] = "\\u0628\\u0644\\u0627 \\u0631\\u0635\\u0627\\u0635 \\u0628\\u0644\\u0627 \\u062A\\u0642\\u062F\\u0645. \\u0639\\u0645 \\u0634\\u064A\\u0651\\u0643 \\u062C\\u064A\\u0648\\u0628\\u064A."
t["No clean front anymore. I'm coming back."] = "\\u0645\\u0627 \\u0639\\u0627\\u062F \\u0641\\u064A \\u062C\\u0628\\u0647\\u0629 \\u0646\\u0636\\u064A\\u0641\\u0629. \\u0631\\u0627\\u062C\\u0639\\u0629."
t["No elbow room, no fight. I'm backing through that gap."] = "\\u0644\\u0627 \\u0645\\u0637\\u0631\\u062D \\u0644\\u0644\\u0643\\u0648\\u0639\\u060C \\u0644\\u0627 \\u0642\\u062A\\u0627\\u0644. \\u0639\\u0645 \\u0627\\u0631\\u062C\\u0639 \\u0645\\u0646 \\u0647\\u0627\\u0644\\u0641\\u062A\\u062D\\u0629."
t["No escape route. Absolutely not."] = "\\u0645\\u0627 \\u0641\\u064A \\u0637\\u0631\\u064A\\u0642 \\u0647\\u0631\\u0648\\u0628. \\u0645\\u0633\\u062A\\u062D\\u064A\\u0644."
t["No fear now. Get out of here."] = "\\u0645\\u0627 \\u0628\\u0642\\u0649 \\u0641\\u064A \\u062E\\u0648\\u0641. \\u0641\\u0644 \\u0645\\u0646 \\u0647\\u0648\\u0646."
t["No fins. Just a souvenir from better garbage collection."] = "\\u0645\\u0627 \\u0641\\u064A \\u0632\\u0639\\u0627\\u0646\\u0641. \\u0628\\u0633 \\u062A\\u0630\\u0643\\u0627\\u0631 \\u0645\\u0646 \\u0623\\u064A\\u0627\\u0645 \\u0645\\u0627 \\u0643\\u0627\\u0646 \\u0641\\u064A \\u0632\\u0628\\u0627\\u0644\\u064A\\u0646."
t["No footing, no weapon - I need assistance!"] = "\\u0644\\u0627 \\u0623\\u0631\\u0636 \\u0648\\u0644\\u0627 \\u0633\\u0644\\u0627\\u062D - \\u0628\\u062F\\u064A \\u0645\\u0633\\u0627\\u0639\\u062F\\u0629!"
t["No front, no flank, just teeth. I'm leaving."] = "\\u0644\\u0627 \\u062C\\u0628\\u0647\\u0629 \\u0648\\u0644\\u0627 \\u062C\\u0646\\u0628\\u060C \\u0628\\u0633 \\u0633\\u0646\\u0627\\u0646. \\u0637\\u0627\\u0644\\u0639\\u0629."
t["No fueled blowtorch. Cold metal doesn't give a hoot."] = "\\u0645\\u0627 \\u0641\\u064A \\u0634\\u0627\\u0644\\u064A\\u0645\\u0648 \\u0645\\u0639\\u0628\\u0651\\u0649. \\u0627\\u0644\\u062D\\u062F\\u064A\\u062F \\u0627\\u0644\\u0628\\u0627\\u0631\\u062F \\u0645\\u0648 \\u0633\\u0627\\u0626\\u0644 \\u0639\\u0646 \\u062D\\u062F\\u0627."
t["No fueled blowtorch. Cold metal doesn't give a shit."] = "\\u0645\\u0627 \\u0641\\u064A \\u0634\\u0627\\u0644\\u064A\\u0645\\u0648 \\u0645\\u0639\\u0628\\u0651\\u0649. \\u0627\\u0644\\u062D\\u062F\\u064A\\u062F \\u0627\\u0644\\u0628\\u0627\\u0631\\u062F \\u0645\\u0627 \\u0641\\u0627\\u0631\\u0642\\u0629 \\u0645\\u0639\\u0647\\u060C \\u064A\\u0644\\u0639\\u0646 \\u0623\\u0628\\u0648\\u0647."
t["No fueled torch in our supplies. Can we look for one?"] = "\\u0645\\u0627 \\u0641\\u064A \\u0634\\u0627\\u0644\\u064A\\u0645\\u0648 \\u0645\\u0639\\u0628\\u0651\\u0649 \\u0639\\u0646\\u0627. \\u0641\\u064A\\u0646\\u0627 \\u0646\\u062F\\u0648\\u0631 \\u0639\\u0644\\u0649 \\u0648\\u0627\\u062D\\u062F\\u061F"
t["No good. I don't have the lumber I need."] = "\\u0645\\u0627 \\u0628\\u062A\\u0632\\u0628\\u0637. \\u0627\\u0644\\u062E\\u0634\\u0628 \\u0627\\u0644\\u0644\\u064A \\u0628\\u062F\\u064A \\u064A\\u0627\\u0647 \\u0645\\u0648 \\u0639\\u0646\\u062F\\u064A."
t["No hammer, no carpentry. Can we find one?"] = "\\u0628\\u0644\\u0627 \\u0634\\u0627\\u0643\\u0648\\u0634 \\u0645\\u0627 \\u0641\\u064A \\u0646\\u062C\\u0627\\u0631\\u0629. \\u0641\\u064A\\u0646\\u0627 \\u0646\\u0644\\u0627\\u0642\\u064A \\u0648\\u0627\\u062D\\u062F\\u061F"
t["No hammer. The wall can wait patiently."] = "\\u0645\\u0627 \\u0641\\u064A \\u0634\\u0627\\u0643\\u0648\\u0634. \\u0627\\u0644\\u062D\\u064A\\u0637 \\u0628\\u064A\\u0642\\u062F\\u0631 \\u064A\\u0633\\u062A\\u0646\\u0649 \\u0639\\u0627\\u0644\\u0647\\u062F\\u0627."
t["No hard feelings. I'll manage."] = "\\u0645\\u0627 \\u0641\\u064A \\u0632\\u0639\\u0644. \\u0628\\u062F\\u0628\\u0631 \\u062D\\u0627\\u0644\\u064A."
t["No heroic detours, then. We get what we need and come home."] = "\\u0628\\u0644\\u0627 \\u0628\\u0637\\u0648\\u0644\\u0627\\u062A \\u0648\\u062A\\u0644\\u0641\\u064A\\u0641\\u0627\\u062A. \\u0645\\u0646\\u062C\\u064A\\u0628 \\u0627\\u0644\\u0644\\u064A \\u0628\\u062F\\u0646\\u0627 \\u064A\\u0627\\u0647 \\u0648\\u0645\\u0646\\u0631\\u062C\\u0639."
t["No heroics until I eat. I mean it."] = "\\u0645\\u0627 \\u0641\\u064A \\u0628\\u0637\\u0648\\u0644\\u0627\\u062A \\u0644\\u062D\\u062A\\u0649 \\u0622\\u0643\\u0644. \\u0639\\u0645 \\u0628\\u062D\\u0643\\u064A \\u062C\\u062F."
t["No heroics! Cut a path!"] = "\\u0628\\u0644\\u0627 \\u0628\\u0637\\u0648\\u0644\\u0627\\u062A! \\u0634\\u0642 \\u0637\\u0631\\u064A\\u0642!"
t["No holding that tide. I'm stepping away from the shore."] = "\\u0645\\u0627 \\u062D\\u062F\\u0627 \\u0628\\u064A\\u0648\\u0642\\u0641 \\u0647\\u0627\\u0644\\u0645\\u0648\\u062C. \\u0639\\u0645 \\u0627\\u0628\\u0639\\u062F \\u0639\\u0646 \\u0627\\u0644\\u0634\\u0637."
t["No leverage. The barricade has won a temporary victory."] = "\\u0645\\u0627 \\u0641\\u064A \\u0642\\u0648\\u0629 \\u0631\\u0641\\u0639. \\u0627\\u0644\\u062D\\u0627\\u062C\\u0632 \\u0631\\u0628\\u062D \\u0646\\u0635\\u0631 \\u0645\\u0624\\u0642\\u062A."
t["No luck with %1. Trying again in %2, with modest expectations."] = "\\u0645\\u0627 \\u0641\\u064A \\u062D\\u0638 \\u0645\\u0639 %1. \\u0631\\u062D \\u062C\\u0631\\u0628 \\u0643\\u0645\\u0627\\u0646 %2\\u060C \\u0648\\u062A\\u0648\\u0642\\u0639\\u0627\\u062A\\u064A \\u0645\\u062A\\u0648\\u0627\\u0636\\u0639\\u0629."
t["No lumber. That's put a firm limit on the carpentry."] = "\\u0645\\u0627 \\u0641\\u064A \\u062E\\u0634\\u0628. \\u0647\\u064A\\u0643 \\u0627\\u0644\\u0646\\u062C\\u0627\\u0631\\u0629 \\u062E\\u0644\\u0635\\u062A \\u0642\\u0628\\u0644 \\u0645\\u0627 \\u062A\\u0628\\u0644\\u0634."
t["No margin for a stumble. I'm opening the distance now."] = "\\u0645\\u0627 \\u0641\\u064A \\u0647\\u0627\\u0645\\u0634 \\u0644\\u062A\\u0639\\u062B\\u0631\\u0629. \\u0639\\u0645 \\u0643\\u0628\\u0631 \\u0627\\u0644\\u0645\\u0633\\u0627\\u0641\\u0629 \\u0647\\u0644\\u0623."
t["No mirror today. I know how I look."] = "\\u0628\\u0644\\u0627 \\u0645\\u0631\\u0627\\u064A\\u0629 \\u0627\\u0644\\u064A\\u0648\\u0645. \\u0628\\u0639\\u0631\\u0641 \\u0634\\u0643\\u0644\\u064A."
t["No more battles for me. You still have yours."] = "\\u062E\\u0644\\u0635\\u062A \\u0645\\u0639\\u0627\\u0631\\u0643\\u064A. \\u0625\\u0646\\u062A \\u0644\\u0633\\u0627 \\u0639\\u0646\\u062F\\u0643 \\u0645\\u0639\\u0627\\u0631\\u0643\\u0643."
t["No more close quarters with you. Not tonight."] = "\\u062E\\u0644\\u0635 \\u0645\\u0627 \\u0641\\u064A \\u0642\\u0631\\u0628 \\u0645\\u0646\\u0643. \\u0645\\u0648 \\u0627\\u0644\\u0644\\u064A\\u0644\\u0629."
t["No more ground until I get a drink."] = "\\u0648\\u0644\\u0627 \\u062E\\u0637\\u0648\\u0629 \\u0643\\u0645\\u0627\\u0646 \\u0644\\u062D\\u062A\\u0649 \\u0627\\u0634\\u0631\\u0628."
t["No more pushing. I can barely stand."] = "\\u062E\\u0644\\u0635 \\u063A\\u0635\\u0628. \\u0628\\u0627\\u0644\\u0643\\u0627\\u062F \\u0648\\u0627\\u0642\\u0641\\u0629."
t["No more second chances!"] = "\\u0645\\u0627 \\u0639\\u0627\\u062F \\u0641\\u064A \\u0641\\u0631\\u0635 \\u062A\\u0627\\u0646\\u064A\\u0629!"
t["No more standing still while you swing."] = "\\u0645\\u0627 \\u0639\\u0627\\u062F \\u0641\\u064A\\u0646\\u064A \\u0648\\u0642\\u0641 \\u0648\\u0627\\u0646\\u062A \\u0639\\u0645 \\u062A\\u0636\\u0631\\u0628."
t["No more treatment, %1. Spend it on someone who has time."] = "\\u062E\\u0644\\u0635 \\u0639\\u0644\\u0627\\u062C \\u064A\\u0627 %1. \\u062E\\u0644\\u064A\\u0647 \\u0644\\u062D\\u062F\\u0627 \\u0644\\u0633\\u0627 \\u0639\\u0646\\u062F\\u0647 \\u0648\\u0642\\u062A."
t["No more. Keep your distance."] = "\\u0628\\u0643\\u0641\\u064A. \\u0636\\u0644 \\u0628\\u0639\\u064A\\u062F."
t["No movement, no new orders. Continuing to gather dust."] = "\\u0644\\u0627 \\u062D\\u0631\\u0643\\u0629 \\u0648\\u0644\\u0627 \\u0623\\u0648\\u0627\\u0645\\u0631 \\u062C\\u062F\\u064A\\u062F\\u0629. \\u0645\\u0633\\u062A\\u0645\\u0631\\u0629 \\u0628\\u062C\\u0645\\u0639 \\u0627\\u0644\\u063A\\u0628\\u0631\\u0629."
t["No nails. Everything else was going almost suspiciously well."] = "\\u0645\\u0627 \\u0641\\u064A \\u0628\\u0633\\u0627\\u0645\\u064A\\u0631. \\u0642\\u0644\\u062A \\u0644\\u062D\\u0627\\u0644\\u064A\\u060C \\u0627\\u0644\\u0623\\u0645\\u0648\\u0631 \\u0645\\u0627\\u0634\\u064A\\u0629 \\u0645\\u0646\\u064A\\u062D \\u0632\\u064A\\u0627\\u062F\\u0629."
t["No need to rush into a bad surprise."] = "\\u0645\\u0627 \\u0641\\u064A \\u062F\\u0627\\u0639\\u064A \\u0646\\u0631\\u0643\\u0636 \\u0639\\u0644\\u0649 \\u0645\\u0641\\u0627\\u062C\\u0623\\u0629 \\u0639\\u0627\\u0637\\u0644\\u0629."
t["No need to worry about me right now."] = "\\u0645\\u0627 \\u0641\\u064A \\u062F\\u0627\\u0639\\u064A \\u062A\\u0642\\u0644\\u0642 \\u0639\\u0644\\u064A\\u064A \\u0647\\u0644\\u0623."
t["No news is not always good news anymore."] = "\\u0645\\u0627 \\u0639\\u0627\\u062F \\u062F\\u0627\\u064A\\u0645\\u0627\\u064B \\u0639\\u062F\\u0645 \\u0627\\u0644\\u0623\\u062E\\u0628\\u0627\\u0631 \\u062E\\u0628\\u0631 \\u0645\\u0646\\u064A\\u062D."
t["No no no - get them OFF!"] = "\\u0644\\u0627 \\u0644\\u0627 \\u0644\\u0627 - \\u0634\\u064A\\u0644\\u0646 \\u0639\\u0646\\u064A!"
t["No one answered the air. Maybe tomorrow."] = "\\u0645\\u0627 \\u062D\\u062F\\u0627 \\u0631\\u062F \\u0639\\u0627\\u0644\\u0647\\u0648\\u0627. \\u064A\\u0645\\u0643\\u0646 \\u0628\\u0643\\u0631\\u0627."
t["No one else has to do this for me."] = "\\u0645\\u0627 \\u062D\\u062F\\u0627 \\u0644\\u0627\\u0632\\u0645 \\u064A\\u0639\\u0645\\u0644\\u0647\\u0627 \\u0639\\u0646\\u064A."
t["No opening between them. I'm waiting for a better one."] = "\\u0645\\u0627 \\u0641\\u064A \\u0641\\u062A\\u062D\\u0629 \\u0628\\u064A\\u0646\\u0627\\u062A\\u0647\\u0646. \\u0631\\u062D \\u0627\\u0633\\u062A\\u0646\\u0649 \\u0648\\u062D\\u062F\\u0629 \\u0623\\u062D\\u0633\\u0646."
t["No pain, no gain. Plenty of pain lately."] = "\\u0628\\u0644\\u0627 \\u0623\\u0644\\u0645 \\u0645\\u0627 \\u0641\\u064A \\u0646\\u062A\\u064A\\u062C\\u0629. \\u0627\\u0644\\u0623\\u0644\\u0645 \\u0643\\u062A\\u064A\\u0631 \\u0647\\u0627\\u0644\\u0641\\u062A\\u0631\\u0629."
t["No panic. Quarantine first, then we decide with clear heads."] = "\\u0628\\u0644\\u0627 \\u0647\\u0644\\u0639. \\u0627\\u0644\\u0639\\u0632\\u0644 \\u0623\\u0648\\u0644 \\u0634\\u064A\\u060C \\u0628\\u0639\\u062F\\u064A\\u0646 \\u0645\\u0646\\u0642\\u0631\\u0631 \\u0648\\u0631\\u0627\\u0633\\u0646\\u0627 \\u0628\\u0627\\u0631\\u062F."
t["No plank means no progress. Find me one solid piece."] = "\\u0628\\u0644\\u0627 \\u0644\\u0648\\u062D \\u0645\\u0627 \\u0641\\u064A \\u062A\\u0642\\u062F\\u0645. \\u062F\\u0628\\u0631\\u0644\\u064A \\u0634\\u0642\\u0641\\u0629 \\u0642\\u0648\\u064A\\u0629."
t["No plumbing, no queue. Small mercies."] = "\\u0644\\u0627 \\u0645\\u0648\\u0627\\u0633\\u064A\\u0631 \\u0648\\u0644\\u0627 \\u062F\\u0648\\u0631. \\u0646\\u0639\\u0645 \\u0635\\u063A\\u064A\\u0631\\u0629."
t["No pot. The soup remains a collection of opinions."] = "\\u0645\\u0627 \\u0641\\u064A \\u0637\\u0646\\u062C\\u0631\\u0629. \\u0627\\u0644\\u0634\\u0648\\u0631\\u0628\\u0629 \\u0644\\u0633\\u0627 \\u0645\\u062C\\u0631\\u062F \\u0648\\u062C\\u0647\\u0627\\u062A \\u0646\\u0638\\u0631."
t["No pressing task, so I'm %1 for a bit."] = "\\u0645\\u0627 \\u0641\\u064A \\u0634\\u064A \\u0636\\u0631\\u0648\\u0631\\u064A\\u060C \\u0641\\u0634\\u063A\\u0644\\u062A\\u064A %1 \\u0634\\u0648\\u064A."
t["No pulse. Clear."] = "\\u0645\\u0627 \\u0641\\u064A \\u0646\\u0628\\u0636. \\u0646\\u0636\\u064A\\u0641."
t["No reaction. Time for an actual escape."] = "\\u0648\\u0644\\u0627 \\u0631\\u062F\\u0629 \\u0641\\u0639\\u0644. \\u0648\\u0642\\u062A \\u0627\\u0644\\u0647\\u0631\\u0648\\u0628 \\u0627\\u0644\\u062C\\u062F."
t["No real plan yet. I am still working that out."] = "\\u0644\\u0633\\u0627 \\u0645\\u0627 \\u0641\\u064A \\u062E\\u0637\\u0629 \\u0639\\u0646 \\u062C\\u062F. \\u0639\\u0645 \\u0627\\u0634\\u062A\\u063A\\u0644 \\u0639\\u0644\\u064A\\u0647\\u0627."
t["No rescue possible. Withdraw, %1."] = "\\u0645\\u0627 \\u0641\\u064A \\u0625\\u0646\\u0642\\u0627\\u0630. \\u0627\\u0646\\u0633\\u062D\\u0628 \\u064A\\u0627 %1."
t["No room for both of us. I'm coming toward you."] = "\\u0645\\u0627 \\u0641\\u064A \\u0645\\u0637\\u0631\\u062D \\u0644\\u062A\\u0646\\u064A\\u0646\\u0627\\u062A\\u0646\\u0627. \\u062C\\u0627\\u064A\\u0629 \\u0644\\u0639\\u0646\\u062F\\u0643."
t["No room for mistakes in here. I'm retreating to daylight."] = "\\u0645\\u0627 \\u0641\\u064A \\u0645\\u062C\\u0627\\u0644 \\u0644\\u063A\\u0644\\u0637\\u0629 \\u0647\\u0648\\u0646. \\u0631\\u0627\\u062C\\u0639\\u0629 \\u0639\\u0627\\u0644\\u0636\\u0648."
t["No room to plant my feet. Moving."] = "\\u0645\\u0627 \\u0641\\u064A \\u0645\\u0637\\u0631\\u062D \\u062B\\u0628\\u062A \\u0625\\u062C\\u0631\\u064A\\u064A. \\u0639\\u0645 \\u0627\\u062A\\u062D\\u0631\\u0643."
t["No rounds left. I'm backing off."] = "\\u062E\\u0644\\u0635 \\u0627\\u0644\\u0631\\u0635\\u0627\\u0635. \\u0639\\u0645 \\u0627\\u0628\\u0639\\u062F."
t["No screwdriver, no disassembly. I'd like the parts afterward."] = "\\u0628\\u0644\\u0627 \\u0645\\u0641\\u0643 \\u0645\\u0627 \\u0641\\u064A \\u0641\\u0643. \\u0648\\u0623\\u0646\\u0627 \\u0628\\u062F\\u064A \\u0627\\u0644\\u0642\\u0637\\u0639 \\u0628\\u0639\\u062F\\u064A\\u0646."
t["No screwdriver. It gets to remain assembled for now."] = "\\u0645\\u0627 \\u0641\\u064A \\u0645\\u0641\\u0643. \\u062E\\u0644\\u0651\\u064A\\u0647\\u0627 \\u0645\\u0631\\u0643\\u0628\\u0629 \\u0644\\u0647\\u0644\\u0623."
t["No second exit means no second chance. I'm waiting here."] = "\\u0645\\u0627 \\u0641\\u064A \\u0645\\u062E\\u0631\\u062C \\u062A\\u0627\\u0646\\u064A \\u064A\\u0639\\u0646\\u064A \\u0645\\u0627 \\u0641\\u064A \\u0641\\u0631\\u0635\\u0629 \\u062A\\u0627\\u0646\\u064A\\u0629. \\u0645\\u0633\\u062A\\u0646\\u064A\\u0629 \\u0647\\u0648\\u0646."
t["No shame in stopping while we still can."] = "\\u0645\\u0627 \\u0641\\u064A \\u0639\\u064A\\u0628 \\u0646\\u0648\\u0642\\u0641 \\u0637\\u0627\\u0644\\u0645\\u0627 \\u0644\\u0633\\u0627 \\u0641\\u064A\\u0646\\u0627."
t["No shovel in the supplies. I can't get this hole started."] = "\\u0645\\u0627 \\u0641\\u064A \\u0643\\u0631\\u064A\\u0643 \\u0628\\u0627\\u0644\\u0623\\u063A\\u0631\\u0627\\u0636. \\u0645\\u0627 \\u0641\\u064A\\u0646\\u064A \\u0628\\u0644\\u0651\\u0634 \\u0628\\u0647\\u0627\\u0644\\u062D\\u0641\\u0631\\u0629."
t["No solid footing here. I'm backing toward the clear patch."] = "\\u0645\\u0627 \\u0641\\u064A \\u0623\\u0631\\u0636 \\u062B\\u0627\\u0628\\u062A\\u0629 \\u0647\\u0648\\u0646. \\u0639\\u0645 \\u0627\\u0631\\u062C\\u0639 \\u0639\\u0627\\u0644\\u0628\\u0642\\u0639\\u0629 \\u0627\\u0644\\u0641\\u0627\\u0636\\u064A\\u0629."
t["No sound hammer. Even the damn tools have given up."] = "\\u0645\\u0627 \\u0641\\u064A \\u0634\\u0627\\u0643\\u0648\\u0634 \\u0633\\u0644\\u064A\\u0645. \\u062D\\u062A\\u0649 \\u0647\\u0627\\u0644\\u0639\\u062F\\u0629 \\u0627\\u0644\\u0645\\u0644\\u0639\\u0648\\u0646\\u0629 \\u0627\\u0633\\u062A\\u0633\\u0644\\u0645\\u062A."
t["No sound hammer. Even the darn tools have given up."] = "\\u0645\\u0627 \\u0641\\u064A \\u0634\\u0627\\u0643\\u0648\\u0634 \\u0633\\u0644\\u064A\\u0645. \\u062D\\u062A\\u0649 \\u0647\\u0627\\u0644\\u0639\\u062F\\u0629 \\u0627\\u0644\\u0645\\u0639\\u062A\\u0631\\u0629 \\u0627\\u0633\\u062A\\u0633\\u0644\\u0645\\u062A."
t["No spark. Give me another shot later."] = "\\u0645\\u0627 \\u0641\\u064A \\u0634\\u0631\\u0627\\u0631\\u0629. \\u062E\\u0644\\u064A\\u0646\\u064A \\u062C\\u0631\\u0628 \\u0643\\u0645\\u0627\\u0646 \\u0634\\u0648\\u064A."
t["No stain left. The smell will take longer."] = "\\u0631\\u0627\\u062D\\u062A \\u0627\\u0644\\u0628\\u0642\\u0639\\u0629. \\u0627\\u0644\\u0631\\u064A\\u062D\\u0629 \\u0628\\u062F\\u0647\\u0627 \\u0648\\u0642\\u062A."
t["No stamina for safe withdrawal afterward. Recovering before contact."] = "\\u0645\\u0627 \\u0645\\u0639\\u064A \\u0646\\u0641\\u0633 \\u0644\\u0644\\u0627\\u0646\\u0633\\u062D\\u0627\\u0628 \\u0628\\u0639\\u062F\\u064A\\u0646. \\u0628\\u0631\\u062A\\u0627\\u062D \\u0642\\u0628\\u0644 \\u0645\\u0627 \\u0646\\u0634\\u062A\\u0628\\u0643."
t["No stove and no fire. This meal has to wait."] = "\\u0644\\u0627 \\u063A\\u0627\\u0632 \\u0648\\u0644\\u0627 \\u0646\\u0627\\u0631. \\u0647\\u0627\\u0644\\u0623\\u0643\\u0644\\u0629 \\u0644\\u0627\\u0632\\u0645 \\u062A\\u0633\\u062A\\u0646\\u0649."
t["No strength for another round. I'm resting where it's clear."] = "\\u0645\\u0627 \\u0641\\u064A\\u0646\\u064A \\u0639\\u0644\\u0649 \\u062C\\u0648\\u0644\\u0629 \\u062A\\u0627\\u0646\\u064A\\u0629. \\u0631\\u062D \\u0627\\u0631\\u062A\\u0627\\u062D \\u0628\\u0645\\u062D\\u0644 \\u0641\\u0627\\u0636\\u064A."
t["No success with %1 yet. I'm trying again in %2."] = "\\u0644\\u0633\\u0627 \\u0645\\u0627 \\u0632\\u0628\\u0637 \\u0645\\u0639\\u064A %1. \\u0631\\u062D \\u062C\\u0631\\u0628 \\u0643\\u0645\\u0627\\u0646 %2."
t["No trouble here. Just making sure the wire's alive."] = "\\u0645\\u0627 \\u0641\\u064A \\u0645\\u0634\\u0643\\u0644\\u0629 \\u0647\\u0648\\u0646. \\u0628\\u0633 \\u0639\\u0645 \\u0627\\u062A\\u0623\\u0643\\u062F \\u0627\\u0644\\u062E\\u0637 \\u0644\\u0633\\u0627 \\u0639\\u0627\\u064A\\u0634."
t["No trouble. Let's go."] = "\\u0645\\u0627 \\u0641\\u064A \\u0645\\u0634\\u0643\\u0644\\u0629. \\u064A\\u0644\\u0627."
t["No trouble. Maybe another time."] = "\\u0645\\u0627 \\u0641\\u064A \\u0645\\u0634\\u0643\\u0644\\u0629. \\u0645\\u0631\\u0629 \\u062A\\u0627\\u0646\\u064A\\u0629."
t["No urgent problems. I am ready to move."] = "\\u0645\\u0627 \\u0641\\u064A \\u0645\\u0634\\u0627\\u0643\\u0644 \\u0636\\u0631\\u0648\\u0631\\u064A\\u0629. \\u062C\\u0627\\u0647\\u0632\\u0629 \\u0627\\u062A\\u062D\\u0631\\u0643."
t["No usable axe in our supplies. Lumber work is stopped."] = "\\u0645\\u0627 \\u0641\\u064A \\u0641\\u0627\\u0633 \\u064A\\u0646\\u0641\\u0639 \\u0628\\u0623\\u063A\\u0631\\u0627\\u0636\\u0646\\u0627. \\u0634\\u063A\\u0644 \\u0627\\u0644\\u062E\\u0634\\u0628 \\u0648\\u0627\\u0642\\u0641."
t["No usable torch. So much for that job."] = "\\u0645\\u0627 \\u0641\\u064A \\u0634\\u0627\\u0644\\u064A\\u0645\\u0648 \\u064A\\u0646\\u0641\\u0639. \\u0631\\u0627\\u062D\\u062A \\u0647\\u0627\\u0644\\u0634\\u063A\\u0644\\u0629."
t["No vacancy. Plenty of vacancy."] = "\\u0644\\u0627 \\u063A\\u0631\\u0641 \\u0641\\u0627\\u0636\\u064A\\u0629. \\u0641\\u064A \\u0643\\u062A\\u064A\\u0631 \\u063A\\u0631\\u0641 \\u0641\\u0627\\u0636\\u064A\\u0629."
t["No visible threat. The room still warrants another sweep."] = "\\u0645\\u0627 \\u0641\\u064A \\u062E\\u0637\\u0631 \\u0645\\u0628\\u064A\\u0646. \\u0628\\u0633 \\u0627\\u0644\\u063A\\u0631\\u0641\\u0629 \\u0628\\u062F\\u0647\\u0627 \\u062A\\u0645\\u0634\\u064A\\u0637\\u0629 \\u0643\\u0645\\u0627\\u0646."
t["No way out of that room. Not doing it."] = "\\u0645\\u0627 \\u0641\\u064A \\u0637\\u0644\\u0639\\u0629 \\u0645\\u0646 \\u0647\\u0627\\u0644\\u063A\\u0631\\u0641\\u0629. \\u0645\\u0648 \\u0641\\u0627\\u064A\\u062A\\u0629."
t["No weapon. Engagement isn't viable."] = "\\u0628\\u0644\\u0627 \\u0633\\u0644\\u0627\\u062D. \\u0627\\u0644\\u0627\\u0634\\u062A\\u0628\\u0627\\u0643 \\u0645\\u0648 \\u0648\\u0627\\u0631\\u062F."
t["No working saw. The log seems pleased."] = "\\u0645\\u0627 \\u0641\\u064A \\u0645\\u0646\\u0634\\u0627\\u0631 \\u0634\\u063A\\u0651\\u0627\\u0644. \\u0627\\u0644\\u062C\\u0630\\u0639 \\u0645\\u0628\\u0633\\u0648\\u0637 \\u0643\\u062A\\u064A\\u0631."
t["No working tool. The dirt has earned a short reprieve."] = "\\u0645\\u0627 \\u0641\\u064A \\u0639\\u062F\\u0629 \\u0634\\u063A\\u0651\\u0627\\u0644\\u0629. \\u0627\\u0644\\u062A\\u0631\\u0627\\u0628 \\u0643\\u0633\\u0628 \\u0627\\u0633\\u062A\\u0631\\u0627\\u062D\\u0629 \\u0642\\u0635\\u064A\\u0631\\u0629."
t["No, no, no - %1, HELP!"] = "\\u0644\\u0627 \\u0644\\u0627 \\u0644\\u0627 - %1, \\u0633\\u0627\\u0639\\u062F\\u0646\\u064A!"
t["No, no, no. It slipped the hook."] = "\\u0644\\u0627\\u060C \\u0644\\u0627\\u060C \\u0644\\u0627. \\u0641\\u0644\\u062A\\u062A \\u0645\\u0646 \\u0627\\u0644\\u0635\\u0646\\u0627\\u0631\\u0629."
t["No. Everyone hears this, right now."] = "\\u0644\\u0623. \\u0627\\u0644\\u0643\\u0644 \\u0628\\u064A\\u0633\\u0645\\u0639 \\u0647\\u0627\\u062F\\u060C \\u0647\\u0644\\u0623."
t["No. I want another way."] = "\\u0644\\u0623. \\u0628\\u062F\\u064A \\u0637\\u0631\\u064A\\u0642\\u0629 \\u062A\\u0627\\u0646\\u064A\\u0629."
t["No. My name is %1. Use it."] = "\\u0644\\u0623. \\u0627\\u0633\\u0645\\u064A %1. \\u0627\\u0633\\u062A\\u0639\\u0645\\u0644\\u0647."
t["No. No way. There are too many to count."] = "\\u0644\\u0627. \\u0645\\u0633\\u062A\\u062D\\u064A\\u0644. \\u0643\\u062A\\u0627\\u0631 \\u0645\\u0627 \\u0628\\u064A\\u0646\\u0639\\u062F\\u0648\\u0627."
t["No. That landing is not worth a broken ankle."] = "\\u0644\\u0623. \\u0647\\u0627\\u0644\\u0646\\u0632\\u0644\\u0629 \\u0645\\u0627 \\u0628\\u062A\\u0633\\u0648\\u0649 \\u0643\\u0627\\u062D\\u0644 \\u0645\\u0643\\u0633\\u0648\\u0631."
t["No. We talk about this now, before I lose my nerve."] = "\\u0644\\u0623. \\u0645\\u0646\\u062D\\u0643\\u064A \\u0647\\u0644\\u0623\\u060C \\u0642\\u0628\\u0644 \\u0645\\u0627 \\u064A\\u0631\\u0648\\u062D \\u0642\\u0644\\u0628\\u064A."
t["Nobody asked, but thank you."] = "\\u0645\\u0627 \\u062D\\u062F\\u0627 \\u0633\\u0623\\u0644\\u0643\\u060C \\u0628\\u0633 \\u0634\\u0643\\u0631\\u0627\\u064B."
t["Nobody falls behind. Fight for space!"] = "\\u0645\\u0627 \\u062D\\u062F\\u0627 \\u064A\\u062A\\u0623\\u062E\\u0631. \\u0642\\u0627\\u062A\\u0644 \\u0639\\u0627\\u0644\\u0645\\u0637\\u0631\\u062D!"
t["Nobody followed me. We're clear."] = "\\u0645\\u0627 \\u062D\\u062F\\u0627 \\u0644\\u062D\\u0642\\u0646\\u064A. \\u0627\\u0644\\u0637\\u0631\\u064A\\u0642 \\u0646\\u0636\\u064A\\u0641."
t["Nobody gets a map marker for this stop."] = "\\u0647\\u0627\\u0644\\u0648\\u0642\\u0641\\u0629 \\u0645\\u0627 \\u0628\\u064A\\u0646\\u062D\\u0637\\u0644\\u0647\\u0627 \\u0639\\u0644\\u0627\\u0645\\u0629 \\u0639\\u0627\\u0644\\u062E\\u0631\\u064A\\u0637\\u0629."
t["Nobody gets left behind for a bag of supplies."] = "\\u0645\\u0627 \\u062D\\u062F\\u0627 \\u0628\\u064A\\u0646\\u062A\\u0631\\u0643 \\u0643\\u0631\\u0645\\u0627\\u0644 \\u0634\\u0646\\u062A\\u0629 \\u0645\\u0648\\u0646\\u0629."
t["Nobody gets left on a Kentucky road. Not while I'm breathing."] = "\\u0645\\u0627 \\u062D\\u062F\\u0627 \\u0628\\u064A\\u0646\\u062A\\u0631\\u0643 \\u0639\\u0644\\u0649 \\u0637\\u0631\\u064A\\u0642 \\u0628\\u0643\\u0646\\u062A\\u0627\\u0643\\u064A. \\u0637\\u0627\\u0644\\u0645\\u0627 \\u0623\\u0646\\u0627 \\u0639\\u0645 \\u0627\\u062A\\u0646\\u0641\\u0633."
t["Nobody has jaywalked in weeks. Civic pride, maybe."] = "\\u0645\\u0627 \\u062D\\u062F\\u0627 \\u0642\\u0637\\u0639 \\u0627\\u0644\\u0634\\u0627\\u0631\\u0639 \\u063A\\u0644\\u0637 \\u0645\\u0646 \\u0623\\u0633\\u0627\\u0628\\u064A\\u0639. \\u064A\\u0645\\u0643\\u0646 \\u062D\\u0633 \\u0645\\u062F\\u0646\\u064A."
t["Nobody hears it from me. Promise me you'll tell them yourself."] = "\\u0645\\u0627 \\u062D\\u062F\\u0627 \\u0628\\u064A\\u0633\\u0645\\u0639\\u0647\\u0627 \\u0645\\u0646\\u064A. \\u0648\\u0639\\u062F\\u0646\\u064A \\u062A\\u062E\\u0628\\u0631\\u0647\\u0646 \\u0625\\u0646\\u062A."
t["Nobody ignores a wound today. I mean it."] = "\\u0645\\u0627 \\u062D\\u062F\\u0627 \\u0628\\u064A\\u0637\\u0646\\u0634 \\u062C\\u0631\\u062D \\u0627\\u0644\\u064A\\u0648\\u0645. \\u0639\\u0645 \\u0628\\u062D\\u0643\\u064A \\u062C\\u062F."
t["Nobody is bleeding yet, but we are out of clean bandages."] = "\\u0645\\u0627 \\u062D\\u062F\\u0627 \\u0639\\u0645 \\u064A\\u0646\\u0632\\u0641 \\u0644\\u0633\\u0627\\u060C \\u0628\\u0633 \\u062E\\u0644\\u0635 \\u0627\\u0644\\u0634\\u0627\\u0634 \\u0627\\u0644\\u0646\\u0636\\u064A\\u0641."
t["Nobody panics, and nobody sleeps alone near them. That's the plan."] = "\\u0645\\u0627 \\u062D\\u062F\\u0627 \\u064A\\u0647\\u0644\\u0639\\u060C \\u0648\\u0645\\u0627 \\u062D\\u062F\\u0627 \\u064A\\u0646\\u0627\\u0645 \\u0644\\u062D\\u0627\\u0644\\u0647 \\u062C\\u0646\\u0628\\u0647\\u0646. \\u0647\\u064A \\u0627\\u0644\\u062E\\u0637\\u0629."
t["Nobody rush me. The dead can wait outside."] = "\\u0645\\u0627 \\u062D\\u062F\\u0627 \\u064A\\u0633\\u062A\\u0639\\u062C\\u0644\\u0646\\u064A. \\u0627\\u0644\\u0645\\u064A\\u062A\\u064A\\u0646 \\u0628\\u064A\\u0633\\u062A\\u0646\\u0648\\u0627 \\u0628\\u0631\\u0627."
t["Nobody says %1 anymore. Feels wrong."] = "\\u0645\\u0627 \\u0639\\u0627\\u062F \\u062D\\u062F\\u0627 \\u064A\\u0642\\u0648\\u0644 %1. \\u0634\\u0639\\u0648\\u0631 \\u063A\\u0644\\u0637."
t["Nobody should have to wake up to this stain."] = "\\u0645\\u0627 \\u062D\\u062F\\u0627 \\u0644\\u0627\\u0632\\u0645 \\u064A\\u0641\\u064A\\u0642 \\u0639\\u0647\\u0627\\u0644\\u0628\\u0642\\u0639\\u0629."
t["Nobody take my clothes. I know what I left there."] = "\\u0645\\u0627 \\u062D\\u062F\\u0627 \\u064A\\u0627\\u062E\\u062F \\u062A\\u064A\\u0627\\u0628\\u064A. \\u0628\\u0639\\u0631\\u0641 \\u0648\\u064A\\u0646 \\u062A\\u0631\\u0643\\u062A\\u0647\\u0646."
t["Nobody thinks about the exit until it is too late."] = "\\u0645\\u0627 \\u062D\\u062F\\u0627 \\u0628\\u064A\\u0641\\u0643\\u0631 \\u0628\\u0627\\u0644\\u0645\\u062E\\u0631\\u062C \\u0644\\u062D\\u062A\\u0649 \\u064A\\u0641\\u0648\\u062A \\u0627\\u0644\\u0623\\u0648\\u0627\\u0646."
t["Nobody to arrest, nobody to call. Still feels like trouble in here."] = "\\u0645\\u0627 \\u0641\\u064A \\u062D\\u062F\\u0627 \\u064A\\u0646\\u062D\\u0628\\u0633 \\u0648\\u0644\\u0627 \\u062D\\u062F\\u0627 \\u0646\\u062A\\u0635\\u0644 \\u0641\\u064A\\u0647. \\u0648\\u0644\\u0633\\u0627 \\u062D\\u0627\\u0633\\u0629 \\u0625\\u0646\\u064A \\u0628\\u0645\\u0634\\u0643\\u0644\\u0629 \\u0647\\u0648\\u0646."
t["Nobody touches them without going through me first."] = "\\u0645\\u0627 \\u062D\\u062F\\u0627 \\u0628\\u064A\\u0642\\u0631\\u0628 \\u0639\\u0644\\u064A\\u0647\\u0646 \\u0642\\u0628\\u0644 \\u0645\\u0627 \\u064A\\u0645\\u0631\\u0642 \\u0639\\u0644\\u064A\\u064A."
t["Nobody wander too far. Let's see what's left here."] = "\\u0645\\u0627 \\u062D\\u062F\\u0627 \\u064A\\u0628\\u0639\\u062F \\u0643\\u062A\\u064A\\u0631. \\u062E\\u0644\\u064A\\u0646\\u0627 \\u0646\\u0634\\u0648\\u0641 \\u0634\\u0648 \\u0636\\u0644 \\u0647\\u0648\\u0646."
t["Nobody wants to be here. Not even now."] = "\\u0645\\u0627 \\u062D\\u062F\\u0627 \\u0628\\u062F\\u0648 \\u064A\\u0643\\u0648\\u0646 \\u0647\\u0648\\u0646. \\u062D\\u062A\\u0649 \\u0647\\u0644\\u0623."
t["Nobody's answering the desk bell. Best service this place ever gave me."] = "\\u0645\\u0627 \\u062D\\u062F\\u0627 \\u0639\\u0645 \\u064A\\u0631\\u062F \\u0639\\u0627\\u0644\\u062C\\u0631\\u0633. \\u0623\\u062D\\u0633\\u0646 \\u062E\\u062F\\u0645\\u0629 \\u0623\\u062E\\u062F\\u062A\\u0647\\u0627 \\u0645\\u0646 \\u0647\\u0627\\u0644\\u0645\\u062D\\u0644."
t["Nobody's timing you. Much."] = "\\u0645\\u0627 \\u062D\\u062F\\u0627 \\u0639\\u0645 \\u064A\\u062D\\u0633\\u0628\\u0644\\u0643 \\u0648\\u0642\\u062A. \\u0643\\u062A\\u064A\\u0631."
t["Nobody's touched their things. Nobody will."] = "\\u0645\\u0627 \\u062D\\u062F\\u0627 \\u0644\\u0645\\u0633 \\u0623\\u063A\\u0631\\u0627\\u0636\\u0647\\u0645. \\u0648\\u0645\\u0627 \\u062D\\u062F\\u0627 \\u0631\\u062D \\u064A\\u0644\\u0645\\u0633."
t["North wind, hold your breath till morning..."] = "\\u064A\\u0627 \\u0631\\u064A\\u062D \\u0627\\u0644\\u0634\\u0645\\u0627\\u0644\\u060C \\u0627\\u062D\\u0628\\u0633\\u064A \\u0646\\u0641\\u0633\\u0643 \\u0644\\u0644\\u0635\\u0628\\u062D..."
t["Not a fish. Not even close."] = "\\u0645\\u0648 \\u0633\\u0645\\u0643\\u0629. \\u0648\\u0644\\u0627 \\u0642\\u0631\\u064A\\u0628\\u0629."
t["Not a word from me. But you tell me the second it gets worse."] = "\\u0648\\u0644\\u0627 \\u0643\\u0644\\u0645\\u0629 \\u0645\\u0646\\u064A. \\u0628\\u0633 \\u0628\\u062A\\u062E\\u0628\\u0631\\u0646\\u064A \\u0623\\u0648\\u0644 \\u0645\\u0627 \\u062A\\u0633\\u0648\\u0621 \\u0627\\u0644\\u062D\\u0627\\u0644\\u0629."
t["Not armed, not ready. I'm backing off."] = "\\u0628\\u0644\\u0627 \\u0633\\u0644\\u0627\\u062D \\u0648\\u0628\\u0644\\u0627 \\u062C\\u0627\\u0647\\u0632\\u064A\\u0629. \\u0639\\u0645 \\u0627\\u0628\\u0639\\u062F."
t["Not both at once!"] = "\\u0645\\u0648 \\u0627\\u0644\\u062A\\u0646\\u064A\\u0646 \\u0633\\u0648\\u0627!"
t["Not done yet, but I am getting tired."] = "\\u0644\\u0633\\u0627 \\u0645\\u0627 \\u062E\\u0644\\u0635\\u062A\\u060C \\u0628\\u0633 \\u0639\\u0645 \\u062A\\u0639\\u0628."
t["Not far. I know the way back."] = "\\u0645\\u0648 \\u0628\\u0639\\u064A\\u062F. \\u0628\\u0639\\u0631\\u0641 \\u0637\\u0631\\u064A\\u0642 \\u0627\\u0644\\u0631\\u062C\\u0639\\u0629."
t["Not getting back up."] = "\\u0645\\u0627 \\u0639\\u0627\\u062F \\u0628\\u064A\\u0642\\u0648\\u0645."
t["Not happening. I need another way."] = "\\u0645\\u0633\\u062A\\u062D\\u064A\\u0644. \\u0628\\u062F\\u064A \\u0637\\u0631\\u064A\\u0642 \\u062A\\u0627\\u0646\\u064A."
t["Not here! Move!"] = "\\u0645\\u0648 \\u0647\\u0648\\u0646! \\u062A\\u062D\\u0631\\u0643!"
t["Not in here. Too tight."] = "\\u0645\\u0648 \\u0647\\u0648\\u0646. \\u0636\\u064A\\u0642 \\u0643\\u062A\\u064A\\u0631."
t["Not like that. Let me keep what time I have."] = "\\u0645\\u0648 \\u0647\\u064A\\u0643. \\u062E\\u0644\\u064A\\u0646\\u064A \\u0639\\u064A\\u0634 \\u0627\\u0644\\u0648\\u0642\\u062A \\u0627\\u0644\\u0644\\u064A \\u0628\\u0627\\u0642\\u064A\\u0644\\u064A."
t["Not like this! We were supposed to make it home!"] = "\\u0645\\u0648 \\u0647\\u064A\\u0643! \\u0643\\u0627\\u0646 \\u0644\\u0627\\u0632\\u0645 \\u0646\\u0631\\u062C\\u0639 \\u0639\\u0627\\u0644\\u0628\\u064A\\u062A!"
t["Not my best work. Effective, though."] = "\\u0645\\u0648 \\u0623\\u062D\\u0633\\u0646 \\u0634\\u063A\\u0644\\u064A. \\u0628\\u0633 \\u0632\\u0628\\u0637."
t["Not now, then. Just remember that we still need it."] = "\\u0645\\u0648 \\u0647\\u0644\\u0623 \\u064A\\u0639\\u0646\\u064A. \\u0628\\u0633 \\u0644\\u0627 \\u062A\\u0646\\u0633\\u0649 \\u0625\\u0646\\u0646\\u0627 \\u0644\\u0633\\u0627 \\u0645\\u062D\\u062A\\u0627\\u062C\\u064A\\u0646\\u0647\\u0627."
t["Not on the body. Beside it. There's a line."] = "\\u0645\\u0648 \\u0639\\u0627\\u0644\\u062C\\u062B\\u0629. \\u062C\\u0646\\u0628\\u0647\\u0627. \\u0641\\u064A \\u062D\\u062F\\u0648\\u062F."
t["Not perfect, but this room feels lived in again."] = "\\u0645\\u0648 \\u0643\\u0627\\u0645\\u0644\\u0629\\u060C \\u0628\\u0633 \\u0627\\u0644\\u063A\\u0631\\u0641\\u0629 \\u0631\\u062C\\u0639\\u062A \\u0643\\u0623\\u0646 \\u0641\\u064A\\u0647\\u0627 \\u0646\\u0627\\u0633."
t["Not safe. Mildly inconvenient, but still not safe."] = "\\u0645\\u0648 \\u0623\\u0645\\u0627\\u0646. \\u0645\\u0632\\u0639\\u062C \\u0634\\u0648\\u064A, \\u0628\\u0633 \\u0628\\u0631\\u0636\\u0648 \\u0645\\u0648 \\u0623\\u0645\\u0627\\u0646."
t["Not this time. There will be another way."] = "\\u0645\\u0648 \\u0647\\u0627\\u0644\\u0645\\u0631\\u0629. \\u0641\\u064A \\u0637\\u0631\\u064A\\u0642 \\u062A\\u0627\\u0646\\u064A \\u0623\\u0643\\u064A\\u062F."
t["Not today."] = "\\u0645\\u0648 \\u0627\\u0644\\u064A\\u0648\\u0645."
t["Not today. This one's fighting back."] = "\\u0645\\u0648 \\u0627\\u0644\\u064A\\u0648\\u0645. \\u0647\\u064A \\u0639\\u0645 \\u062A\\u0642\\u0627\\u0648\\u0645\\u0646\\u064A."
t["Not too much. Drowned roots are no better than dry ones."] = "\\u0645\\u0648 \\u0643\\u062A\\u064A\\u0631. \\u0627\\u0644\\u062C\\u0630\\u0648\\u0631 \\u0627\\u0644\\u063A\\u0631\\u0642\\u0627\\u0646\\u0629 \\u0645\\u062A\\u0644 \\u0627\\u0644\\u0646\\u0627\\u0634\\u0641\\u0629."
t["Not urgent yet, but I am getting hungry."] = "\\u0644\\u0633\\u0627 \\u0645\\u0648 \\u0636\\u0631\\u0648\\u0631\\u064A\\u060C \\u0628\\u0633 \\u0639\\u0645 \\u062C\\u0648\\u0639."
