t["Pair. Peel one off, finish it, repeat!"] = "\\u062A\\u0646\\u064A\\u0646. \\u0633\\u062D\\u0628\\u0647, \\u062E\\u0644\\u0635\\u0647, \\u0648\\u0639\\u064A\\u062F!"
t["Panic is setting in. I need a clean exit."] = "\\u0627\\u0644\\u0647\\u0644\\u0639 \\u0639\\u0645 \\u064A\\u0628\\u0644\\u0634. \\u0628\\u062F\\u064A \\u0637\\u0644\\u0639\\u0629 \\u0646\\u0636\\u064A\\u0641\\u0629."
t["Part of me thinks they'll walk back in. Part of me is scared they will."] = "\\u062C\\u0632\\u0621 \\u0645\\u0646\\u064A \\u0628\\u064A\\u0641\\u0643\\u0631 \\u0625\\u0646\\u0647\\u0645 \\u0631\\u062D \\u064A\\u0631\\u062C\\u0639\\u0648\\u0627 \\u064A\\u0641\\u0648\\u062A\\u0648\\u0627. \\u062C\\u0632\\u0621 \\u0645\\u0646\\u064A \\u062E\\u0627\\u064A\\u0641 \\u064A\\u0631\\u062C\\u0639\\u0648\\u0627."
t["Part of me wants to paint the walls bright yellow. Unwarranted."] = "\\u0641\\u064A \\u062C\\u0632\\u0621 \\u0645\\u0646\\u064A \\u0628\\u062F\\u0648 \\u064A\\u062F\\u0647\\u0646 \\u0627\\u0644\\u062D\\u064A\\u0637\\u0627\\u0646 \\u0623\\u0635\\u0641\\u0631 \\u0641\\u0627\\u0642\\u0639. \\u0628\\u0644\\u0627 \\u0645\\u0628\\u0631\\u0631."
t["Part of me wants to walk the middle of the road like I own it."] = "\\u0641\\u064A \\u062C\\u0632\\u0621 \\u0645\\u0646\\u064A \\u0628\\u062F\\u0648 \\u064A\\u0645\\u0634\\u064A \\u0628\\u0646\\u0635 \\u0627\\u0644\\u0637\\u0631\\u064A\\u0642 \\u0643\\u0623\\u0646\\u0647 \\u0645\\u0644\\u0643\\u064A."
t["Part of me wants to yell hello into the next quiet house."] = "\\u0641\\u064A \\u062C\\u0632\\u0621 \\u0645\\u0646\\u064A \\u0628\\u062F\\u0648 \\u064A\\u0635\\u0631\\u062E \\u0645\\u0631\\u062D\\u0628\\u0627 \\u0628\\u0627\\u0644\\u0628\\u064A\\u062A \\u0627\\u0644\\u0647\\u0627\\u062F\\u064A \\u0627\\u0644\\u062C\\u0627\\u064A."
t["Pastor said the end was coming. Nobody asked for details."] = "\\u0627\\u0644\\u0642\\u0633\\u064A\\u0633 \\u0642\\u0627\\u0644 \\u0627\\u0644\\u0646\\u0647\\u0627\\u064A\\u0629 \\u062C\\u0627\\u064A\\u0629. \\u0645\\u0627 \\u062D\\u062F\\u0627 \\u0633\\u0623\\u0644 \\u0639\\u0646 \\u0627\\u0644\\u062A\\u0641\\u0627\\u0635\\u064A\\u0644."
t["Peace and quiet. Christ, I hate peace and quiet now."] = "\\u0631\\u0627\\u062D\\u0629 \\u0648\\u0647\\u062F\\u0648\\u0621. \\u064A\\u0644\\u0639\\u0646\\u060C \\u0635\\u0631\\u062A \\u0627\\u0643\\u0631\\u0647 \\u0627\\u0644\\u0631\\u0627\\u062D\\u0629 \\u0648\\u0627\\u0644\\u0647\\u062F\\u0648\\u0621."
t["Peace and quiet. Lord, I hate peace and quiet now."] = "\\u0631\\u0627\\u062D\\u0629 \\u0648\\u0647\\u062F\\u0648\\u0621. \\u064A\\u0627 \\u0631\\u0628\\u060C \\u0635\\u0631\\u062A \\u0627\\u0643\\u0631\\u0647 \\u0627\\u0644\\u0631\\u0627\\u062D\\u0629 \\u0648\\u0627\\u0644\\u0647\\u062F\\u0648\\u0621."
t["Personal defense guidance: stay calm, check your target, conserve ammunition."] = "\\u0625\\u0631\\u0634\\u0627\\u062F\\u0627\\u062A \\u0627\\u0644\\u062F\\u0641\\u0627\\u0639: \\u0627\\u0647\\u062F\\u0627\\u060C \\u062A\\u0623\\u0643\\u062F \\u0645\\u0646 \\u0647\\u062F\\u0641\\u0643\\u060C \\u0648\\u0648\\u0641\\u0631 \\u0627\\u0644\\u0631\\u0635\\u0627\\u0635."
t["Pews are still warm. That's not a good sign."] = "\\u0627\\u0644\\u0645\\u0642\\u0627\\u0639\\u062F \\u0644\\u0633\\u0627 \\u062F\\u0627\\u0641\\u064A\\u0629. \\u0645\\u0648 \\u0639\\u0644\\u0627\\u0645\\u0629 \\u0645\\u0646\\u064A\\u062D\\u0629."
t["Pharmacist's still in the back, I bet. Don't check."] = "\\u0627\\u0644\\u0635\\u064A\\u062F\\u0644\\u064A \\u0644\\u0633\\u0627 \\u062C\\u0648\\u0627\\u060C \\u0628\\u062D\\u0637 \\u0625\\u064A\\u062F\\u064A \\u0639\\u0627\\u0644\\u0646\\u0627\\u0631. \\u0644\\u0627 \\u062A\\u062A\\u0641\\u0642\\u062F."
t["Physically I am okay. I am still trying to settle my nerves."] = "\\u062C\\u0633\\u0645\\u064A \\u0645\\u0646\\u064A\\u062D. \\u0644\\u0633\\u0627 \\u0639\\u0645 \\u062D\\u0627\\u0648\\u0644 \\u0647\\u062F\\u0651\\u064A \\u0623\\u0639\\u0635\\u0627\\u0628\\u064A."
t["Pick a direction. I'll make it work."] = "\\u0627\\u062E\\u062A\\u0627\\u0631 \\u062C\\u0647\\u0629. \\u0648\\u0623\\u0646\\u0627 \\u0628\\u0645\\u0634\\u064A\\u0647\\u0627."
t["Picture the census taker this year. Brave soul."] = "\\u062A\\u062E\\u064A\\u0644 \\u0645\\u0648\\u0638\\u0641 \\u0627\\u0644\\u0625\\u062D\\u0635\\u0627\\u0621 \\u0647\\u0627\\u0644\\u0633\\u0646\\u0629. \\u0642\\u0644\\u0628 \\u0623\\u0633\\u062F."
t["Pinned! Clear the closest two!"] = "\\u0627\\u0646\\u062D\\u0635\\u0631\\u062A! \\u0646\\u0636\\u0641 \\u0623\\u0642\\u0631\\u0628 \\u062A\\u0646\\u064A\\u0646!"
t["Pinned. Clear the ones on top of me!"] = "\\u0627\\u0646\\u062D\\u0635\\u0631\\u062A. \\u0646\\u0636\\u0641 \\u0627\\u0644\\u0644\\u064A \\u0641\\u0648\\u0642\\u064A!"
t["Plan for both endings. Hope for the good one."] = "\\u062E\\u0637\\u0637\\u0648\\u0627 \\u0644\\u0644\\u0646\\u0647\\u0627\\u064A\\u062A\\u064A\\u0646. \\u0648\\u0623\\u0645\\u0644\\u0648\\u0627 \\u0628\\u0627\\u0644\\u0645\\u0646\\u064A\\u062D\\u0629."
t["Planks per wall per argument. Still not enough damn planks."] = "\\u0623\\u0644\\u0648\\u0627\\u062D \\u0644\\u0643\\u0644 \\u062D\\u064A\\u0637 \\u0644\\u0643\\u0644 \\u062E\\u0646\\u0627\\u0642\\u0629. \\u0644\\u0633\\u0627 \\u0645\\u0627 \\u0641\\u064A \\u0643\\u0641\\u0627\\u064A\\u0629 \\u064A\\u0644\\u0639\\u0646."
t["Planks per wall per argument. Still not enough planks."] = "\\u0623\\u0644\\u0648\\u0627\\u062D \\u0644\\u0643\\u0644 \\u062D\\u064A\\u0637 \\u0644\\u0643\\u0644 \\u062E\\u0646\\u0627\\u0642\\u0629. \\u0644\\u0633\\u0627 \\u0645\\u0627 \\u0641\\u064A \\u0643\\u0641\\u0627\\u064A\\u0629."
t["Planting this patch."] = "\\u0639\\u0645 \\u0627\\u0632\\u0631\\u0639 \\u0647\\u0627\\u0644\\u0634\\u0642\\u0641\\u0629."
t["Planting. Nothing heroic, which is a relief."] = "\\u0639\\u0645 \\u0627\\u0632\\u0631\\u0639. \\u0645\\u0627 \\u0641\\u064A \\u0628\\u0637\\u0648\\u0644\\u0627\\u062A\\u060C \\u0648\\u0627\\u0644\\u062D\\u0645\\u062F \\u0644\\u0644\\u0647."
t["Please don't ask me again. Let's talk about the other options."] = "\\u0627\\u0644\\u0644\\u0647 \\u064A\\u062E\\u0644\\u064A\\u0643 \\u0644\\u0627 \\u062A\\u0639\\u064A\\u062F \\u062A\\u0633\\u0623\\u0644\\u0646\\u064A. \\u062E\\u0644\\u064A\\u0646\\u0627 \\u0646\\u062D\\u0643\\u064A \\u0628\\u0627\\u0644\\u062E\\u064A\\u0627\\u0631\\u0627\\u062A \\u0627\\u0644\\u062A\\u0627\\u0646\\u064A\\u0629."
t["Please don't get yourself killed reaching me!"] = "\\u0627\\u0644\\u0644\\u0647 \\u064A\\u062E\\u0644\\u064A\\u0643 \\u0644\\u0627 \\u062A\\u0645\\u0648\\u062A \\u0648\\u0625\\u0646\\u062A \\u062C\\u0627\\u064A \\u0644\\u0639\\u0646\\u062F\\u064A!"
t["Please don't leave the room yet."] = "\\u0627\\u0644\\u0644\\u0647 \\u064A\\u062E\\u0644\\u064A\\u0643 \\u0644\\u0627 \\u062A\\u0637\\u0644\\u0639 \\u0645\\u0646 \\u0627\\u0644\\u063A\\u0631\\u0641\\u0629 \\u0647\\u0644\\u0623."
t["Please don't let them eat me alive."] = "\\u0627\\u0644\\u0644\\u0647 \\u064A\\u062E\\u0644\\u064A\\u0643 \\u0644\\u0627 \\u062A\\u062E\\u0644\\u064A\\u0647\\u0646 \\u064A\\u0627\\u0643\\u0644\\u0648\\u0646\\u064A \\u0639\\u0627\\u064A\\u0634\\u0629."
t["Please don't shout. It's a bite. I'm sorry."] = "\\u0627\\u0644\\u0644\\u0647 \\u064A\\u062E\\u0644\\u064A\\u0643 \\u0644\\u0627 \\u062A\\u0635\\u0631\\u062E. \\u0647\\u064A \\u0639\\u0636\\u0629. \\u0623\\u0646\\u0627 \\u0622\\u0633\\u0641\\u0629."
t["Please don't worry about me. Just let me be quiet."] = "\\u0644\\u0627 \\u062A\\u0647\\u062A\\u0645 \\u0644\\u0623\\u0645\\u0631\\u064A\\u060C \\u0627\\u0644\\u0644\\u0647 \\u064A\\u062E\\u0644\\u064A\\u0643. \\u0628\\u0633 \\u062E\\u0644\\u064A\\u0646\\u064A \\u0633\\u0627\\u0643\\u062A\\u0629."
t["Please don't. I'm barely holding it together."] = "\\u062F\\u062E\\u064A\\u0644\\u0643 \\u0644\\u0623. \\u064A\\u0627 \\u062F\\u0648\\u0628 \\u0645\\u0627\\u0633\\u0643\\u0629 \\u062D\\u0627\\u0644\\u064A."
t["Please eat. Sleep. Keep being a person."] = "\\u0627\\u0644\\u0644\\u0647 \\u064A\\u062E\\u0644\\u064A\\u0643 \\u0643\\u0648\\u0644. \\u0646\\u0627\\u0645. \\u0636\\u0644 \\u0625\\u0646\\u0633\\u0627\\u0646."
t["Please find a proper tool. I don't want anyone ruining their hands."] = "\\u0627\\u0644\\u0644\\u0647 \\u064A\\u062E\\u0644\\u064A\\u0643 \\u0644\\u0627\\u0642\\u064A \\u0639\\u062F\\u0629 \\u0639\\u062F\\u0644\\u0629. \\u0645\\u0627 \\u0628\\u062F\\u064A \\u062D\\u062F\\u0627 \\u064A\\u062E\\u0631\\u0628 \\u0625\\u064A\\u062F\\u064A\\u0647."
t["Please find us somewhere safe enough to stop."] = "\\u0644\\u0627\\u0642\\u064A\\u0644\\u0646\\u0627 \\u0627\\u0644\\u0644\\u0647 \\u064A\\u062E\\u0644\\u064A\\u0643 \\u0645\\u062D\\u0644 \\u0622\\u0645\\u0646 \\u0646\\u0648\\u0642\\u0641 \\u0641\\u064A\\u0647."
t["Please find water. I can't focus."] = "\\u0644\\u0627\\u0642\\u064A \\u0645\\u064A \\u0627\\u0644\\u0644\\u0647 \\u064A\\u062E\\u0644\\u064A\\u0643. \\u0645\\u0627 \\u0639\\u0645 \\u0628\\u0642\\u062F\\u0631 \\u0631\\u0643\\u0651\\u0632."
t["Please help me eat before I become another person to carry."] = "\\u0633\\u0627\\u0639\\u062F\\u0646\\u064A \\u0622\\u0643\\u0644 \\u0642\\u0628\\u0644 \\u0645\\u0627 \\u0635\\u064A\\u0631 \\u062D\\u062F\\u0627 \\u062A\\u0627\\u0646\\u064A \\u0628\\u062F\\u0643\\u0646 \\u062A\\u0634\\u064A\\u0644\\u0648\\u0647."
t["Please help me find water. I really need it."] = "\\u0633\\u0627\\u0639\\u062F\\u0646\\u064A \\u0644\\u0627\\u0642\\u064A \\u0645\\u064A \\u0627\\u0644\\u0644\\u0647 \\u064A\\u062E\\u0644\\u064A\\u0643. \\u0645\\u062D\\u062A\\u0627\\u062C\\u062A\\u0647\\u0627 \\u0639\\u0646 \\u062C\\u062F."
t["Please keep the strange ones to yourself."] = "\\u062F\\u062E\\u064A\\u0644\\u0643\\u060C \\u0627\\u0644\\u0623\\u0641\\u0643\\u0627\\u0631 \\u0627\\u0644\\u063A\\u0631\\u064A\\u0628\\u0629 \\u062E\\u0644\\u064A\\u0647\\u0627 \\u0628\\u0631\\u0627\\u0633\\u0643."
t["Please let me check you. It will help me breathe."] = "\\u062E\\u0644\\u064A\\u0646\\u064A \\u0634\\u0648\\u0641\\u0643\\u060C \\u0627\\u0644\\u0644\\u0647 \\u064A\\u062E\\u0644\\u064A\\u0643. \\u0647\\u064A\\u0643 \\u0628\\u0642\\u062F\\u0631 \\u0627\\u062A\\u0646\\u0641\\u0633."
t["Please remember I would never choose to hurt you."] = "\\u0627\\u0644\\u0644\\u0647 \\u064A\\u062E\\u0644\\u064A\\u0643 \\u062A\\u0630\\u0643\\u0631 \\u0625\\u0646\\u064A \\u0645\\u0627 \\u0628\\u062E\\u062A\\u0627\\u0631 \\u0623\\u0630\\u064A\\u0643 \\u0623\\u0628\\u062F\\u0627."
t["Please stay back. Someone inside isn't well."] = "\\u0627\\u0628\\u0639\\u062F \\u0644\\u0648 \\u0633\\u0645\\u062D\\u062A. \\u0641\\u064A \\u062D\\u062F\\u0627 \\u062C\\u0648\\u0627 \\u0645\\u0648 \\u0645\\u0646\\u064A\\u062D."
t["Please stop asking. I need the room to be empty."] = "\\u062E\\u0644\\u0635 \\u0628\\u0642\\u0649 \\u0627\\u0633\\u0623\\u0644. \\u0628\\u062F\\u064A \\u0627\\u0644\\u063A\\u0631\\u0641\\u0629 \\u0641\\u0627\\u0636\\u064A\\u0629."
t["Please take over for me. I cannot stay awake."] = "\\u0627\\u0633\\u062A\\u0644\\u0645 \\u0639\\u0646\\u064A \\u0627\\u0644\\u0644\\u0647 \\u064A\\u062E\\u0644\\u064A\\u0643. \\u0645\\u0627 \\u0641\\u064A\\u0646\\u064A \\u0636\\u0644 \\u0641\\u0627\\u064A\\u0642\\u0629."
t["Please tell me we have enough for a meal."] = "\\u0642\\u0644\\u064A \\u0627\\u0644\\u0644\\u0647 \\u064A\\u062E\\u0644\\u064A\\u0643 \\u0625\\u0646\\u0647 \\u0639\\u0646\\u0627 \\u0623\\u0643\\u0644 \\u0628\\u064A\\u0643\\u0641\\u064A."
t["Please! Don't let me die here!"] = "\\u0627\\u0644\\u0644\\u0647 \\u064A\\u062E\\u0644\\u064A\\u0643! \\u0644\\u0627 \\u062A\\u062E\\u0644\\u064A\\u0646\\u064A \\u0645\\u0648\\u062A \\u0647\\u0648\\u0646!"
t["Please, %1, don't let me wake up hungry."] = "\\u0627\\u0644\\u0644\\u0647 \\u064A\\u062E\\u0644\\u064A\\u0643 \\u064A\\u0627 %1, \\u0644\\u0627 \\u062A\\u062E\\u0644\\u064A\\u0646\\u064A \\u0641\\u064A\\u0642 \\u062C\\u0648\\u0639\\u0627\\u0646\\u0629."
t["Please, I still have things to say!"] = "\\u0627\\u0644\\u0644\\u0647 \\u064A\\u062E\\u0644\\u064A\\u0643, \\u0644\\u0633\\u0627 \\u0639\\u0646\\u062F\\u064A \\u062D\\u0643\\u064A!"
t["Please. I need something to eat."] = "\\u0627\\u0644\\u0644\\u0647 \\u064A\\u062E\\u0644\\u064A\\u0643. \\u0628\\u062F\\u064A \\u0634\\u064A \\u0622\\u0643\\u0644\\u0647."
t["Please. Tell me the part that stayed with you."] = "\\u062A\\u0641\\u0636\\u0644. \\u0627\\u062D\\u0643\\u064A\\u0644\\u064A \\u0634\\u0648 \\u0627\\u0644\\u062C\\u0632\\u0621 \\u0627\\u0644\\u0644\\u064A \\u0636\\u0644 \\u0628\\u0631\\u0627\\u0633\\u0643."
t["Plenty of guns. Never enough sense. Not before, sure as hell not after."] = "\\u0633\\u0644\\u0627\\u062D \\u0643\\u062A\\u064A\\u0631 \\u0648\\u0639\\u0642\\u0644 \\u0645\\u0627 \\u0641\\u064A. \\u0644\\u0627 \\u0642\\u0628\\u0644\\u060C \\u0648\\u0644\\u0627 \\u0628\\u0639\\u062F\\u060C \\u064A\\u0644\\u0639\\u0646 \\u0647\\u064A\\u0643 \\u062D\\u0627\\u0644."
t["Plenty of guns. There was never enough sense, before or after."] = "\\u0633\\u0644\\u0627\\u062D \\u0643\\u062A\\u064A\\u0631. \\u0648\\u0627\\u0644\\u0639\\u0642\\u0644 \\u0639\\u0645\\u0631\\u0647 \\u0645\\u0627 \\u0643\\u0641\\u0651\\u0649\\u060C \\u0644\\u0627 \\u0642\\u0628\\u0644 \\u0648\\u0644\\u0627 \\u0628\\u0639\\u062F."
t["Plot selected. I'll prepare it properly."] = "\\u0627\\u062E\\u062A\\u0631\\u062A \\u0627\\u0644\\u0623\\u0631\\u0636. \\u0631\\u062D \\u062C\\u0647\\u0632\\u0647\\u0627 \\u0639\\u062F\\u0644."
t["Point me at something hard. I need the fight out of me."] = "\\u0648\\u062F\\u0651\\u064A\\u0646\\u064A \\u0639\\u0644\\u0649 \\u0634\\u064A \\u0635\\u0639\\u0628. \\u0644\\u0627\\u0632\\u0645 \\u064A\\u0637\\u0644\\u0639 \\u0627\\u0644\\u0642\\u062A\\u0627\\u0644 \\u0645\\u0646\\u064A."
t["Point the way. I'll handle whatever's on it."] = "\\u0623\\u0634\\u0651\\u0631 \\u0639\\u0627\\u0644\\u0637\\u0631\\u064A\\u0642. \\u0648\\u0623\\u0646\\u0627 \\u0628\\u062A\\u0635\\u0631\\u0641 \\u0645\\u0639 \\u0627\\u0644\\u0644\\u064A \\u0639\\u0644\\u064A\\u0647."
t["Pool table's intact. Nobody left to argue over the rules."] = "\\u0637\\u0627\\u0648\\u0644\\u0629 \\u0627\\u0644\\u0628\\u0644\\u064A\\u0627\\u0631\\u062F\\u0648 \\u0633\\u0644\\u064A\\u0645\\u0629. \\u0648\\u0645\\u0627 \\u0636\\u0644 \\u062D\\u062F\\u0627 \\u064A\\u062A\\u062E\\u0627\\u0646\\u0642 \\u0639\\u0627\\u0644\\u0642\\u0648\\u0627\\u0646\\u064A\\u0646."
t["Pop quiz. Capital of Kentucky? Wrong. It's Frankfort. It's always Frankfort."] = "\\u0627\\u0645\\u062A\\u062D\\u0627\\u0646 \\u0645\\u0641\\u0627\\u062C\\u0626. \\u0639\\u0627\\u0635\\u0645\\u0629 \\u0643\\u0646\\u062A\\u0627\\u0643\\u064A\\u061F \\u063A\\u0644\\u0637. \\u0641\\u0631\\u0627\\u0646\\u0643\\u0641\\u0648\\u0631\\u062A. \\u062F\\u0627\\u064A\\u0645\\u064B\\u0627 \\u0641\\u0631\\u0627\\u0646\\u0643\\u0641\\u0648\\u0631\\u062A."
t["Popcorn machine's still full. Stale, but full."] = "\\u0645\\u0643\\u0646\\u0629 \\u0627\\u0644\\u0628\\u0648\\u0634\\u0627\\u0631 \\u0644\\u0633\\u0627 \\u0645\\u0644\\u064A\\u0627\\u0646\\u0629. \\u0628\\u0627\\u064A\\u062A\\u060C \\u0628\\u0633 \\u0645\\u0644\\u064A\\u0627\\u0646\\u0629."
t["Position lost! Withdraw!"] = "\\u0627\\u0644\\u0645\\u0643\\u0627\\u0646 \\u0631\\u0627\\u062D! \\u0627\\u0646\\u0633\\u062D\\u0628!"
t["Position lost. Immediate evacuation."] = "\\u0627\\u0644\\u0645\\u0643\\u0627\\u0646 \\u0631\\u0627\\u062D. \\u0625\\u062E\\u0644\\u0627\\u0621 \\u0641\\u0648\\u0631\\u064A."
t["Poster calls this a community refuge. The community seems delayed."] = "\\u0627\\u0644\\u0628\\u0648\\u0633\\u062A\\u0631 \\u0628\\u064A\\u0633\\u0645\\u064A\\u0647 \\u0645\\u0644\\u062C\\u0623 \\u0623\\u0647\\u0644\\u064A. \\u0627\\u0644\\u0623\\u0647\\u0627\\u0644\\u064A \\u0634\\u0643\\u0644\\u0647\\u0645 \\u062A\\u0623\\u062E\\u0631\\u0648\\u0627."
t["Poster promises a meal and a smile. We may have to supply both."] = "\\u0627\\u0644\\u0628\\u0648\\u0633\\u062A\\u0631 \\u0628\\u064A\\u0648\\u0639\\u062F \\u0628\\u0648\\u062C\\u0628\\u0629 \\u0648\\u0636\\u062D\\u0643\\u0629. \\u064A\\u0645\\u0643\\u0646 \\u0646\\u062C\\u064A\\u0628\\u0647\\u0645 \\u0646\\u062D\\u0646\\u0627."
t["Poster says a healthy smile builds confidence. The model has all his teeth."] = "\\u0627\\u0644\\u0628\\u0648\\u0633\\u062A\\u0631 \\u0628\\u064A\\u0642\\u0648\\u0644 \\u0627\\u0644\\u0636\\u062D\\u0643\\u0629 \\u0627\\u0644\\u062D\\u0644\\u0648\\u0629 \\u0628\\u062A\\u0628\\u0646\\u064A \\u0627\\u0644\\u062B\\u0642\\u0629. \\u0627\\u0644\\u0644\\u064A \\u0628\\u0627\\u0644\\u0635\\u0648\\u0631\\u0629 \\u0623\\u0633\\u0646\\u0627\\u0646\\u0647 \\u0643\\u0644\\u0647\\u0627 \\u0639\\u0646\\u062F\\u0647."
t["Poster says cleanliness is everyone's duty. Quarters are everyone's problem."] = "\\u0627\\u0644\\u0628\\u0648\\u0633\\u062A\\u0631 \\u0628\\u064A\\u0642\\u0648\\u0644 \\u0627\\u0644\\u0646\\u0636\\u0627\\u0641\\u0629 \\u0648\\u0627\\u062C\\u0628 \\u0627\\u0644\\u062C\\u0645\\u064A\\u0639. \\u0627\\u0644\\u0641\\u0631\\u0627\\u0637\\u0629 \\u0645\\u0634\\u0643\\u0644\\u0629 \\u0627\\u0644\\u062C\\u0645\\u064A\\u0639."
t["Poster says music keeps communities strong. Power supply not pictured."] = "\\u0627\\u0644\\u0628\\u0648\\u0633\\u062A\\u0631 \\u0628\\u064A\\u0642\\u0648\\u0644 \\u0627\\u0644\\u0645\\u0648\\u0633\\u064A\\u0642\\u0649 \\u0628\\u062A\\u0642\\u0648\\u0651\\u064A \\u0627\\u0644\\u0623\\u0647\\u0627\\u0644\\u064A. \\u0627\\u0644\\u0643\\u0647\\u0631\\u0628\\u0627 \\u0645\\u0648 \\u0628\\u0627\\u0644\\u0635\\u0648\\u0631\\u0629."
t["Poster says preparedness starts in the classroom. Class dismissed."] = "\\u0627\\u0644\\u0628\\u0648\\u0633\\u062A\\u0631 \\u0628\\u064A\\u0642\\u0648\\u0644 \\u0627\\u0644\\u0627\\u0633\\u062A\\u0639\\u062F\\u0627\\u062F \\u0628\\u064A\\u0628\\u0644\\u0634 \\u0645\\u0646 \\u0627\\u0644\\u0635\\u0641. \\u0627\\u0646\\u062A\\u0647\\u0649 \\u0627\\u0644\\u062F\\u0631\\u0633."
t["Poster says preventive maintenance keeps Kentucky moving. We'll do our part."] = "\\u0627\\u0644\\u0628\\u0648\\u0633\\u062A\\u0631 \\u0628\\u064A\\u0642\\u0648\\u0644 \\u0627\\u0644\\u0635\\u064A\\u0627\\u0646\\u0629 \\u0627\\u0644\\u0648\\u0642\\u0627\\u0626\\u064A\\u0629 \\u0628\\u062A\\u062E\\u0644\\u064A \\u0643\\u0646\\u062A\\u0627\\u0643\\u064A \\u062A\\u0645\\u0634\\u064A. \\u0631\\u062D \\u0646\\u0642\\u0648\\u0645 \\u0628\\u062F\\u0648\\u0631\\u0646\\u0627."
t["Poster says quality brings people together. It neglected to specify alive people."] = "\\u0627\\u0644\\u0628\\u0648\\u0633\\u062A\\u0631 \\u0628\\u064A\\u0642\\u0648\\u0644 \\u0627\\u0644\\u062C\\u0648\\u062F\\u0629 \\u0628\\u062A\\u062C\\u0645\\u0639 \\u0627\\u0644\\u0646\\u0627\\u0633. \\u0646\\u0633\\u064A \\u064A\\u062D\\u062F\\u062F \\u0627\\u0644\\u0623\\u062D\\u064A\\u0627\\u0621."
t["Poster says support local workers. The county really did think of everything."] = "\\u0627\\u0644\\u0628\\u0648\\u0633\\u062A\\u0631 \\u0628\\u064A\\u0642\\u0648\\u0644 \\u0627\\u062F\\u0639\\u0645 \\u0627\\u0644\\u0639\\u0645\\u0627\\u0644 \\u0627\\u0644\\u0645\\u062D\\u0644\\u064A\\u064A\\u0646. \\u0627\\u0644\\u0645\\u0642\\u0627\\u0637\\u0639\\u0629 \\u0641\\u0643\\u0631\\u062A \\u0628\\u0643\\u0644 \\u0634\\u064A \\u0639\\u0646 \\u062C\\u062F."
t["Poster says the situation is under control. It's dated July."] = "\\u0627\\u0644\\u0628\\u0648\\u0633\\u062A\\u0631 \\u0628\\u064A\\u0642\\u0648\\u0644 \\u0627\\u0644\\u0648\\u0636\\u0639 \\u062A\\u062D\\u062A \\u0627\\u0644\\u0633\\u064A\\u0637\\u0631\\u0629. \\u062A\\u0627\\u0631\\u064A\\u062E\\u0647 \\u062A\\u0645\\u0648\\u0632."
t["Pour me one before Bandit gets all the biscuits."] = "\\u0635\\u0628\\u0644\\u064A \\u0642\\u0628\\u0644 \\u0645\\u0627 \\u064A\\u0627\\u0643\\u0644 \\u0628\\u0627\\u0646\\u062F\\u064A\\u062A \\u0643\\u0644 \\u0627\\u0644\\u0628\\u0633\\u0643\\u0648\\u064A\\u062A."
t["Pour me one. I'll drink while it's quiet."] = "\\u0635\\u0628\\u0651\\u0644\\u064A \\u0643\\u0627\\u0633\\u0629. \\u0628\\u0634\\u0631\\u0628\\u0647\\u0627 \\u0637\\u0627\\u0644\\u0645\\u0627 \\u0627\\u0644\\u062F\\u0646\\u064A\\u0627 \\u0647\\u0627\\u062F\\u064A\\u0629."
t["Prepared citizens stay fit. The county would be proud of all this running."] = "\\u0627\\u0644\\u0645\\u0648\\u0627\\u0637\\u0646 \\u0627\\u0644\\u0645\\u0633\\u062A\\u0639\\u062F \\u0644\\u064A\\u0627\\u0642\\u062A\\u0647 \\u0639\\u0627\\u0644\\u064A\\u0629. \\u0627\\u0644\\u0645\\u0642\\u0627\\u0637\\u0639\\u0629 \\u0631\\u062D \\u062A\\u0641\\u062A\\u062E\\u0631 \\u0628\\u0643\\u0644 \\u0647\\u0627\\u0644\\u0631\\u0643\\u0636."
t["Preparing helps. Living in fear doesn't. I'm working on the difference."] = "\\u0627\\u0644\\u0627\\u0633\\u062A\\u0639\\u062F\\u0627\\u062F \\u0628\\u064A\\u0641\\u064A\\u062F. \\u0627\\u0644\\u0639\\u064A\\u0634\\u0629 \\u0628\\u0627\\u0644\\u062E\\u0648\\u0641 \\u0644\\u0623. \\u0639\\u0645 \\u0627\\u0634\\u062A\\u063A\\u0644 \\u0639\\u0627\\u0644\\u0641\\u0631\\u0642."
t["Prescriptions for the whole county. Most of them won't need it now."] = "\\u0648\\u0635\\u0641\\u0627\\u062A \\u0644\\u0644\\u0645\\u0642\\u0627\\u0637\\u0639\\u0629 \\u0643\\u0644\\u0647\\u0627. \\u0623\\u063A\\u0644\\u0628\\u0647\\u0645 \\u0645\\u0627 \\u0639\\u0627\\u062F \\u0628\\u062F\\u0647\\u0645."
t["Press here. Hard. I need both hands."] = "\\u0627\\u0636\\u063A\\u0637 \\u0647\\u0648\\u0646. \\u0628\\u0642\\u0648\\u0629. \\u0628\\u062F\\u064A \\u0625\\u064A\\u062F\\u064A\\u064A \\u0627\\u0644\\u062A\\u0646\\u062A\\u064A\\u0646."
t["Price check on everything. Everything's free now. Everything's gone."] = "\\u0641\\u062D\\u0635 \\u0633\\u0639\\u0631 \\u0639\\u0644\\u0649 \\u0643\\u0644 \\u0634\\u064A. \\u0643\\u0644 \\u0634\\u064A \\u0628\\u0628\\u0644\\u0627\\u0634 \\u0647\\u0644\\u0623. \\u0643\\u0644 \\u0634\\u064A \\u062E\\u0627\\u0644\\u0635."
t["Prices went up. Then everything went down."] = "\\u0627\\u0644\\u0623\\u0633\\u0639\\u0627\\u0631 \\u0637\\u0644\\u0639\\u062A \\u0644\\u0641\\u0648\\u0642. \\u0648\\u0628\\u0639\\u062F\\u064A\\u0646 \\u0643\\u0644 \\u0634\\u064A \\u0646\\u0632\\u0644 \\u0644\\u062A\\u062D\\u062A."
t["Prices went up. Then everything went to hell."] = "\\u0627\\u0644\\u0623\\u0633\\u0639\\u0627\\u0631 \\u063A\\u0644\\u064A\\u062A. \\u0648\\u0628\\u0639\\u062F\\u0647\\u0627 \\u0643\\u0644 \\u0634\\u064A \\u0631\\u0627\\u062D \\u0628\\u0633\\u062A\\u064A\\u0646 \\u062F\\u0627\\u0647\\u064A\\u0629."
t["Principles matter most when following them costs something."] = "\\u0627\\u0644\\u0645\\u0628\\u0627\\u062F\\u0626 \\u0628\\u062A\\u0641\\u0631\\u0642 \\u0623\\u0643\\u062A\\u0631 \\u0644\\u0645\\u0627 \\u064A\\u0643\\u0648\\u0646 \\u062A\\u0645\\u0646\\u0647\\u0627 \\u063A\\u0627\\u0644\\u064A."
t["Priorities are clear. I am working them in order."] = "\\u0627\\u0644\\u0623\\u0648\\u0644\\u0648\\u064A\\u0627\\u062A \\u0648\\u0627\\u0636\\u062D\\u0629. \\u0639\\u0645 \\u0627\\u0634\\u062A\\u063A\\u0644\\u0647\\u0627 \\u0628\\u0627\\u0644\\u062A\\u0631\\u062A\\u064A\\u0628."
t["Promise me this doesn't make you stop trusting people."] = "\\u0648\\u0639\\u062F\\u0646\\u064A \\u0647\\u0627\\u0644\\u0634\\u064A \\u0645\\u0627 \\u064A\\u062E\\u0644\\u064A\\u0643 \\u062A\\u0628\\u0637\\u0644 \\u062A\\u062B\\u0642 \\u0628\\u0627\\u0644\\u0646\\u0627\\u0633."
t["Promise me you'll check the next corner twice."] = "\\u0648\\u0639\\u062F\\u0646\\u064A \\u062A\\u0634\\u0648\\u0641 \\u0627\\u0644\\u0632\\u0627\\u0648\\u064A\\u0629 \\u0627\\u0644\\u062C\\u0627\\u064A\\u0629 \\u0645\\u0631\\u062A\\u064A\\u0646."
t["Promise me you'll eat something tomorrow."] = "\\u0648\\u0639\\u062F\\u0646\\u064A \\u062A\\u0627\\u0643\\u0644 \\u0634\\u064A \\u0628\\u0643\\u0631\\u0627."
t["Property listing: secure, quiet, some neighbours dead. Make an offer."] = "\\u0644\\u0644\\u0628\\u064A\\u0639: \\u0622\\u0645\\u0646\\u060C \\u0647\\u0627\\u062F\\u064A\\u060C \\u0628\\u0639\\u0636 \\u0627\\u0644\\u062C\\u064A\\u0631\\u0627\\u0646 \\u0645\\u064A\\u062A\\u064A\\u0646. \\u0642\\u062F\\u0651\\u0645 \\u0639\\u0631\\u0636\\u0643."
t["Public Health says every case will be recorded. They ran out of tags first."] = "\\u0627\\u0644\\u0635\\u062D\\u0629 \\u0627\\u0644\\u0639\\u0627\\u0645\\u0629 \\u0628\\u062A\\u0642\\u0648\\u0644 \\u0643\\u0644 \\u062D\\u0627\\u0644\\u0629 \\u0631\\u062D \\u062A\\u062A\\u0633\\u062C\\u0644. \\u062E\\u0644\\u0635\\u0648\\u0627 \\u0627\\u0644\\u0628\\u0637\\u0627\\u0642\\u0627\\u062A \\u0623\\u0648\\u0644."
t["Public information center. Further updates are in the fiction aisle."] = "\\u0645\\u0631\\u0643\\u0632 \\u0627\\u0644\\u0645\\u0639\\u0644\\u0648\\u0645\\u0627\\u062A \\u0627\\u0644\\u0639\\u0627\\u0645\\u0629. \\u0627\\u0644\\u062A\\u062D\\u062F\\u064A\\u062B\\u0627\\u062A \\u0627\\u0644\\u062C\\u0627\\u064A\\u0629 \\u0628\\u0642\\u0633\\u0645 \\u0627\\u0644\\u062E\\u064A\\u0627\\u0644."
t["Pull back before they surround us!"] = "\\u0627\\u0631\\u062C\\u0639 \\u0642\\u0628\\u0644 \\u0645\\u0627 \\u064A\\u0637\\u0648\\u0642\\u0648\\u0646\\u0627!"
t["Pull back, now!"] = "\\u0627\\u0646\\u0633\\u062D\\u0628, \\u0647\\u0644\\u0623!"
t["Pull it into the open first!"] = "\\u0627\\u0633\\u062D\\u0628\\u0647 \\u0639\\u0627\\u0644\\u0645\\u0643\\u0634\\u0648\\u0641 \\u0623\\u0648\\u0644!"
t["Pull them apart. Fall back!"] = "\\u0641\\u0631\\u0642\\u0646. \\u0627\\u0631\\u062C\\u0639!"
t["Pull them off and I'll stand back up!"] = "\\u0634\\u064A\\u0644\\u0646 \\u0639\\u0646\\u064A \\u0648\\u0628\\u0648\\u0642\\u0641 \\u0645\\u0646 \\u062C\\u062F\\u064A\\u062F!"
t["Pulse is slowing. My chest has cancelled the funeral."] = "\\u0627\\u0644\\u0646\\u0628\\u0636 \\u0639\\u0645 \\u064A\\u0647\\u062F\\u0649. \\u0635\\u062F\\u0631\\u064A \\u0644\\u063A\\u0649 \\u0627\\u0644\\u0639\\u0632\\u0627."
t["Pumps are dry, candy's stale, still better than most places."] = "\\u0627\\u0644\\u0645\\u0636\\u062E\\u0627\\u062A \\u0646\\u0627\\u0634\\u0641\\u0629 \\u0648\\u0627\\u0644\\u0633\\u0643\\u0627\\u0643\\u0631 \\u0628\\u0627\\u064A\\u062A\\u0629\\u060C \\u0648\\u0644\\u0633\\u0627 \\u0623\\u062D\\u0633\\u0646 \\u0645\\u0646 \\u0623\\u063A\\u0644\\u0628 \\u0627\\u0644\\u0645\\u062D\\u0644\\u0627\\u062A."
t["Put it away, %1. The trees have suffered enough."] = "\\u062F\\u062E\\u0644\\u0647 \\u064A\\u0627 %1. \\u0627\\u0644\\u0634\\u062C\\u0631 \\u062A\\u0639\\u0630\\u0628 \\u0643\\u0641\\u0627\\u064A\\u0629."
t["Put it away. That isn't my choice."] = "\\u0634\\u064A\\u0644\\u0647\\u0627. \\u0647\\u0627\\u062F \\u0645\\u0648 \\u062E\\u064A\\u0627\\u0631\\u064A."
t["Put it down. This is your last chance."] = "\\u0646\\u0632\\u0651\\u0644\\u0647. \\u0647\\u064A \\u0622\\u062E\\u0631 \\u0641\\u0631\\u0635\\u0629 \\u0625\\u0644\\u0643."
t["Put it on the list. I'll help when these legs remember their job."] = "\\u062D\\u0637\\u0647\\u0627 \\u0628\\u0627\\u0644\\u0642\\u0627\\u0626\\u0645\\u0629. \\u0628\\u0633\\u0627\\u0639\\u062F\\u0643 \\u0644\\u0645\\u0627 \\u062A\\u062A\\u0630\\u0643\\u0631 \\u0631\\u062C\\u0644\\u064A\\u064A \\u0634\\u063A\\u0644\\u0647\\u0627."
t["Put me down as someone who finished the damn book."] = "\\u0633\\u062C\\u0644\\u0646\\u064A \\u0645\\u0646 \\u0627\\u0644\\u0644\\u064A \\u062E\\u0644\\u0635\\u0648\\u0627 \\u0647\\u0627\\u0644\\u0643\\u062A\\u0627\\u0628 \\u0627\\u0644\\u0645\\u0644\\u0639\\u0648\\u0646."
t["Put me down as someone who finished the darn book."] = "\\u0633\\u062C\\u0644\\u0646\\u064A \\u0645\\u0646 \\u0627\\u0644\\u0644\\u064A \\u062E\\u0644\\u0635\\u0648\\u0627 \\u0647\\u0627\\u0644\\u0643\\u062A\\u0627\\u0628 \\u0627\\u0644\\u0645\\u0639\\u062A\\u0651\\u0631."
t["Put me on clear ground and I'll take them."] = "\\u062D\\u0637\\u064A\\u0646\\u064A \\u0639\\u0623\\u0631\\u0636 \\u0646\\u0636\\u064A\\u0641\\u0629 \\u0648\\u0628\\u062E\\u0644\\u0651\\u0635 \\u0639\\u0644\\u064A\\u0647\\u0646."
t["Put some space between us. Now."] = "\\u062D\\u0637 \\u0645\\u0633\\u0627\\u0641\\u0629 \\u0628\\u064A\\u0646\\u0627\\u062A\\u0646\\u0627. \\u0647\\u0644\\u0623."
t["Put that goddamn thought back where you found it."] = "\\u0631\\u062C\\u0651\\u0639 \\u0647\\u0627\\u0644\\u0641\\u0643\\u0631\\u0629 \\u0627\\u0644\\u0645\\u0644\\u0639\\u0648\\u0646\\u0629 \\u0645\\u0637\\u0631\\u062D \\u0645\\u0627 \\u0644\\u0642\\u064A\\u062A\\u0647\\u0627."
t["Put that thought back where you found it."] = "\\u0631\\u062C\\u0651\\u0639 \\u0647\\u0627\\u0644\\u0641\\u0643\\u0631\\u0629 \\u0645\\u0637\\u0631\\u062D \\u0645\\u0627 \\u0644\\u0642\\u064A\\u062A\\u0647\\u0627."
t["Put the kettle back by Milli. She'll want it tomorrow."] = "\\u0631\\u062C\\u0651\\u0639 \\u0627\\u0644\\u0625\\u0628\\u0631\\u064A\\u0642 \\u062C\\u0646\\u0628 \\u0645\\u064A\\u0644\\u064A. \\u0631\\u062D \\u062A\\u062D\\u062A\\u0627\\u062C\\u0647 \\u0628\\u0643\\u0631\\u0627."
t["Put the weapon down!"] = "\\u062D\\u0637 \\u0627\\u0644\\u0633\\u0644\\u0627\\u062D \\u0639\\u0627\\u0644\\u0623\\u0631\\u0636!"
t["Put the weapons down. This is still our friend."] = "\\u0646\\u0632\\u0644\\u0648\\u0627 \\u0627\\u0644\\u0633\\u0644\\u0627\\u062D. \\u0647\\u0627\\u062F \\u0644\\u0633\\u0627 \\u0631\\u0641\\u064A\\u0642\\u0646\\u0627."
t["Put what you owe us on the ground. We will collect it."] = "\\u062D\\u0637 \\u0627\\u0644\\u0644\\u064A \\u0639\\u0644\\u064A\\u0643 \\u0639\\u0627\\u0644\\u0623\\u0631\\u0636. \\u0646\\u062D\\u0646\\u0627 \\u0645\\u0646\\u0644\\u0645\\u0647."
t["Quick and quiet. Don't draw a crowd!"] = "\\u0628\\u0633\\u0631\\u0639\\u0629 \\u0648\\u0628\\u0647\\u062F\\u0648\\u0621. \\u0645\\u0627 \\u0628\\u062F\\u0646\\u0627 \\u0646\\u062C\\u0645\\u0639 \\u0627\\u0644\\u0643\\u0644!"
t["Quick check. I want to know this thing works when it matters."] = "\\u0641\\u062D\\u0635 \\u0633\\u0631\\u064A\\u0639. \\u0628\\u062F\\u064A \\u0627\\u0639\\u0631\\u0641 \\u0647\\u0627\\u0644\\u0634\\u064A \\u0628\\u064A\\u0634\\u062A\\u063A\\u0644 \\u0648\\u0642\\u062A \\u0627\\u0644\\u062D\\u0632\\u0629."
t["Quick health check, then we return to work."] = "\\u0641\\u062D\\u0635 \\u0633\\u0631\\u064A\\u0639\\u060C \\u0648\\u0628\\u0639\\u062F\\u064A\\u0646 \\u0645\\u0646\\u0631\\u062C\\u0639 \\u0639\\u0627\\u0644\\u0634\\u063A\\u0644."
t["Quiet enough to hear myself think. Almost."] = "\\u0647\\u062F\\u0648\\u0621 \\u0644\\u062F\\u0631\\u062C\\u0629 \\u0628\\u0633\\u0645\\u0639 \\u0623\\u0641\\u0643\\u0627\\u0631\\u064A. \\u062A\\u0642\\u0631\\u064A\\u0628\\u064B\\u0627."
t["Quiet feet, keep moving, do not turn to fight!"] = "\\u0631\\u062C\\u0644\\u064A\\u0646 \\u062E\\u0641\\u0627\\u0641, \\u0643\\u0645\\u0644, \\u0648\\u0644\\u0627 \\u062A\\u062F\\u0648\\u0631 \\u062A\\u0642\\u0627\\u062A\\u0644!"
t["Quiet in here. Library quiet, not dead quiet. I think."] = "\\u0647\\u0627\\u062F\\u064A \\u0647\\u0648\\u0646. \\u0647\\u062F\\u0648\\u0621 \\u0645\\u0643\\u062A\\u0628\\u0629\\u060C \\u0645\\u0648 \\u0647\\u062F\\u0648\\u0621 \\u0645\\u0648\\u062A. \\u0628\\u0638\\u0646."
t["Quiet in the back row. Always was."] = "\\u0647\\u062F\\u0648\\u0621 \\u0628\\u0627\\u0644\\u0635\\u0641 \\u0627\\u0644\\u0623\\u062E\\u064A\\u0631. \\u0637\\u0648\\u0644 \\u0639\\u0645\\u0631\\u0647."
t["Quiet is the only thing keeping us alive. Mind it."] = "\\u0627\\u0644\\u0633\\u0643\\u0648\\u062A \\u0647\\u0648 \\u0627\\u0644\\u0634\\u064A \\u0627\\u0644\\u0648\\u062D\\u064A\\u062F \\u0627\\u0644\\u0644\\u064A \\u0645\\u062E\\u0644\\u064A\\u0646\\u0627 \\u0639\\u0627\\u064A\\u0634\\u064A\\u0646. \\u0627\\u0646\\u062A\\u0628\\u0647 \\u0639\\u0644\\u064A\\u0647."
t["Quiet minute. How are you doing, %1?"] = "\\u062F\\u0642\\u064A\\u0642\\u0629 \\u0647\\u062F\\u0648\\u0621. \\u0643\\u064A\\u0641\\u0643 \\u064A\\u0627 %1\\u061F"
t["Quiet nights here sound exactly like waiting."] = "\\u0627\\u0644\\u0644\\u064A\\u0627\\u0644\\u064A \\u0627\\u0644\\u0647\\u0627\\u062F\\u064A\\u0629 \\u0647\\u0648\\u0646 \\u0635\\u0648\\u062A\\u0647\\u0627 \\u0645\\u062A\\u0644 \\u0627\\u0644\\u0627\\u0646\\u062A\\u0638\\u0627\\u0631 \\u0628\\u0627\\u0644\\u0632\\u0628\\u0637."
t["Quiet out here. Too quiet for this sort of thing."] = "\\u0647\\u0627\\u062F\\u064A \\u0647\\u0648\\u0646. \\u0643\\u062A\\u064A\\u0631 \\u0647\\u0627\\u062F\\u064A \\u0644\\u0647\\u064A\\u0643 \\u0634\\u063A\\u0644\\u0629."
t["Quiet places make me listen harder."] = "\\u0627\\u0644\\u0623\\u0645\\u0627\\u0643\\u0646 \\u0627\\u0644\\u0647\\u0627\\u062F\\u064A\\u0629 \\u0628\\u062A\\u062E\\u0644\\u064A\\u0646\\u064A \\u0627\\u0633\\u0645\\u0639 \\u0623\\u0643\\u062A\\u0631."
t["Quiet so far. I'd still watch the windows."] = "\\u0647\\u0627\\u062F\\u064A \\u0644\\u0647\\u0644\\u0623. \\u0628\\u0633 \\u0636\\u0644 \\u0631\\u0627\\u0642\\u0628 \\u0627\\u0644\\u0634\\u0628\\u0627\\u0628\\u064A\\u0643."
t["Quiet. I can hear one of them."] = "\\u0647\\u0633. \\u0639\\u0645 \\u0627\\u0633\\u0645\\u0639 \\u0648\\u0627\\u062D\\u062F \\u0645\\u0646\\u0646."
t["Radio check. Can everyone hear me?"] = "\\u0641\\u062D\\u0635 \\u0631\\u0627\\u062F\\u064A\\u0648. \\u0627\\u0644\\u0643\\u0644 \\u0633\\u0627\\u0645\\u0639\\u0646\\u064A\\u061F"
t["Radio check. Kentucky, be kind to us for once."] = "\\u0641\\u062D\\u0635 \\u0631\\u0627\\u062F\\u064A\\u0648. \\u064A\\u0627 \\u0643\\u0646\\u062A\\u0627\\u0643\\u064A\\u060C \\u0627\\u0631\\u062D\\u0645\\u064A\\u0646\\u0627 \\u0644\\u0645\\u0631\\u0629 \\u0648\\u062D\\u062F\\u0629."
t["Rain cuts visibility. Slow down around blind corners."] = "\\u0627\\u0644\\u0645\\u0637\\u0631 \\u0628\\u064A\\u0642\\u0635\\u0631 \\u0627\\u0644\\u0631\\u0624\\u064A\\u0629. \\u0639\\u0645\\u0647\\u0644\\u0643 \\u0639\\u0627\\u0644\\u0632\\u0648\\u0627\\u064A\\u0627 \\u0627\\u0644\\u0639\\u0645\\u064A\\u0627\\u0621."
t["Rain makes them look almost sorry."] = "\\u0627\\u0644\\u0645\\u0637\\u0631 \\u0628\\u064A\\u062E\\u0644\\u064A\\u0647\\u0645 \\u064A\\u0628\\u064A\\u0646\\u0648\\u0627 \\u0634\\u0628\\u0647 \\u0632\\u0639\\u0644\\u0627\\u0646\\u064A\\u0646."
t["Rain on the roof sounds like gravel from this chair."] = "\\u0627\\u0644\\u0645\\u0637\\u0631 \\u0639\\u0627\\u0644\\u0633\\u0642\\u0641 \\u0628\\u064A\\u0635\\u064A\\u0631 \\u0645\\u062A\\u0644 \\u0627\\u0644\\u0628\\u062D\\u0635 \\u0645\\u0646 \\u0647\\u0627\\u0644\\u0643\\u0631\\u0633\\u064A."
t["Rain on tin, mud on boots. Could be worse. Usually is."] = "\\u0645\\u0637\\u0631 \\u0639\\u0627\\u0644\\u062A\\u0646\\u0643 \\u0648\\u0648\\u062D\\u0644 \\u0639\\u0627\\u0644\\u0628\\u0648\\u0637. \\u0645\\u0645\\u0643\\u0646 \\u0623\\u0633\\u0648\\u0623. \\u0648\\u0639\\u0627\\u062F\\u0629\\u064B \\u0628\\u064A\\u0643\\u0648\\u0646."
t["Rain sounds like applause for something I missed."] = "\\u0635\\u0648\\u062A \\u0627\\u0644\\u0645\\u0637\\u0631 \\u0645\\u062A\\u0644 \\u062A\\u0635\\u0641\\u064A\\u0642 \\u0644\\u0634\\u064A \\u0641\\u0627\\u062A\\u0646\\u064A."
t["Rain will mask sound in both directions."] = "\\u0627\\u0644\\u0645\\u0637\\u0631 \\u0628\\u064A\\u063A\\u0637\\u064A \\u0627\\u0644\\u0635\\u0648\\u062A \\u0628\\u0627\\u0644\\u0627\\u062A\\u062C\\u0627\\u0647\\u064A\\u0646."
t["Rain won't stop us. Just keep your footing."] = "\\u0627\\u0644\\u0645\\u0637\\u0631 \\u0645\\u0627 \\u0628\\u064A\\u0648\\u0642\\u0641\\u0646\\u0627. \\u0628\\u0633 \\u062F\\u064A\\u0631 \\u0628\\u0627\\u0644\\u0643 \\u0639\\u062E\\u0637\\u0648\\u062A\\u0643."
t["Rain's coming down. Tell me if you get cold."] = "\\u0627\\u0644\\u0645\\u0637\\u0631 \\u0646\\u0627\\u0632\\u0644. \\u0642\\u0644\\u064A \\u0625\\u0630\\u0627 \\u0628\\u0631\\u062F\\u062A."
t["Rain. Good cover for us, and for anything nearby."] = "\\u0645\\u0637\\u0631. \\u063A\\u0637\\u0627 \\u0645\\u0646\\u064A\\u062D \\u0625\\u0644\\u0646\\u0627\\u060C \\u0648\\u0644\\u0623\\u064A \\u0634\\u064A \\u0642\\u0631\\u064A\\u0628."
t["Ran the numbers on this trip. The numbers say we're fucked. Walk faster."] = "\\u062D\\u0633\\u0628\\u062A\\u0647\\u0627 \\u0644\\u0647\\u0627\\u0644\\u0645\\u0634\\u0648\\u0627\\u0631. \\u0627\\u0644\\u0623\\u0631\\u0642\\u0627\\u0645 \\u0628\\u062A\\u0642\\u0648\\u0644 \\u0631\\u0627\\u062D\\u062A \\u0639\\u0644\\u064A\\u0646\\u0627 \\u064A\\u0644\\u0639\\u0646. \\u0627\\u0645\\u0634\\u064A \\u0623\\u0633\\u0631\\u0639."
t["Ran the numbers on this trip. The numbers say we're screwed. Walk faster."] = "\\u062D\\u0633\\u0628\\u062A\\u0647\\u0627 \\u0644\\u0647\\u0627\\u0644\\u0645\\u0634\\u0648\\u0627\\u0631. \\u0627\\u0644\\u0623\\u0631\\u0642\\u0627\\u0645 \\u0628\\u062A\\u0642\\u0648\\u0644 \\u0631\\u0627\\u062D\\u062A \\u0639\\u0644\\u064A\\u0646\\u0627. \\u0627\\u0645\\u0634\\u064A \\u0623\\u0633\\u0631\\u0639."
t["Ration boxes. They taste like duty."] = "\\u0639\\u0644\\u0628 \\u0625\\u0639\\u0627\\u0634\\u0629. \\u0637\\u0639\\u0645\\u062A\\u0647\\u0627 \\u0645\\u062A\\u0644 \\u0627\\u0644\\u0648\\u0627\\u062C\\u0628."
t["Read me the part you keep thinking about, %1."] = "\\u0627\\u0642\\u0631\\u0627\\u0644\\u064A \\u0627\\u0644\\u0642\\u0633\\u0645 \\u0627\\u0644\\u0644\\u064A \\u0645\\u0627 \\u0639\\u0645 \\u064A\\u0637\\u0644\\u0639 \\u0645\\u0646 \\u0631\\u0627\\u0633\\u0643 \\u064A\\u0627 %1."
t["Read the labels. Guesswork's already killed enough people."] = "\\u0627\\u0642\\u0631\\u0627 \\u0627\\u0644\\u0645\\u0644\\u0635\\u0642\\u0627\\u062A. \\u0627\\u0644\\u062A\\u062E\\u0645\\u064A\\u0646 \\u0642\\u062A\\u0644 \\u0646\\u0627\\u0633 \\u0643\\u0641\\u0627\\u064A\\u0629."
t["Readiness is high. This is the time for the hard job."] = "\\u0627\\u0644\\u062C\\u0627\\u0647\\u0632\\u064A\\u0629 \\u0639\\u0627\\u0644\\u064A\\u0629. \\u0647\\u0627\\u062F \\u0648\\u0642\\u062A \\u0627\\u0644\\u0634\\u063A\\u0644\\u0629 \\u0627\\u0644\\u0635\\u0639\\u0628\\u0629."
t["Readiness is too low. Resetting before contact."] = "\\u0627\\u0644\\u062C\\u0627\\u0647\\u0632\\u064A\\u0629 \\u0642\\u0644\\u064A\\u0644\\u0629. \\u0639\\u0645 \\u0631\\u062A\\u0628 \\u062D\\u0627\\u0644\\u064A \\u0642\\u0628\\u0644 \\u0627\\u0644\\u0627\\u0644\\u062A\\u062D\\u0627\\u0645."
t["Ready. Let's not waste the daylight."] = "\\u062C\\u0627\\u0647\\u0632\\u0629. \\u062E\\u0644\\u064A\\u0646\\u0627 \\u0645\\u0627 \\u0646\\u0636\\u064A\\u0651\\u0639 \\u0636\\u0648 \\u0627\\u0644\\u0646\\u0647\\u0627\\u0631."
t["Real cops. I used to wave at these guys from the mall."] = "\\u0634\\u0631\\u0637\\u0629 \\u062D\\u0642\\u064A\\u0642\\u064A\\u064A\\u0646. \\u0643\\u0646\\u062A \\u0633\\u0644\\u0651\\u0645 \\u0639\\u0644\\u064A\\u0647\\u0645 \\u0645\\u0646 \\u0627\\u0644\\u0645\\u0648\\u0644."
t["Received. I'll keep it in working order. Thanks."] = "\\u0648\\u0635\\u0644. \\u0631\\u062D \\u062E\\u0644\\u064A\\u0647 \\u0634\\u063A\\u0627\\u0644. \\u0634\\u0643\\u0631\\u0627."
t["Record the time, lock the door, and leave, %1."] = "\\u0633\\u062C\\u0644 \\u0627\\u0644\\u0648\\u0642\\u062A, \\u0627\\u0642\\u0641\\u0644 \\u0627\\u0644\\u0628\\u0627\\u0628, \\u0648\\u0631\\u0648\\u062D \\u064A\\u0627 %1."
t["Records don't need power. Just a turntable and faith."] = "\\u0627\\u0644\\u0623\\u0633\\u0637\\u0648\\u0627\\u0646\\u0627\\u062A \\u0645\\u0627 \\u0628\\u062F\\u0647\\u0627 \\u0643\\u0647\\u0631\\u0628\\u0627. \\u0628\\u0633 \\u0628\\u064A\\u0643 \\u0623\\u0628 \\u0648\\u0625\\u064A\\u0645\\u0627\\u0646."
t["Remember me standing, not like this."] = "\\u062A\\u0630\\u0643\\u0631\\u0646\\u064A \\u0648\\u0627\\u0642\\u0641\\u0629, \\u0645\\u0648 \\u0647\\u064A\\u0643."
t["Remember my voice, not the sound I'll make later."] = "\\u062A\\u0630\\u0643\\u0631 \\u0635\\u0648\\u062A\\u064A, \\u0645\\u0648 \\u0627\\u0644\\u0635\\u0648\\u062A \\u0627\\u0644\\u0644\\u064A \\u0631\\u062D \\u0637\\u0644\\u0639\\u0647 \\u0628\\u0639\\u062F\\u064A\\u0646."
t["Remember that. We may need it tomorrow."] = "\\u062A\\u0630\\u0643\\u0631 \\u0647\\u0627\\u062F. \\u064A\\u0645\\u0643\\u0646 \\u0646\\u062D\\u062A\\u0627\\u062C\\u0647 \\u0628\\u0643\\u0631\\u0627."
t["Remember when somebody else worried about what was for dinner?"] = "\\u0628\\u062A\\u0630\\u0643\\u0631 \\u0644\\u0645\\u0627 \\u0643\\u0627\\u0646 \\u063A\\u064A\\u0631\\u0646\\u0627 \\u064A\\u0647\\u062A\\u0645 \\u0634\\u0648 \\u0627\\u0644\\u0639\\u0634\\u0627\\u061F"
t["Remember, folks: idle hands get eaten."] = "\\u062A\\u0630\\u0643\\u0631\\u0648\\u0627 \\u064A\\u0627 \\u062C\\u0645\\u0627\\u0639\\u0629: \\u0627\\u0644\\u0625\\u064A\\u062F \\u0627\\u0644\\u0641\\u0627\\u0636\\u064A\\u0629 \\u0628\\u062A\\u0646\\u0648\\u0643\\u0644."
t["Remind me never to stand next to you on a roof."] = "\\u0630\\u0643\\u0651\\u0631\\u0646\\u064A \\u0645\\u0627 \\u0623\\u0648\\u0642\\u0641 \\u062D\\u062F\\u0651\\u0643 \\u0639\\u0644\\u0649 \\u0633\\u0637\\u062D \\u0623\\u0628\\u062F\\u0627\\u064B."
t["Rental shoes. The true horror."] = "\\u0623\\u062D\\u0630\\u064A\\u0629 \\u0645\\u0633\\u062A\\u0623\\u062C\\u0631\\u0629. \\u0627\\u0644\\u0631\\u0639\\u0628 \\u0627\\u0644\\u062D\\u0642\\u064A\\u0642\\u064A."
t["Report cards on the floor. Everybody gets an incomplete."] = "\\u062C\\u0644\\u0627\\u0621\\u0627\\u062A \\u0639\\u0627\\u0644\\u0623\\u0631\\u0636. \\u0627\\u0644\\u0643\\u0644 \\u0646\\u0627\\u0642\\u0635."
t["Reset against the lone target."] = "\\u0631\\u062A\\u0628 \\u0645\\u0633\\u0627\\u0641\\u062A\\u0643 \\u0645\\u0639 \\u0627\\u0644\\u0648\\u0627\\u062D\\u062F."
t["Rest has to become a priority."] = "\\u0627\\u0644\\u0631\\u0627\\u062D\\u0629 \\u0644\\u0627\\u0632\\u0645 \\u062A\\u0635\\u064A\\u0631 \\u0623\\u0648\\u0644\\u0648\\u064A\\u0629."
t["Rest need is rising, but I remain functional."] = "\\u0627\\u0644\\u062D\\u0627\\u062C\\u0629 \\u0644\\u0644\\u0631\\u0627\\u062D\\u0629 \\u0639\\u0645 \\u062A\\u0632\\u064A\\u062F\\u060C \\u0628\\u0633 \\u0644\\u0633\\u0627 \\u0641\\u064A\\u0646\\u064A \\u0627\\u0634\\u062A\\u063A\\u0644."
t["Restroom key's gone. Last decent decision anybody made here."] = "\\u0645\\u0641\\u062A\\u0627\\u062D \\u0627\\u0644\\u062D\\u0645\\u0627\\u0645 \\u0636\\u0627\\u064A\\u0639. \\u0622\\u062E\\u0631 \\u0642\\u0631\\u0627\\u0631 \\u0639\\u0627\\u0642\\u0644 \\u0635\\u0627\\u0631 \\u0647\\u0648\\u0646."
t["Return it to literature storage. Somebody else will need it."] = "\\u0631\\u062C\\u0639\\u0647 \\u0644\\u0645\\u062E\\u0632\\u0646 \\u0627\\u0644\\u0643\\u062A\\u0628. \\u062D\\u062F\\u0627 \\u062A\\u0627\\u0646\\u064A \\u0631\\u062D \\u064A\\u062D\\u062A\\u0627\\u062C\\u0647."
t["Returned with everyone we left with. That's the number that matters."] = "\\u0631\\u062C\\u0639\\u0646\\u0627 \\u0628\\u0643\\u0644 \\u0627\\u0644\\u0644\\u064A \\u0637\\u0644\\u0639\\u0646\\u0627 \\u0641\\u064A\\u0647\\u0645. \\u0647\\u0627\\u062F \\u0627\\u0644\\u0631\\u0642\\u0645 \\u0627\\u0644\\u0644\\u064A \\u0628\\u064A\\u0647\\u0645."
t["Right behind you."] = "\\u0648\\u0631\\u0627\\u0643 \\u062A\\u0645\\u0627\\u0645."
t["Right now I am focused on getting through the day."] = "\\u0647\\u0644\\u0623 \\u0643\\u0644 \\u0647\\u0645\\u064A \\u0627\\u062E\\u0644\\u0635 \\u0647\\u0627\\u0644\\u064A\\u0648\\u0645 \\u0639\\u062E\\u064A\\u0631."
t["Right now we are %1. Supply levels remain %2."] = "\\u0647\\u0644\\u0623 \\u0646\\u062D\\u0646\\u0627 %1. \\u0648\\u0627\\u0644\\u0645\\u0648\\u0646\\u0629 \\u0644\\u0633\\u0627 %2."
t["Right now, I'm %1."] = "\\u0628\\u0647\\u0627\\u0644\\u0644\\u062D\\u0638\\u0629 \\u0634\\u063A\\u0644\\u062A\\u064A %1."
t["Right. Where were we?"] = "\\u0637\\u064A\\u0628. \\u0648\\u064A\\u0646 \\u0643\\u0646\\u0627\\u061F"
t["Ring of teeth. I don't do rings. Pulling out."] = "\\u062D\\u0644\\u0642\\u0629 \\u0633\\u0646\\u0627\\u0646. \\u0648\\u0623\\u0646\\u0627 \\u0645\\u0627 \\u0628\\u062D\\u0628 \\u0627\\u0644\\u062D\\u0644\\u0642\\u0627\\u062A. \\u0637\\u0627\\u0644\\u0639\\u0629."
t["Rinse the cups. Milli counts them every night."] = "\\u0627\\u0634\\u0637\\u0641 \\u0627\\u0644\\u0643\\u0627\\u0633\\u0627\\u062A. \\u0645\\u064A\\u0644\\u064A \\u0628\\u062A\\u0639\\u062F\\u0651\\u0647\\u0645 \\u0643\\u0644 \\u0644\\u064A\\u0644\\u0629."
t["Road maps by the counter. Somebody might still need directions."] = "\\u062E\\u0631\\u0627\\u064A\\u0637 \\u0637\\u0631\\u0642 \\u062C\\u0646\\u0628 \\u0627\\u0644\\u0643\\u0627\\u0648\\u0646\\u062A\\u0631. \\u064A\\u0645\\u0643\\u0646 \\u062D\\u062F\\u0627 \\u0644\\u0633\\u0627 \\u0645\\u062D\\u062A\\u0627\\u062C \\u064A\\u0639\\u0631\\u0641 \\u0637\\u0631\\u064A\\u0642\\u0647."
t["Roadside ditches never used to worry me. Funny how that changed."] = "\\u062C\\u0648\\u0631 \\u0627\\u0644\\u0637\\u0631\\u064A\\u0642 \\u0645\\u0627 \\u0643\\u0627\\u0646\\u062A \\u062A\\u062E\\u0648\\u0641\\u0646\\u064A. \\u063A\\u0631\\u064A\\u0628 \\u0643\\u064A\\u0641 \\u062A\\u063A\\u064A\\u0631\\u062A."
t["Roast potatoes and anything fresh would do."] = "\\u0628\\u0637\\u0627\\u0637\\u0627 \\u0645\\u0634\\u0648\\u064A\\u0629 \\u0648\\u0623\\u064A \\u0634\\u064A \\u0637\\u0627\\u0632\\u0629 \\u0628\\u064A\\u0643\\u0641\\u0648\\u0627."
t["Room's trying to scare me. It can get in line."] = "\\u0627\\u0644\\u063A\\u0631\\u0641\\u0629 \\u0639\\u0645 \\u062A\\u062D\\u0627\\u0648\\u0644 \\u062A\\u062E\\u0648\\u0641\\u0646\\u064A. \\u062E\\u0644\\u064A\\u0647\\u0627 \\u062A\\u0648\\u0642\\u0641 \\u0628\\u0627\\u0644\\u062F\\u0648\\u0631."
t["Rot took the crop. It does not get the soil too."] = "\\u0627\\u0644\\u0639\\u0641\\u0646 \\u0623\\u062E\\u062F \\u0627\\u0644\\u0632\\u0631\\u0639. \\u0628\\u0633 \\u0627\\u0644\\u062A\\u0631\\u0627\\u0628 \\u0645\\u0627 \\u0631\\u062D \\u064A\\u0627\\u062E\\u062F\\u0647."
t["Rules are rules. Bitten means isolated. No exceptions."] = "\\u0627\\u0644\\u0642\\u0627\\u0646\\u0648\\u0646 \\u0642\\u0627\\u0646\\u0648\\u0646. \\u0627\\u0644\\u0645\\u0639\\u0636\\u0648\\u0636 \\u0628\\u064A\\u0646\\u0639\\u0632\\u0644. \\u0628\\u0644\\u0627 \\u0627\\u0633\\u062A\\u062B\\u0646\\u0627\\u0621\\u0627\\u062A."
t["Running inventory in my head again. It never adds up to enough."] = "\\u0639\\u0645 \\u0627\\u0639\\u0645\\u0644 \\u062C\\u0631\\u062F \\u0628\\u0631\\u0627\\u0633\\u064A \\u0645\\u0631\\u0629 \\u062A\\u0627\\u0646\\u064A\\u0629. \\u0639\\u0645\\u0631\\u0647 \\u0645\\u0627 \\u0628\\u064A\\u0637\\u0644\\u0639 \\u0643\\u0641\\u0627\\u064A\\u0629."
t["Same damn jingle in my head for three miles. Make it stop."] = "\\u0646\\u0641\\u0633 \\u0627\\u0644\\u062F\\u0639\\u0627\\u064A\\u0629 \\u0627\\u0644\\u0632\\u0641\\u062A \\u0628\\u0631\\u0627\\u0633\\u064A \\u0645\\u0646 \\u062A\\u0644\\u0627\\u062A \\u0623\\u0645\\u064A\\u0627\\u0644. \\u0648\\u0642\\u0641\\u0648\\u0647\\u0627."
t["Same jingle in my head for three miles. Make it stop."] = "\\u0646\\u0641\\u0633 \\u0627\\u0644\\u062F\\u0639\\u0627\\u064A\\u0629 \\u0628\\u0631\\u0627\\u0633\\u064A \\u0645\\u0646 \\u062A\\u0644\\u0627\\u062A \\u0623\\u0645\\u064A\\u0627\\u0644. \\u0648\\u0642\\u0641\\u0648\\u0647\\u0627."
t["Same name. Much worse circumstances."] = "\\u0646\\u0641\\u0633 \\u0627\\u0644\\u0627\\u0633\\u0645. \\u0638\\u0631\\u0648\\u0641 \\u0623\\u0639\\u0637\\u0644 \\u0628\\u0643\\u062A\\u064A\\u0631."
t["Same road, same rules. Eyes open."] = "\\u0646\\u0641\\u0633 \\u0627\\u0644\\u0637\\u0631\\u064A\\u0642\\u060C \\u0646\\u0641\\u0633 \\u0627\\u0644\\u0642\\u0648\\u0627\\u0639\\u062F. \\u0641\\u062A\\u0651\\u062D \\u0639\\u064A\\u0646\\u0643."
t["Same, honestly. Don't tell anyone."] = "\\u0648\\u0623\\u0646\\u0627 \\u0643\\u0645\\u0627\\u0646\\u060C \\u0628\\u0635\\u0631\\u0627\\u062D\\u0629. \\u0644\\u0627 \\u062A\\u0642\\u0648\\u0644 \\u0644\\u062D\\u062F\\u0627."
t["Sanitation protects the community. At last, advice we can actually use."] = "\\u0627\\u0644\\u0646\\u0636\\u0627\\u0641\\u0629 \\u0628\\u062A\\u062D\\u0645\\u064A \\u0627\\u0644\\u0623\\u0647\\u0627\\u0644\\u064A. \\u0623\\u062E\\u064A\\u0631\\u064B\\u0627\\u060C \\u0646\\u0635\\u064A\\u062D\\u0629 \\u0641\\u064A\\u0646\\u0627 \\u0646\\u0633\\u062A\\u0639\\u0645\\u0644\\u0647\\u0627."
t["Save it for me, %1. I'd like to know what moved you."] = "\\u062E\\u0628\\u064A\\u0647 \\u0625\\u0644\\u064A \\u064A\\u0627 %1. \\u0628\\u062F\\u064A \\u0627\\u0639\\u0631\\u0641 \\u0634\\u0648 \\u062D\\u0631\\u0643\\u0643."
t["Save your strength. I am already spent."] = "\\u0648\\u0641\\u0631 \\u062D\\u064A\\u0644\\u0643. \\u0623\\u0646\\u0627 \\u062E\\u0644\\u0635\\u062A."
t["Say a word if you've got one. I ran out in July."] = "\\u0642\\u0648\\u0644 \\u0643\\u0644\\u0645\\u0629 \\u0625\\u0630\\u0627 \\u0639\\u0646\\u062F\\u0643. \\u0623\\u0646\\u0627 \\u062E\\u0644\\u0635\\u0648\\u0627 \\u0643\\u0644\\u0645\\u0627\\u062A\\u064A \\u0628\\u062A\\u0645\\u0648\\u0632."
t["Say if you need a breather. We can take one."] = "\\u0642\\u0648\\u0644 \\u0625\\u0630\\u0627 \\u0628\\u062F\\u0643 \\u062A\\u0631\\u062A\\u0627\\u062D. \\u0641\\u064A\\u0646\\u0627 \\u0646\\u0648\\u0642\\u0641 \\u0634\\u0648\\u064A."
t["Say it plainly. We cannot fix what nobody will name."] = "\\u0642\\u0648\\u0644\\u0647\\u0627 \\u0639\\u0627\\u0644\\u0645\\u0643\\u0634\\u0648\\u0641. \\u0645\\u0627 \\u0645\\u0646\\u0635\\u0644\\u0651\\u062D \\u0634\\u064A \\u0645\\u0627 \\u062D\\u062F\\u0627 \\u0628\\u064A\\u0633\\u0645\\u064A\\u0647."
t["Say my name once when you get somewhere safe."] = "\\u0642\\u0648\\u0644 \\u0627\\u0633\\u0645\\u064A \\u0645\\u0631\\u0629 \\u0644\\u0645\\u0627 \\u062A\\u0648\\u0635\\u0644 \\u0644\\u0645\\u0643\\u0627\\u0646 \\u0623\\u0645\\u0627\\u0646."
t["Say something if this gets through the static."] = "\\u0627\\u062D\\u0643\\u0648\\u0627 \\u0634\\u064A \\u0625\\u0630\\u0627 \\u0647\\u0627\\u062F \\u0645\\u0631\\u0642 \\u0645\\u0646 \\u0627\\u0644\\u062A\\u0634\\u0648\\u064A\\u0634."
t["Say something true. I need one last true thing."] = "\\u0642\\u0648\\u0644 \\u0634\\u064A \\u0635\\u0627\\u062F\\u0642. \\u0628\\u062F\\u064A \\u0622\\u062E\\u0631 \\u0634\\u064A \\u0635\\u0627\\u062F\\u0642."
t["Say the word and I am ready for another supply run."] = "\\u0628\\u0633 \\u0642\\u0648\\u0644 \\u0627\\u0644\\u0643\\u0644\\u0645\\u0629\\u060C \\u0648\\u0623\\u0646\\u0627 \\u062C\\u0627\\u0647\\u0632\\u0629 \\u0644\\u0645\\u0634\\u0648\\u0627\\u0631 \\u062A\\u0627\\u0646\\u064A."
t["Say the word. I'll punch the clock, or something moving."] = "\\u0642\\u0648\\u0644 \\u0643\\u0644\\u0645\\u0629. \\u064A\\u0627 \\u0628\\u062F\\u0627\\u0648\\u0645 \\u064A\\u0627 \\u0628\\u0636\\u0631\\u0628 \\u0634\\u064A \\u0628\\u064A\\u062A\\u062D\\u0631\\u0643."
t["Say what you need to say, but do not pretend you had every answer."] = "\\u0642\\u0648\\u0644 \\u0627\\u0644\\u0644\\u064A \\u0628\\u062F\\u0643 \\u064A\\u0627\\u0647\\u060C \\u0628\\u0633 \\u0645\\u0627 \\u062A\\u0639\\u0645\\u0644 \\u062D\\u0627\\u0644\\u0643 \\u0643\\u0646\\u062A \\u0639\\u0627\\u0631\\u0641 \\u0643\\u0644\\u0634\\u064A."
t["Says here informed citizens make calm citizens. Let's take two."] = "\\u0645\\u0643\\u062A\\u0648\\u0628 \\u0627\\u0644\\u0645\\u0648\\u0627\\u0637\\u0646 \\u0627\\u0644\\u0645\\u0637\\u0651\\u0644\\u0639 \\u0645\\u0648\\u0627\\u0637\\u0646 \\u0647\\u0627\\u062F\\u064A. \\u062E\\u0644\\u064A\\u0646\\u0627 \\u0646\\u0627\\u062E\\u062F \\u0646\\u0633\\u062E\\u062A\\u064A\\u0646."
t["Says here knowledge is protection. Good. We can carry several books."] = "\\u0645\\u0643\\u062A\\u0648\\u0628 \\u0625\\u0646 \\u0627\\u0644\\u0645\\u0639\\u0631\\u0641\\u0629 \\u062D\\u0645\\u0627\\u064A\\u0629. \\u0645\\u0646\\u064A\\u062D. \\u0641\\u064A\\u0646\\u0627 \\u0646\\u062D\\u0645\\u0644 \\u0643\\u0627\\u0645 \\u0643\\u062A\\u0627\\u0628."
t["Scoreboard still shows the last game. Somebody was winning."] = "\\u0644\\u0648\\u062D \\u0627\\u0644\\u0646\\u062A\\u0627\\u064A\\u062C \\u0644\\u0633\\u0627 \\u0639\\u0627\\u0644\\u062C\\u0648\\u0644\\u0629 \\u0627\\u0644\\u0623\\u062E\\u064A\\u0631\\u0629. \\u062D\\u062F\\u0627 \\u0643\\u0627\\u0646 \\u0631\\u0627\\u0628\\u062D."
t["Search the containers. Our stock is too low."] = "\\u0641\\u062A\\u0634 \\u0627\\u0644\\u062E\\u0632\\u0627\\u064A\\u0646. \\u0627\\u0644\\u0645\\u062E\\u0632\\u0648\\u0646 \\u0642\\u0644\\u064A\\u0644 \\u0643\\u062A\\u064A\\u0631."
t["Search the shelves, then we head home together."] = "\\u0641\\u062A\\u0634\\u0648\\u0627 \\u0627\\u0644\\u0631\\u0641\\u0648\\u0641\\u060C \\u0648\\u0628\\u0639\\u062F\\u064A\\u0646 \\u0645\\u0646\\u0631\\u062C\\u0639 \\u0633\\u0648\\u0627."
t["Seat's comfortable. That's how they get you."] = "\\u0627\\u0644\\u0643\\u0631\\u0633\\u064A \\u0645\\u0631\\u064A\\u062D. \\u0647\\u064A\\u0643 \\u0628\\u064A\\u0648\\u0642\\u0639\\u0648\\u0643."
t["Seated zombie ahead. Keep your distance."] = "\\u0632\\u0648\\u0645\\u0628\\u064A \\u0642\\u0627\\u0639\\u062F \\u0642\\u062F\\u0627\\u0645\\u0646\\u0627. \\u0636\\u0644 \\u0628\\u0639\\u064A\\u062F."
t["Second Amendment's still standing. The rest of us, less so."] = "\\u0627\\u0644\\u062A\\u0639\\u062F\\u064A\\u0644 \\u0627\\u0644\\u062A\\u0627\\u0646\\u064A \\u0644\\u0633\\u0627 \\u0635\\u0627\\u0645\\u062F. \\u0646\\u062D\\u0646\\u0627 \\u0628\\u0627\\u0642\\u064A \\u0627\\u0644\\u0646\\u0627\\u0633\\u060C \\u0623\\u0642\\u0644 \\u0634\\u0648\\u064A."
t["Secrets get people killed. Come on. Together."] = "\\u0627\\u0644\\u0623\\u0633\\u0631\\u0627\\u0631 \\u0628\\u062A\\u0645\\u0648\\u0651\\u062A \\u0627\\u0644\\u0639\\u0627\\u0644\\u0645. \\u064A\\u0644\\u0627. \\u0633\\u0648\\u0627."
t["Secure both doors before the fever takes me."] = "\\u0623\\u0645\\u0646 \\u0627\\u0644\\u0628\\u0627\\u0628\\u064A\\u0646 \\u0642\\u0628\\u0644 \\u0645\\u0627 \\u062A\\u0627\\u062E\\u062F\\u0646\\u064A \\u0627\\u0644\\u062D\\u0645\\u0649."
t["Secure them. Nobody opens that door without permission."] = "\\u0623\\u0645\\u0646\\u0648\\u0647\\u0646. \\u0648\\u0645\\u0627 \\u062D\\u062F\\u0627 \\u064A\\u0641\\u062A\\u062D \\u0647\\u0627\\u0644\\u0628\\u0627\\u0628 \\u0628\\u0644\\u0627 \\u0625\\u0630\\u0646."
t["Seed by seed. Here we go."] = "\\u0628\\u0632\\u0631\\u0629 \\u0648\\u0631\\u0627 \\u0628\\u0632\\u0631\\u0629. \\u064A\\u0644\\u0627."
t["Seed count checked. Planting now."] = "\\u0639\\u062F\\u0651\\u064A\\u062A \\u0627\\u0644\\u0628\\u0632\\u0627\\u0631. \\u0639\\u0645 \\u0627\\u0632\\u0631\\u0639 \\u0647\\u0644\\u0623."
t["Seeds are going in."] = "\\u0627\\u0644\\u0628\\u0632\\u0627\\u0631 \\u0646\\u0627\\u0632\\u0644."
t["Seeds are in. Now we wait and pretend to be patient."] = "\\u0627\\u0644\\u0628\\u0632\\u0627\\u0631 \\u0646\\u0632\\u0644. \\u0647\\u0644\\u0623 \\u0645\\u0646\\u0633\\u062A\\u0646\\u0649 \\u0648\\u0645\\u0646\\u0639\\u0645\\u0644 \\u062D\\u0627\\u0644\\u0646\\u0627 \\u0635\\u0628\\u0648\\u0631\\u064A\\u0646."
t["Self-help section's picked clean. Of course it is."] = "\\u0642\\u0633\\u0645 \\u062A\\u0637\\u0648\\u064A\\u0631 \\u0627\\u0644\\u0630\\u0627\\u062A \\u0645\\u0646\\u0647\\u0648\\u0628. \\u0637\\u0628\\u064A\\u0639\\u064A."
t["Separate them, keep watch, and make an exit plan."] = "\\u0627\\u0641\\u0635\\u0644\\u0648\\u0647\\u0646\\u060C \\u0631\\u0627\\u0642\\u0628\\u0648\\u0627\\u060C \\u0648\\u062C\\u0647\\u0632\\u0648\\u0627 \\u062E\\u0637\\u0629 \\u0637\\u0644\\u0648\\u0639."
t["Set the payment down and step away."] = "\\u062D\\u0637 \\u0627\\u0644\\u062F\\u0641\\u0639\\u0629 \\u0648\\u0627\\u0628\\u0639\\u062F."
t["Several ahead. Watch each other!"] = "\\u0643\\u0630\\u0627 \\u0648\\u0627\\u062D\\u062F \\u0642\\u062F\\u0627\\u0645. \\u0627\\u0646\\u062A\\u0628\\u0647\\u0648\\u0627 \\u0644\\u0628\\u0639\\u0636!"
t["Several on us. Move to the choke point!"] = "\\u0643\\u0630\\u0627 \\u0648\\u0627\\u062D\\u062F \\u0639\\u0644\\u064A\\u0646\\u0627. \\u0639\\u0627\\u0644\\u0645\\u0645\\u0631 \\u0627\\u0644\\u0636\\u064A\\u0642!"
t["Several zombies. Keep your spacing."] = "\\u0643\\u0630\\u0627 \\u0632\\u0648\\u0645\\u0628\\u064A. \\u062E\\u0644\\u064A \\u0645\\u0633\\u0627\\u0641\\u0629."
t["Shh. Quiet. You want to get us all killed?"] = "\\u0647\\u0633\\u0633. \\u0627\\u0633\\u0643\\u062A. \\u0628\\u062F\\u0643 \\u062A\\u0645\\u0648\\u0651\\u062A\\u0646\\u0627 \\u0643\\u0644\\u0646\\u0627\\u061F"
t["Shit, that looks bad. Hold still."] = "\\u064A\\u0644\\u0639\\u0646\\u060C \\u0634\\u0643\\u0644\\u0647\\u0627 \\u0639\\u0627\\u0637\\u0644. \\u062B\\u0628\\u062A."
t["Shit. My hands won't listen. Stay close while I breathe."] = "\\u064A\\u0644\\u0639\\u0646 \\u0623\\u0628\\u0648\\u0647\\u0627. \\u0625\\u064A\\u062F\\u064A\\u064A \\u0645\\u0627 \\u0639\\u0645 \\u064A\\u0637\\u064A\\u0639\\u0648\\u0646\\u064A. \\u062E\\u0644\\u064A\\u0643 \\u0642\\u0631\\u064A\\u0628 \\u0644\\u0622\\u062E\\u062F \\u0646\\u0641\\u0633\\u064A."
t["Shit. That's another fish with a story about me."] = "\\u062E\\u0631\\u0627. \\u0647\\u064A \\u0633\\u0645\\u0643\\u0629 \\u062A\\u0627\\u0646\\u064A\\u0629 \\u0639\\u0646\\u062F\\u0647\\u0627 \\u0642\\u0635\\u0629 \\u0639\\u0646\\u064A."
t["Shit. Tough room, worse listeners."] = "\\u064A\\u0644\\u0639\\u0646 \\u0623\\u0628\\u0648\\u0647\\u0627. \\u062C\\u0645\\u0647\\u0648\\u0631 \\u0635\\u0639\\u0628\\u060C \\u0648\\u0623\\u062F\\u0627\\u0646\\u0647\\u0646 \\u0623\\u0635\\u0639\\u0628."
t["Shoes, water, ammo, will. In that order. Will is running low as shit."] = "\\u062C\\u0632\\u0645\\u060C \\u0645\\u064A\\u060C \\u0630\\u062E\\u064A\\u0631\\u0629\\u060C \\u0625\\u0631\\u0627\\u062F\\u0629. \\u0628\\u0647\\u0627\\u0644\\u062A\\u0631\\u062A\\u064A\\u0628. \\u0627\\u0644\\u0625\\u0631\\u0627\\u062F\\u0629 \\u0639\\u0645 \\u062A\\u062E\\u0644\\u0635 \\u064A\\u0644\\u0639\\u0646\\u0647\\u0627."
t["Shoes, water, ammo, will. In that order. Will is running low."] = "\\u062C\\u0632\\u0645\\u060C \\u0645\\u064A\\u060C \\u0630\\u062E\\u064A\\u0631\\u0629\\u060C \\u0625\\u0631\\u0627\\u062F\\u0629. \\u0628\\u0647\\u0627\\u0644\\u062A\\u0631\\u062A\\u064A\\u0628. \\u0627\\u0644\\u0625\\u0631\\u0627\\u062F\\u0629 \\u0639\\u0645 \\u062A\\u062E\\u0644\\u0635."
t["Shook them off!"] = "\\u0646\\u0641\\u0636\\u062A\\u0646 \\u0639\\u0646\\u064A!"
t["Shopping carts everywhere. Everybody left in a hurry."] = "\\u0639\\u0631\\u0628\\u064A\\u0627\\u062A \\u062A\\u0633\\u0648\\u0642 \\u0628\\u0643\\u0644 \\u0645\\u062D\\u0644. \\u0627\\u0644\\u0643\\u0644 \\u0637\\u0644\\u0639 \\u0645\\u0633\\u062A\\u0639\\u062C\\u0644."
t["Short on %1. No amount of counting improves it."] = "\\u0646\\u0627\\u0642\\u0635\\u0646\\u0627 %1. \\u0648\\u0627\\u0644\\u0639\\u062F \\u0645\\u0627 \\u0628\\u064A\\u0632\\u064A\\u062F\\u0647."
t["Shout if you need a breather. I won't think less of you."] = "\\u0627\\u0635\\u0631\\u062E \\u0625\\u0630\\u0627 \\u0628\\u062F\\u0643 \\u062A\\u0631\\u062A\\u0627\\u062D. \\u0645\\u0627 \\u0631\\u062D \\u062A\\u0646\\u0632\\u0644 \\u0645\\u0646 \\u0639\\u064A\\u0646\\u064A."
t["Shut the hell up. You're right, but shut the hell up."] = "\\u0633\\u062F \\u0628\\u0648\\u0632\\u0643. \\u0645\\u0639\\u0643 \\u062D\\u0642\\u060C \\u0628\\u0633 \\u0633\\u062F \\u0628\\u0648\\u0632\\u0643."
t["Shut up. You're right, but shut up."] = "\\u0627\\u0633\\u0643\\u062A. \\u0645\\u0639\\u0643 \\u062D\\u0642\\u060C \\u0628\\u0633 \\u0627\\u0633\\u0643\\u062A."
t["Sign says check fuel before travel. Clear, practical, several weeks late."] = "\\u0627\\u0644\\u064A\\u0627\\u0641\\u0637\\u0629 \\u0628\\u062A\\u0642\\u0648\\u0644 \\u062A\\u0623\\u0643\\u062F \\u0645\\u0646 \\u0627\\u0644\\u0628\\u0646\\u0632\\u064A\\u0646 \\u0642\\u0628\\u0644 \\u0627\\u0644\\u0633\\u0641\\u0631. \\u0648\\u0627\\u0636\\u062D\\u0629 \\u0648\\u0639\\u0645\\u0644\\u064A\\u0629 \\u0648\\u0645\\u062A\\u0623\\u062E\\u0631\\u0629 \\u0623\\u0633\\u0627\\u0628\\u064A\\u0639."
t["Sign says clean rooms and friendly service. One of those may still be true."] = "\\u0627\\u0644\\u064A\\u0627\\u0641\\u0637\\u0629 \\u0628\\u062A\\u0642\\u0648\\u0644 \\u063A\\u0631\\u0641 \\u0646\\u0636\\u064A\\u0641\\u0629 \\u0648\\u062E\\u062F\\u0645\\u0629 \\u0644\\u0637\\u064A\\u0641\\u0629. \\u0648\\u062D\\u062F\\u0629 \\u0645\\u0646\\u0647\\u0645 \\u064A\\u0645\\u0643\\u0646 \\u0644\\u0633\\u0627 \\u0635\\u062D\\u064A\\u062D\\u0629."
t["Sign says remain calm and await instructions. I'm doing my part."] = "\\u0627\\u0644\\u064A\\u0627\\u0641\\u0637\\u0629 \\u0628\\u062A\\u0642\\u0648\\u0644 \\u0627\\u0647\\u062F\\u0648\\u0627 \\u0648\\u0627\\u0633\\u062A\\u0646\\u0648\\u0627 \\u0627\\u0644\\u062A\\u0639\\u0644\\u064A\\u0645\\u0627\\u062A. \\u0623\\u0646\\u0627 \\u0639\\u0645 \\u0642\\u0648\\u0645 \\u0628\\u062F\\u0648\\u0631\\u064A."
t["Sign says report symptoms promptly. We are a few weeks behind schedule."] = "\\u0627\\u0644\\u064A\\u0627\\u0641\\u0637\\u0629 \\u0628\\u062A\\u0642\\u0648\\u0644 \\u0628\\u0644\\u0651\\u063A \\u0639\\u0646 \\u0627\\u0644\\u0623\\u0639\\u0631\\u0627\\u0636 \\u0641\\u0648\\u0631\\u064B\\u0627. \\u0645\\u062A\\u0623\\u062E\\u0631\\u064A\\u0646 \\u0643\\u0627\\u0645 \\u0623\\u0633\\u0628\\u0648\\u0639."
t["Single contact at the moment."] = "\\u0648\\u0627\\u062D\\u062F \\u0628\\u0633 \\u0644\\u0647\\u0644\\u0623."
t["Single contact, poor angle. Reposition."] = "\\u0648\\u0627\\u062D\\u062F, \\u0648\\u0627\\u0644\\u0632\\u0627\\u0648\\u064A\\u0629 \\u0639\\u0627\\u0637\\u0644\\u0629. \\u063A\\u064A\\u0631 \\u0645\\u0637\\u0631\\u062D\\u0643."
t["Single contact. Check the corners too."] = "\\u0648\\u0627\\u062D\\u062F \\u0628\\u0633. \\u0634\\u0648\\u0641 \\u0627\\u0644\\u0632\\u0648\\u0627\\u064A\\u0627 \\u0643\\u0645\\u0627\\u0646."
t["Single target selected."] = "\\u0646\\u0642\\u064A\\u062A \\u0627\\u0644\\u0647\\u062F\\u0641."
t["Single target. Engaging!"] = "\\u0647\\u062F\\u0641 \\u0648\\u0627\\u062D\\u062F. \\u0639\\u0645 \\u0647\\u0627\\u062C\\u0645!"
t["Sit down and let me check you. Yes, that was an order."] = "\\u0627\\u0642\\u0639\\u062F \\u062E\\u0644\\u064A\\u0646\\u064A \\u0634\\u0648\\u0641\\u0643. \\u0625\\u064A\\u060C \\u0647\\u0627\\u062F \\u0643\\u0627\\u0646 \\u0623\\u0645\\u0631."
t["Sit down. Breathe. We're right here."] = "\\u0627\\u0642\\u0639\\u062F. \\u0627\\u062A\\u0646\\u0641\\u0633. \\u0646\\u062D\\u0646\\u0627 \\u0647\\u0648\\u0646."
t["Sitting down makes my brain stand up."] = "\\u0644\\u0645\\u0627 \\u0628\\u0642\\u0639\\u062F\\u060C \\u0639\\u0642\\u0644\\u064A \\u0628\\u064A\\u0648\\u0642\\u0641."
t["Sitting still is hard. Listening helps."] = "\\u0627\\u0644\\u0642\\u0639\\u062F\\u0629 \\u0635\\u0639\\u0628\\u0629. \\u0627\\u0644\\u0633\\u0645\\u0639 \\u0628\\u064A\\u0633\\u0627\\u0639\\u062F."
t["Sitting there like it owns the damn place. Stay clear."] = "\\u0642\\u0627\\u0639\\u062F \\u0643\\u0623\\u0646\\u0648 \\u0627\\u0644\\u0645\\u062D\\u0644 \\u0645\\u0644\\u0643 \\u0623\\u0628\\u0648\\u0647 \\u0627\\u0644\\u0645\\u0644\\u0639\\u0648\\u0646. \\u0627\\u0628\\u0639\\u062F."
t["Sitting there like it owns the darn place. Stay clear."] = "\\u0642\\u0627\\u0639\\u062F \\u0643\\u0623\\u0646\\u0648 \\u0627\\u0644\\u0645\\u062D\\u0644 \\u0645\\u0644\\u0643 \\u0623\\u0628\\u0648\\u0647. \\u0627\\u0628\\u0639\\u062F."
t["Sitting walker. Stay back; I'll make sure it stays down."] = "\\u0648\\u0627\\u062D\\u062F \\u0642\\u0627\\u0639\\u062F. \\u062E\\u0644\\u064A\\u0643 \\u0644\\u0648\\u0631\\u0627\\u060C \\u0623\\u0646\\u0627 \\u0628\\u062A\\u0623\\u0643\\u062F \\u0625\\u0646\\u0648 \\u0645\\u0627 \\u064A\\u0642\\u0648\\u0645."
t["Sitting zombie by the wall. Don't mistake it for furniture."] = "\\u0632\\u0648\\u0645\\u0628\\u064A \\u0642\\u0627\\u0639\\u062F \\u062C\\u0646\\u0628 \\u0627\\u0644\\u062D\\u064A\\u0637. \\u0644\\u0627 \\u062A\\u0641\\u0643\\u0631\\u0647 \\u0639\\u0641\\u0634."
t["Sitting zombie spotted. Treat it as a live contact."] = "\\u0634\\u0641\\u062A \\u0632\\u0648\\u0645\\u0628\\u064A \\u0642\\u0627\\u0639\\u062F. \\u0627\\u0639\\u062A\\u0628\\u0631\\u0647 \\u0639\\u0627\\u064A\\u0634 \\u0648\\u062E\\u0637\\u0631."
t["Situation report:"] = "\\u0622\\u062E\\u0631 \\u0627\\u0644\\u0623\\u062E\\u0628\\u0627\\u0631:"
t["Six or more! Don't stand still!"] = "\\u0633\\u062A\\u0629 \\u0623\\u0648 \\u0623\\u0643\\u062A\\u0631! \\u0644\\u0627 \\u062A\\u0648\\u0642\\u0641!"
t["Six or more. Start looking for another route."] = "\\u0633\\u062A\\u0629 \\u0623\\u0648 \\u0623\\u0643\\u062A\\u0631. \\u062F\\u0648\\u0631 \\u0639\\u0644\\u0649 \\u0637\\u0631\\u064A\\u0642 \\u062A\\u0627\\u0646\\u064A."
t["Six, maybe eight walkers in sight."] = "\\u0633\\u062A\\u0629, \\u064A\\u0645\\u0643\\u0646 \\u062A\\u0645\\u0627\\u0646\\u064A\\u0629 \\u0632\\u0648\\u0645\\u0628\\u064A \\u0645\\u0628\\u064A\\u0646\\u064A\\u0646."
t["Six-plus. Every strike should buy an escape step."] = "\\u0623\\u0643\\u062A\\u0631 \\u0645\\u0646 \\u0633\\u062A\\u0629. \\u0643\\u0644 \\u0636\\u0631\\u0628\\u0629 \\u0644\\u0627\\u0632\\u0645 \\u062A\\u0634\\u062A\\u0631\\u064A \\u062E\\u0637\\u0648\\u0629 \\u0647\\u0631\\u0628."
t["Slow and clean. Bad ground wastes good seed."] = "\\u0639\\u0627\\u0644\\u0647\\u062F\\u0627 \\u0648\\u0639\\u0627\\u0644\\u0646\\u0636\\u064A\\u0641. \\u0627\\u0644\\u0623\\u0631\\u0636 \\u0627\\u0644\\u0639\\u0627\\u0637\\u0644\\u0629 \\u0628\\u062A\\u0636\\u064A\\u0651\\u0639 \\u0627\\u0644\\u0628\\u0632\\u0627\\u0631 \\u0627\\u0644\\u0645\\u0646\\u064A\\u062D."
t["Slow and deliberate. I want a clear way back out."] = "\\u0639\\u0627\\u0644\\u0647\\u062F\\u0627 \\u0648\\u0628\\u0639\\u0642\\u0644. \\u0628\\u062F\\u064A \\u0637\\u0631\\u064A\\u0642 \\u0631\\u062C\\u0639\\u0629 \\u0648\\u0627\\u0636\\u062D\\u0629."
t["Slushie machine. Blue flavor. A mystery forever."] = "\\u0645\\u0643\\u0646\\u0629 \\u0627\\u0644\\u0633\\u0644\\u0627\\u0634. \\u0646\\u0643\\u0647\\u0629 \\u0632\\u0631\\u0642\\u0627. \\u0644\\u063A\\u0632 \\u0644\\u0644\\u0623\\u0628\\u062F."
t["Small group closing! Fall back!"] = "\\u062C\\u0645\\u0627\\u0639\\u0629 \\u0635\\u063A\\u064A\\u0631\\u0629 \\u0639\\u0645 \\u062A\\u0642\\u0631\\u0628! \\u0627\\u0631\\u062C\\u0639!"
t["Small group confirmed. Choose the ground."] = "\\u062C\\u0645\\u0627\\u0639\\u0629 \\u0635\\u063A\\u064A\\u0631\\u0629 \\u0623\\u0643\\u064A\\u062F. \\u0646\\u0642\\u064A \\u0627\\u0644\\u0645\\u0643\\u0627\\u0646 \\u0645\\u0646\\u064A\\u062D."
t["Small group has the advantage. Reposition."] = "\\u0627\\u0644\\u062C\\u0645\\u0627\\u0639\\u0629 \\u0627\\u0644\\u0635\\u063A\\u064A\\u0631\\u0629 \\u063A\\u0627\\u0644\\u0628\\u062A\\u0646\\u0627. \\u063A\\u064A\\u0631 \\u0645\\u0637\\u0631\\u062D\\u0643."
t["Small group! Hold the line!"] = "\\u062C\\u0645\\u0627\\u0639\\u0629 \\u0635\\u063A\\u064A\\u0631\\u0629! \\u0627\\u062B\\u0628\\u062A!"
t["Small group. Do not chase into them."] = "\\u062C\\u0645\\u0627\\u0639\\u0629 \\u0635\\u063A\\u064A\\u0631\\u0629. \\u0644\\u0627 \\u062A\\u0641\\u0648\\u062A \\u0628\\u064A\\u0646\\u0627\\u062A\\u0646."
t["Small group. Mark the way back."] = "\\u062C\\u0645\\u0627\\u0639\\u0629 \\u0635\\u063A\\u064A\\u0631\\u0629. \\u0639\\u0644\\u0645 \\u0637\\u0631\\u064A\\u0642 \\u0627\\u0644\\u0631\\u062C\\u0639\\u0629."
t["Small group. Three, maybe four."] = "\\u062C\\u0645\\u0627\\u0639\\u0629 \\u0635\\u063A\\u064A\\u0631\\u0629. \\u062A\\u0644\\u0627\\u062A\\u0629, \\u064A\\u0645\\u0643\\u0646 \\u0623\\u0631\\u0628\\u0639\\u0629."
t["Small group. Use the narrow ground."] = "\\u062C\\u0645\\u0627\\u0639\\u0629 \\u0635\\u063A\\u064A\\u0631\\u0629. \\u0627\\u0633\\u062A\\u063A\\u0644 \\u0627\\u0644\\u0645\\u0637\\u0631\\u062D \\u0627\\u0644\\u0636\\u064A\\u0642."
t["Small pack ahead."] = "\\u0642\\u0637\\u064A\\u0639 \\u0635\\u063A\\u064A\\u0631 \\u0642\\u062F\\u0627\\u0645\\u0646\\u0627."
t["Small pack. Make them come through us one at a time!"] = "\\u0642\\u0637\\u064A\\u0639 \\u0635\\u063A\\u064A\\u0631. \\u062E\\u0644\\u064A\\u0647\\u0646 \\u064A\\u062C\\u0648\\u0627 \\u0648\\u0627\\u062D\\u062F \\u0648\\u0631\\u0627 \\u0648\\u0627\\u062D\\u062F!"
t["Small pack. We break them apart first."] = "\\u0642\\u0637\\u064A\\u0639 \\u0635\\u063A\\u064A\\u0631. \\u0623\\u0648\\u0644 \\u0634\\u064A \\u0645\\u0646\\u0641\\u0631\\u0642\\u0646."
t["Small pack. We break them here!"] = "\\u0642\\u0637\\u064A\\u0639 \\u0635\\u063A\\u064A\\u0631. \\u0647\\u0648\\u0646 \\u0645\\u0646\\u0643\\u0633\\u0631\\u0646!"
